(window.JUR_IMPORT = window.JUR_IMPORT || []).push([{"tribunal": "STJ", "n": "1", "texto": "O foro do domicilio ou da residencia do alimentando e o competente para a ação de investigação de paternidade, quando cumulada com a de alimentos.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Segunda Seção", "data": "25/04/1990"}, {"tribunal": "STJ", "n": "2", "texto": "Não cabe o habeas data (cf, art. 5., lxxii, letra \"a\") se não houve recusa de informações por parte da autoridade administrativa.", "vinculante": false, "materia": "Direito Processual Civil – Habeas Data", "orgao": "Primeira Seção", "data": "08/05/1990"}, {"tribunal": "STJ", "n": "3", "texto": "Compete ao tribunal regional federal dirimir conflito de competencia verificado, na respectiva região, entre juiz federal e juiz estadual investido de jurisdição federal.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Primeira Seção", "data": "08/05/1990"}, {"tribunal": "STJ", "n": "4", "texto": "Compete a justiça estadual julgar causa decorrente do processo eleitoral sindical.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Primeira Seção", "data": "08/05/1990"}, {"tribunal": "STJ", "n": "5", "texto": "A simples interpretação de clausula contratual não enseja recurso especial.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "10/05/1990"}, {"tribunal": "STJ", "n": "6", "texto": "Compete a justiça comum estadual processar e julgar delito decorrente de acidente de transito envolvendo viatura de policia militar, salvo se autor e vitima forem policiais militares em situação de atividade.", "vinculante": false, "materia": "Direito Processual Penal – Competência", "orgao": "Terceira Seção", "data": "07/06/1990"}, {"tribunal": "STJ", "n": "7", "texto": "A pretensão de simples reexame de prova não enseja recurso especial.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "28/06/1990"}, {"tribunal": "STJ", "n": "8", "texto": "Aplica-se a correção monetaria aos creditos habilitados em concordata preventiva, salvo durante o periodo compreendido entre as datas de vigencia da lei 7.274, de 10-12-84, e do decreto-lei 2.283, de 27-02-86.", "vinculante": false, "materia": "Direito Empresarial – Falência e Concordata", "orgao": "Segunda Seção", "data": "29/08/1990"}, {"tribunal": "STJ", "n": "9", "texto": "A exigencia da prisão provisoria, para apelar, não ofende a garantia constitucional da presunção de inocencia.", "vinculante": false, "materia": "Direito Processual Penal – Prisão Provisória", "orgao": "Terceira Seção", "data": "06/09/1990"}, {"tribunal": "STJ", "n": "10", "texto": "Instalada a junta de conciliação e julgamento, cessa a competencia do juiz de direito em materia trabalhista, inclusive para a execução das sentenças por ele proferidas.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Segunda Seção", "data": "26/09/1990"}, {"tribunal": "STJ", "n": "11", "texto": "A presença da união ou de qualquer de seus entes, na ação de usucapião especial, não afasta a competencia do foro da situação do imovel.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Segunda Seção", "data": "26/09/1990"}, {"tribunal": "STJ", "n": "12", "texto": "Em desapropriação, são cumulaveis juros compensatorios e moratorios.", "vinculante": false, "materia": "Direito Administrativo – Desapropriação", "orgao": "Primeira Seção", "data": "30/10/1990"}, {"tribunal": "STJ", "n": "13", "texto": "A divergencia entre julgados do mesmo tribunal não enseja recurso especial.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "08/11/1990"}, {"tribunal": "STJ", "n": "14", "texto": "Arbitrados os honorarios advocaticios em percentual sobre o valor da causa, a correção monetaria incide a partir do respectivo ajuizamento.", "vinculante": false, "materia": "Direito Processual Civil – Honorários Advocatícios", "orgao": "Corte Especial", "data": "08/11/1990"}, {"tribunal": "STJ", "n": "15", "texto": "Compete a justiça estadual processar e julgar os litigios decorrentes de acidente do trabalho.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Corte Especial", "data": "08/11/1990"}, {"tribunal": "STJ", "n": "16", "texto": "A legislação ordinaria sobre credito rural não veda a incidencia da correção monetaria.", "vinculante": false, "materia": "Direito Bancário – Contrato Bancário", "orgao": "Segunda Seção", "data": "14/11/1990"}, {"tribunal": "STJ", "n": "17", "texto": "Quando o falso se exaure no estelionato, sem mais potencialidade lesiva, e por este absorvido.", "vinculante": false, "materia": "Direito Penal – Tipificação Penal", "orgao": "Terceira Seção", "data": "20/11/1990"}, {"tribunal": "STJ", "n": "18", "texto": "A sentença concessiva do perdão judicial é declaratória da extinção da punibilidade, não subsistindo qualquer efeito condenatório.", "vinculante": false, "materia": "Direito Penal – Extinção da Punibilidade", "orgao": "Terceira Seção", "data": "20/11/1990"}, {"tribunal": "STJ", "n": "19", "texto": "A fixação do horario bancario, para atendimento ao publico, e da competencia da união.", "vinculante": false, "materia": "Direito Bancário – Sistema Financeiro Nacional", "orgao": "Primeira Seção", "data": "04/12/1990"}, {"tribunal": "STJ", "n": "20", "texto": "A mercadoria importada de pais signatario do gatt e isenta do icm, quando contemplado com esse favor o similar nacional.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Circulação de Mercadorias e Serviços", "orgao": "Primeira Seção", "data": "04/12/1990"}, {"tribunal": "STJ", "n": "21", "texto": "Pronunciado o reu, fica superada a alegação do constrangimento ilegal da prisão por excesso de prazo na instrução.", "vinculante": false, "materia": "Direito Processual Penal – Constrangimento Ilegal", "orgao": "Terceira Seção", "data": "06/12/1990"}, {"tribunal": "STJ", "n": "22", "texto": "Não ha conflito de competencia entre o tribunal de justiça e tribunal de alçada do mesmo estado-membro.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Corte Especial", "data": "13/12/1990"}, {"tribunal": "STJ", "n": "23", "texto": "O banco central do brasil é parte legítima nas ações fundadas na resolução 1154, de 1986.", "vinculante": false, "materia": "Direito Tributário – Empréstimo Compulsório", "orgao": "Primeira Seção", "data": "19/03/1991"}, {"tribunal": "STJ", "n": "24", "texto": "Aplica-se ao crime de estelionato, em que figure como vítima entidade autárquica da previdência social, a qualificadora do § 3º, do art. 171 do codigo penal.", "vinculante": false, "materia": "Direito Penal – Tipificação Penal", "orgao": "Terceira Seção", "data": "04/04/1991"}, {"tribunal": "STJ", "n": "25", "texto": "Nas ações da lei de falencias o prazo para a interposição de recurso conta-se da intimação da parte.", "vinculante": false, "materia": "Direito Empresarial – Falência e Concordata", "orgao": "Segunda Seção", "data": "10/04/1991"}, {"tribunal": "STJ", "n": "26", "texto": "O avalista do titulo de credito vinculado a contrato de mutuo tambem responde pelas obrigações pactuadas, quando no contrato figurar como devedor solidario.", "vinculante": false, "materia": "Direito Empresarial – Títulos de Crédito", "orgao": "Segunda Seção", "data": "12/06/1991"}, {"tribunal": "STJ", "n": "27", "texto": "Pode a execução fundar-se em mais de um titulo extrajudicial relativos ao mesmo negocio.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Segunda Seção", "data": "12/06/1991"}, {"tribunal": "STJ", "n": "28", "texto": "O contrato de alienação fiduciaria em garantia pode ter por objeto bem que ja integrava o patrimonio do devedor.", "vinculante": false, "materia": "Direito Bancário – Contrato Com Garantia de Alienação Fiduciária", "orgao": "Segunda Seção", "data": "25/09/1991"}, {"tribunal": "STJ", "n": "29", "texto": "No pagamento em juizo para elidir falencia, são devidos correção monetaria, juros e honorarios de advogado.", "vinculante": false, "materia": "Direito Empresarial – Falência e Concordata", "orgao": "Segunda Seção", "data": "09/10/1991"}, {"tribunal": "STJ", "n": "30", "texto": "A comissão de permanencia e a correção monetaria são inacumulaveis.", "vinculante": false, "materia": "Direito Bancário – Contrato Bancário", "orgao": "Segunda Seção", "data": "09/10/1991"}, {"tribunal": "STJ", "n": "31", "texto": "A aquisição, pelo segurado, de mais de um imovel financiado pelo sistema financeiro da habitação, situados na mesma localidade, não exime a seguradora da obrigação de pagamento dos seguros.", "vinculante": false, "materia": "Direito Bancário – Sistema Financeiro da Habitação", "orgao": "Segunda Seção", "data": "09/10/1991"}, {"tribunal": "STJ", "n": "32", "texto": "Compete a justiça federal processar justificações judiciais destinadas a instruir pedidos perante entidades que nela tem exclusividade de foro, ressalvada a aplicação do art. 15, ii da lei 5010/66.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Corte Especial", "data": "24/10/1991"}, {"tribunal": "STJ", "n": "33", "texto": "A incompetencia relativa não pode ser declarada de oficio.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Corte Especial", "data": "24/10/1991"}, {"tribunal": "STJ", "n": "34", "texto": "Compete a justiça estadual processar e julgar causa relativa a mensalidade escolar, cobrada por estabelecimento particular de ensino.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Segunda Seção", "data": "13/11/1991"}, {"tribunal": "STJ", "n": "35", "texto": "Incide correção monetaria sobre as prestações pagas, quando de sua restituição, em virtude da retirada ou exclusão do participante de plano de consorcio.", "vinculante": false, "materia": "Direito do Consumidor – Consórcio", "orgao": "Segunda Seção", "data": "13/11/1991"}, {"tribunal": "STJ", "n": "36", "texto": "A correção monetaria integra o valor da restituição, em caso de adiantamento de cambio, requerida em concordata ou falencia.", "vinculante": false, "materia": "Direito Empresarial – Falência e Concordata", "orgao": "Segunda Seção", "data": "11/12/1991"}, {"tribunal": "STJ", "n": "37", "texto": "São cumulaveis as indenizações por dano material e dano moral oriundos do mesmo fato.", "vinculante": false, "materia": "Direito Civil – Dano Moral", "orgao": "Corte Especial", "data": "12/03/1992"}, {"tribunal": "STJ", "n": "38", "texto": "Compete a justiça estadual comum, na vigencia da constituição de 1988, o processo por contravenção penal, ainda que praticada em detrimento de bens, serviços ou interesse da união ou de suas entidades.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Terceira Seção", "data": "19/03/1992"}, {"tribunal": "STJ", "n": "39", "texto": "Prescreve em vinte anos a ação para haver indenização, por responsabilidade civil, de sociedade de economia mista.", "vinculante": false, "materia": "Direito Administrativo – Prescrição e Decadência", "orgao": "Segunda Seção", "data": "08/04/1992"}, {"tribunal": "STJ", "n": "40", "texto": "Para obtenção dos beneficios de saida temporaria e trabalho externo, considera-se o tempo de cumprimento da pena no regime fechado.", "vinculante": false, "materia": "Direito Penal – Execução Penal", "orgao": "Terceira Seção", "data": "07/05/1992"}, {"tribunal": "STJ", "n": "41", "texto": "O superior tribunal de justiça não tem competencia para processar e julgar, originariamente, mandado de segurança contra ato de outros tribunais ou dos respectivos orgãos.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Corte Especial", "data": "14/05/1992"}, {"tribunal": "STJ", "n": "42", "texto": "Compete a justiça comum estadual processar e julgar as causas civeis em que e parte sociedade de economia mista e os crimes praticados em seu detrimento.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Corte Especial", "data": "14/05/1992"}, {"tribunal": "STJ", "n": "43", "texto": "Incide correção monetaria sobre divida por ato ilicito a partir da data do efetivo prejuizo.", "vinculante": false, "materia": "Direito Civil – Responsabilidade Civil", "orgao": "Corte Especial", "data": "14/05/1992"}, {"tribunal": "STJ", "n": "44", "texto": "A definição, em ato regulamentar, de grau minimo de disacusia, não exclui, por si so, a concessão do beneficio previdenciario.", "vinculante": false, "materia": "Direito Previdenciário – dos Benefícios Previdenciários", "orgao": "Primeira Seção", "data": "16/06/1992"}, {"tribunal": "STJ", "n": "45", "texto": "No reexame necessario, e defeso, ao tribunal, agravar a condenação imposta a fazenda publica.", "vinculante": false, "materia": "Direito Processual Civil – Reexame Necessário", "orgao": "Primeira Seção", "data": "16/06/1992"}, {"tribunal": "STJ", "n": "46", "texto": "Na execução por carta, os embargos do devedor serão decididos no juizo deprecante, salvo se versarem unicamente vicios ou defeitos da penhora, avaliação ou alienação dos bens.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Corte Especial", "data": "13/08/1992"}, {"tribunal": "STJ", "n": "47", "texto": "Compete a justiça militar processar e julgar crime cometido por militar contra civil, com emprego de arma pertencente a corporação, mesmo não estando em serviço.", "vinculante": false, "materia": "Direito Processual Penal – Competência", "orgao": "Terceira Seção", "data": "20/08/1992"}, {"tribunal": "STJ", "n": "48", "texto": "Compete ao juizo do local da obtenção da vantagem ilicita processar e julgar crime de estelionato cometido mediante falsificação de cheque.", "vinculante": false, "materia": "Direito Processual Penal – Competência", "orgao": "Terceira Seção", "data": "20/08/1992"}, {"tribunal": "STJ", "n": "49", "texto": "Na exportação de cafe em grão, não se inclui na base de calculo do icm a quota de contribuição, a que e refere o art. 2. Do decreto-lei 2.295, de 21.11.86.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Circulação de Mercadorias e Serviços", "orgao": "Primeira Seção", "data": "08/09/1992"}, {"tribunal": "STJ", "n": "50", "texto": "O adicional de tarifa portuaria incide apenas nas operações realizadas com mercadorias importadas ou exportadas, objeto do comercio de navegação de longo curso.", "vinculante": false, "materia": "Direito Tributário – Adicional de Tarifa Portuária", "orgao": "Primeira Seção", "data": "08/09/1992"}, {"tribunal": "STJ", "n": "51", "texto": "A punição do intermediador, no jogo do bicho, independe da identificação do \" apostador\" ou do \"banqueiro\".", "vinculante": false, "materia": "Direito Penal – Tipificação Penal", "orgao": "Terceira Seção", "data": "17/09/1992"}, {"tribunal": "STJ", "n": "52", "texto": "Encerrada a instrução criminal, fica superada a alegação de constrangimento por excesso de prazo.", "vinculante": false, "materia": "Direito Processual Penal – Constrangimento Ilegal", "orgao": "Terceira Seção", "data": "17/09/1992"}, {"tribunal": "STJ", "n": "53", "texto": "Compete a justiça comum estadual processar e julgar civil acusado de pratica de crime contra instituições militares estaduais.", "vinculante": false, "materia": "Direito Processual Penal – Competência", "orgao": "Terceira Seção", "data": "17/09/1992"}, {"tribunal": "STJ", "n": "54", "texto": "Os juros moratorios fluem a partir do evento danoso, em caso de responsabilidade extracontratual.", "vinculante": false, "materia": "Direito Civil – Responsabilidade Civil", "orgao": "Corte Especial", "data": "24/09/1992"}, {"tribunal": "STJ", "n": "55", "texto": "Tribunal regional federal não e competente para julgar recurso de decisão proferida por juiz estadual não investido de jurisdição federal.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Corte Especial", "data": "24/09/1992"}, {"tribunal": "STJ", "n": "56", "texto": "Na desapropriação para instituir servidão administrativa são devidos os juros compensatorios pela limitação de uso da propriedade.", "vinculante": false, "materia": "Direito Administrativo – Desapropriação", "orgao": "Primeira Seção", "data": "29/09/1992"}, {"tribunal": "STJ", "n": "57", "texto": "Compete a justiça comum estadual processar e julgar ação de cumprimento fundada em acordo ou convenção coletiva não homologados pela justiça do trabalho.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Primeira Seção", "data": "29/09/1992"}, {"tribunal": "STJ", "n": "58", "texto": "Proposta a execução fiscal, a posterior mudança de domicilio do executado não desloca a competencia ja fixada.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Primeira Seção", "data": "29/09/1992"}, {"tribunal": "STJ", "n": "59", "texto": "Não ha conflito de competencia se ja existe sentença com transito em julgado, proferida por um dos juizos conflitantes.", "vinculante": false, "materia": "Direito Processual Penal – Competência", "orgao": "Corte Especial", "data": "08/10/1992"}, {"tribunal": "STJ", "n": "60", "texto": "E nula a obrigação cambial assumida por procurador do mutuario vinculado ao mutuante, no exclusivo interesse deste.", "vinculante": false, "materia": "Direito Empresarial – Títulos de Crédito", "orgao": "Segunda Seção", "data": "14/10/1992"}, {"tribunal": "STJ", "n": "61", "texto": "O SEGURO DE VIDA COBRE O SUICIDIO NÃO PREMEDITADO. A Segunda Seção, na sessão de 25 de abril de 2018, ao apreciar o Projeto de Súmula n. 1.154, determinou o CANCELAMENTO da Súmula n. 61-STJ.", "vinculante": false, "materia": "Direito Civil – Contrato de Seguro", "orgao": "Segunda Seção", "data": "14/10/1992"}, {"tribunal": "STJ", "n": "62", "texto": "Compete a justiça estadual processar e julgar o crime de falsa anotação na carteira de trabalho e previdencia social, atribuido a empresa privada.", "vinculante": false, "materia": "Direito Processual Penal – Competência", "orgao": "Terceira Seção", "data": "19/11/1992"}, {"tribunal": "STJ", "n": "63", "texto": "São devidos direitos autorais pela retransmissão radiofonica de musicas em estabelecimentos comerciais.", "vinculante": false, "materia": "Direito Civil – Direito Autoral", "orgao": "Segunda Seção", "data": "25/11/1992"}, {"tribunal": "STJ", "n": "64", "texto": "Não constitui constrangimento ilegal o excesso de prazo na instrução, provocado pela defesa.", "vinculante": false, "materia": "Direito Processual Penal – Constrangimento Ilegal", "orgao": "Terceira Seção", "data": "03/12/1992"}, {"tribunal": "STJ", "n": "65", "texto": "O cancelamento, previsto no art. 29 do decreto-lei 2.303, de 21.11.86, não alcança os debitos previdenciarios.", "vinculante": false, "materia": "Direito Previdenciário – Débitos Previdenciários", "orgao": "Primeira Seção", "data": "15/12/1992"}, {"tribunal": "STJ", "n": "66", "texto": "Compete a justiça federal processar e julgar execução fiscal promovida por conselho de fiscalização profissional.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Primeira Seção", "data": "15/12/1992"}, {"tribunal": "STJ", "n": "67", "texto": "Na desapropriação, cabe a atualização monetaria, ainda que por mais de uma vez, independente do decurso de prazo superior a um ano entre o calculo e o efetivo pagamento da indenização.", "vinculante": false, "materia": "Direito Administrativo – Desapropriação", "orgao": "Primeira Seção", "data": "15/12/1992"}, {"tribunal": "STJ", "n": "68", "texto": "A PARCELA RELATIVA AO ICM INCLUI-SE NA BASE DE CALCULO DO PIS. A Primeira Seção, na sessão de 27 de março de 2019, ao julgar a Questão de Ordem nos REsps 1.624.297-RS, 1.629.001-SC e 1.638.772-SC, determinou o CANCELAMENTO da Súmula n. 68-STJ.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Circulação de Mercadorias e Serviços", "orgao": "Primeira Seção", "data": "15/12/1992"}, {"tribunal": "STJ", "n": "69", "texto": "Na desapropriação direta, os juros compensatorios são devidos desde a antecipada imissão na posse e, na desapropriação indireta, a partir da efetiva ocupação do imovel.", "vinculante": false, "materia": "Direito Administrativo – Desapropriação", "orgao": "Primeira Seção", "data": "15/12/1992"}, {"tribunal": "STJ", "n": "70", "texto": "Os juros moratorios, na desapropriação direta ou indireta, contam-se desde o transito em julgado da sentença.", "vinculante": false, "materia": "Direito Administrativo – Desapropriação", "orgao": "Primeira Seção", "data": "15/12/1992"}, {"tribunal": "STJ", "n": "71", "texto": "O bacalhau importado de pais signatario do gatt e isento do icm.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Circulação de Mercadorias e Serviços", "orgao": "Primeira Seção", "data": "15/12/1992"}, {"tribunal": "STJ", "n": "72", "texto": "A comprovação da mora e imprescindivel a busca e apreensão do bem alienado fiduciariamente.", "vinculante": false, "materia": "Direito Bancário – Contrato Com Garantia de Alienação Fiduciária", "orgao": "Segunda Seção", "data": "14/04/1993"}, {"tribunal": "STJ", "n": "73", "texto": "A utilização de papel moeda grosseiramente falsificado configura, em tese, o crime de estelionato, da competencia da justiça estadual.", "vinculante": false, "materia": "Direito Penal – Tipificação Penal", "orgao": "Terceira Seção", "data": "15/04/1993"}, {"tribunal": "STJ", "n": "74", "texto": "Para efeitos penais, o reconhecimento da menoridade do reu requer prova por documento habil.", "vinculante": false, "materia": "Direito Penal – das Penas", "orgao": "Terceira Seção", "data": "15/04/1993"}, {"tribunal": "STJ", "n": "75", "texto": "Compete a justiça comum estadual processar e julgar o policial militar por crime de promover ou facilitar a fuga de preso de estabelecimento penal.", "vinculante": false, "materia": "Direito Processual Penal – Competência", "orgao": "Terceira Seção", "data": "15/04/1993"}, {"tribunal": "STJ", "n": "76", "texto": "A falta de registro do compromisso de compra e venda de imovel não dispensa a previa interpelação para constituir em mora o devedor.", "vinculante": false, "materia": "Direito do Consumidor – Contrato de Compra e Venda de Imóvel", "orgao": "Segunda Seção", "data": "28/04/1993"}, {"tribunal": "STJ", "n": "77", "texto": "A caixa economica federal e parte ilegitima para figurar no polo passivo das ações relativas as contribuições para o fundo pis/pasep.", "vinculante": false, "materia": "Direito Previdenciário – Ações Previdenciárias", "orgao": "Primeira Seção", "data": "04/05/1993"}, {"tribunal": "STJ", "n": "78", "texto": "Compete a justiça militar processar e julgar policial de corporação estadual, ainda que o delito tenha sido praticado em outra unidade federativa.", "vinculante": false, "materia": "Direito Processual Penal – Competência", "orgao": "Terceira Seção", "data": "08/06/1993"}, {"tribunal": "STJ", "n": "79", "texto": "Os bancos comerciais não estão sujeitos a registro nos conselhos regionais de economia.", "vinculante": false, "materia": "Direito Bancário – Sistema Financeiro Nacional", "orgao": "Primeira Seção", "data": "08/06/1993"}, {"tribunal": "STJ", "n": "80", "texto": "A taxa de melhoramento dos portos não se inclui na base de calculo do icms.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Circulação de Mercadorias e Serviços", "orgao": "Primeira Seção", "data": "15/06/1993"}, {"tribunal": "STJ", "n": "81", "texto": "Não se concede fiança quando, em concurso material, a soma das penas minimas cominadas for superior a dois anos de reclusão.", "vinculante": false, "materia": "Direito Processual Penal – Fiança", "orgao": "Terceira Seção", "data": "17/06/1993"}, {"tribunal": "STJ", "n": "82", "texto": "Compete a justiça federal, excluidas as reclamações trabalhistas, processar e julgar os feitos relativos a movimentação do fgts.", "vinculante": false, "materia": "Direito Administrativo – Fundo de Garantia Por Tempo de Serviço", "orgao": "Corte Especial", "data": "18/06/1993"}, {"tribunal": "STJ", "n": "83", "texto": "Não se conhece do recurso especial pela divergencia, quando a orientação do tribunal se firmou no mesmo sentido da decisão recorrida.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "18/06/1993"}, {"tribunal": "STJ", "n": "84", "texto": "E admissivel a oposição de embargos de terceiro fundados em alegação de posse advinda do compromisso de compra e venda de imovel, ainda que desprovido do registro.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Corte Especial", "data": "18/06/1993"}, {"tribunal": "STJ", "n": "85", "texto": "Nas relações juridicas de trato sucessivo em que a fazenda publica figure como devedora, quando não tiver sido negado o proprio direito reclamado, a prescrição atinge apenas as prestações vencidas antes do quinquenio anterior a propositura da ação.", "vinculante": false, "materia": "Direito Administrativo – Prescrição e Decadência", "orgao": "Corte Especial", "data": "18/06/1993"}, {"tribunal": "STJ", "n": "86", "texto": "Cabe recurso especial contra acordão proferido no julgamento de agravo de instrumento.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "18/06/1993"}, {"tribunal": "STJ", "n": "87", "texto": "A isenção do icms relativa a rações balanceadas para animais abrange o concentrado e o suplemento.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Circulação de Mercadorias e Serviços", "orgao": "Primeira Seção", "data": "28/09/1993"}, {"tribunal": "STJ", "n": "88", "texto": "São admissiveis embargos infringentes em processo falimentar.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Segunda Seção", "data": "29/09/1993"}, {"tribunal": "STJ", "n": "89", "texto": "A ação acidentaria prescinde do exaurimento da via administrativa.", "vinculante": false, "materia": "Direito Processual Civil – Ação Acidentária", "orgao": "Terceira Seção", "data": "21/10/1993"}, {"tribunal": "STJ", "n": "90", "texto": "Compete a justiça estadual militar processar e julgar o policial militar pela pratica do crime militar, e a comum pela pratica do crime comum simultaneo aquele.", "vinculante": false, "materia": "Direito Processual Penal – Competência", "orgao": "Terceira Seção", "data": "21/10/1993"}, {"tribunal": "STJ", "n": "91", "texto": "COMPETE A JUSTIÇA FEDERAL PROCESSAR E JULGAR OS CRIMES PRATICADOS CONTRA A FAUNA. Na sessão de 08/11/2000, a Terceira Seção deliberou pelo CANCELAMENTO da Súmula n. 91.", "vinculante": false, "materia": "Direito Processual Penal – Competência", "orgao": "Terceira Seção", "data": "08/11/2000"}, {"tribunal": "STJ", "n": "92", "texto": "A terceiro de boa-fe não e oponivel a alienação fiduciaria não anotada no certificado de registro do veiculo automotor.", "vinculante": false, "materia": "Direito Bancário – Contrato Com Garantia de Alienação Fiduciária", "orgao": "Segunda Seção", "data": "27/10/1993"}, {"tribunal": "STJ", "n": "93", "texto": "A legislação sobre cedulas de credito rural, comercial e industrial admite o pacto de capitalização de juros.", "vinculante": false, "materia": "Direito Bancário – Contrato Bancário", "orgao": "Segunda Seção", "data": "27/10/1993"}, {"tribunal": "STJ", "n": "94", "texto": "A PARCELA RELATIVA AO ICMS INCLUI-SE NA BASE DE CALCULO DO FINSOCIAL. A Primeira Seção, na sessão de 27 de março de 2019, ao julgar a Questão de Ordem nos REsps 1.624.297-RS, 1.629.001-SC e 1.638.772-SC, determinou o CANCELAMENTO da Súmula n. 94-STJ.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Circulação de Mercadorias e Serviços", "orgao": "Primeira Seção", "data": "22/02/1994"}, {"tribunal": "STJ", "n": "95", "texto": "A redução da aliquota do imposto sobre produtos industrializados ou do imposto de importação não implica redução do icms.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Circulação de Mercadorias e Serviços", "orgao": "Primeira Seção", "data": "22/02/1994"}, {"tribunal": "STJ", "n": "96", "texto": "O crime de extorsão consuma-se independentemente da obtenção da vantagem indevida.", "vinculante": false, "materia": "Direito Penal – Tipificação Penal", "orgao": "Terceira Seção", "data": "03/03/1994"}, {"tribunal": "STJ", "n": "97", "texto": "Compete a justiça do trabalho processar e julgar reclamação de servidor publico relativamente a vantagens trabalhistas anteriores a instituição do regime juridico unico.", "vinculante": false, "materia": "Direito Administrativo – Servidor Público Civil", "orgao": "Terceira Seção", "data": "03/03/1994"}, {"tribunal": "STJ", "n": "98", "texto": "Embargos de declaração manifestados com notorio proposito de prequestionamento não tem carater protelatorio.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "14/04/1994"}, {"tribunal": "STJ", "n": "99", "texto": "O ministerio publico tem legitimidade para recorrer no processo em que oficiou como fiscal da lei, ainda que não haja recurso da parte.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "14/04/1994"}, {"tribunal": "STJ", "n": "100", "texto": "E devido o adicional ao frete para renovação da marinha mercante na importação sob o regime de beneficios fiscais a exportação (befiex).", "vinculante": false, "materia": "Direito Tributário – Adicional ao Frete Para Renovação da Marinha Mercante", "orgao": "Primeira Seção", "data": "19/04/1994"}, {"tribunal": "STJ", "n": "101", "texto": "A ação de indenização do segurado em grupo contra a seguradora prescreve em um ano.", "vinculante": false, "materia": "Direito Civil – Contrato de Seguro", "orgao": "Segunda Seção", "data": "27/04/1994"}, {"tribunal": "STJ", "n": "102", "texto": "A incidencia dos juros moratorios sobre os compensatorios, nas ações expropriatorias, não constitui anatocismo vedado em lei.", "vinculante": false, "materia": "Direito Administrativo – Desapropriação", "orgao": "Primeira Seção", "data": "17/05/1994"}, {"tribunal": "STJ", "n": "103", "texto": "Incluem-se entre os imoveis funcionais que podem ser vendidos os administrados pelas forças armadas e ocupados pelos servidores civis.", "vinculante": false, "materia": "Direito Administrativo – Bem Público", "orgao": "Terceira Seção", "data": "19/05/1994"}, {"tribunal": "STJ", "n": "104", "texto": "Compete a justiça estadual o processo e julgamento dos crimes de falsificação e uso de documento falso relativo a estabelecimento particular de ensino.", "vinculante": false, "materia": "Direito Processual Penal – Competência", "orgao": "Terceira Seção", "data": "19/05/1994"}, {"tribunal": "STJ", "n": "105", "texto": "Na ação de mandado de segurança não se admite condenação em honorarios advocaticios.", "vinculante": false, "materia": "Direito Processual Civil – Mandado de Segurança", "orgao": "Corte Especial", "data": "26/05/1994"}, {"tribunal": "STJ", "n": "106", "texto": "Proposta a ação no prazo fixado para o seu exercicio, a demora na citação, por motivos inerentes ao mecanismo da justiça, não justifica o acolhimento da arguição de prescrição ou decadencia.", "vinculante": false, "materia": "Direito Processual Civil – Citação", "orgao": "Corte Especial", "data": "26/05/1994"}, {"tribunal": "STJ", "n": "107", "texto": "Compete a justiça comum estadual processar e julgar crime de estelionato praticado mediante falsificação das guias de recolhimento das contribuições previdenciarias, quando não ocorrente lesão a autarquia federal.", "vinculante": false, "materia": "Direito Processual Penal – Competência", "orgao": "Terceira Seção", "data": "16/06/1994"}, {"tribunal": "STJ", "n": "108", "texto": "A aplicação de medidas socio-educativas ao adolescente, pela pratica de ato infracional, e da competencia exclusiva do juiz.", "vinculante": false, "materia": "Direito Penal – Estatuto da Criança e Do Adolescente", "orgao": "Terceira Seção", "data": "16/06/1994"}, {"tribunal": "STJ", "n": "109", "texto": "O reconhecimento do direito a indenização, por falta de mercadoria transportada via maritima, independe de vistoria.", "vinculante": false, "materia": "Direito Civil – Transporte Marítimo", "orgao": "Segunda Seção", "data": "28/09/1994"}, {"tribunal": "STJ", "n": "110", "texto": "A isenção do pagamento de honorarios advocaticios, nas ações acidentarias, e restrita ao segurado.", "vinculante": false, "materia": "Direito Processual Civil – Ações Previdenciárias", "orgao": "Terceira Seção", "data": "06/10/1994"}, {"tribunal": "STJ", "n": "111", "texto": "Os honorários advocatícios, nas ações previdenciárias, não incidem sobre as prestações vencidas após a sentença. (*) . (*) - apreciando o projeto de súmula n. 560, na sessão de 27/09/06, a Terceira Seção deliberou pela MODIFICAÇÃO da súmula n. 111. REDAÇÃO ANTERIOR (decisão de 06/10/1994, DJ 13/10/1994): OS HONORÁRIOS ADVOCATÍCIOS, NAS AÇÕES PREVIDENCIÁRIAS, NÃO INCIDEM SOBRE PRESTAÇÕES VINCENDAS.", "vinculante": false, "materia": "Direito Processual Civil – Ações Previdenciárias", "orgao": "Terceira Seção", "data": "27/09/2006"}, {"tribunal": "STJ", "n": "112", "texto": "O deposito somente suspende a exigibilidade do credito tributario se for integral e em dinheiro.", "vinculante": false, "materia": "Direito Tributário – Depósito", "orgao": "Primeira Seção", "data": "25/10/1994"}, {"tribunal": "STJ", "n": "113", "texto": "Os juros compensatorios, na desapropriação direta, incidem a partir da imissão na posse, calculados sobre o valor da indenização, corrigido monetariamente.", "vinculante": false, "materia": "Direito Administrativo – Desapropriação", "orgao": "Primeira Seção", "data": "25/10/1994"}, {"tribunal": "STJ", "n": "114", "texto": "Os juros compensatorios, na desapropriação indireta, incidem a partir da ocupação, calculados sobre o valor da indenização, corrigido monetariamente.", "vinculante": false, "materia": "Direito Administrativo – Desapropriação", "orgao": "Primeira Seção", "data": "25/10/1994"}, {"tribunal": "STJ", "n": "115", "texto": "Na instancia especial é inexistente recurso interposto por advogado sem procuração nos autos.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "27/10/1994"}, {"tribunal": "STJ", "n": "116", "texto": "A fazenda publica e o ministerio publico tem prazo em dobro para interpor agravo regimental no superior tribunal de justiça.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "27/10/1994"}, {"tribunal": "STJ", "n": "117", "texto": "A inobservancia do prazo de 48 horas, entre a publicação de pauta e o julgamento sem a presença das partes, acarreta nulidade.", "vinculante": false, "materia": "Direito Processual Civil – dos Prazos", "orgao": "Corte Especial", "data": "27/10/1994"}, {"tribunal": "STJ", "n": "118", "texto": "O agravo de instrumento é o recurso cabivel da decisão que homologa a atualização do calculo da liquidação.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "27/10/1994"}, {"tribunal": "STJ", "n": "119", "texto": "A ação de desapropriação indireta prescreve em vinte anos.", "vinculante": false, "materia": "Direito Administrativo – Desapropriação", "orgao": "Primeira Seção", "data": "08/11/1994"}, {"tribunal": "STJ", "n": "120", "texto": "O oficial de farmacia, inscrito no conselho regional de farmacia, pode ser responsavel tecnico por drogaria.", "vinculante": false, "materia": "Direito Administrativo – Atividade Farmacêutica", "orgao": "Primeira Seção", "data": "29/11/1994"}, {"tribunal": "STJ", "n": "121", "texto": "Na execução fiscal o devedor devera ser intimado, pessoalmente, do dia e hora da realização do leilão.", "vinculante": false, "materia": "Direito Processual Civil – Execução Fiscal", "orgao": "Primeira Seção", "data": "29/11/1994"}, {"tribunal": "STJ", "n": "122", "texto": "Compete a justiça federal o processo e julgamento unificado dos crimes conexos de competencia federal e estadual, não se aplicando a regra do art. 78, ii, \"a\", do codigo de processo penal.", "vinculante": false, "materia": "Direito Processual Penal – Competência", "orgao": "Terceira Seção", "data": "01/12/1994"}, {"tribunal": "STJ", "n": "123", "texto": "A decisão que admite, ou não, o recurso especial deve ser fundamentada, com o exame dos seus pressupostos gerais e constitucionais.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "02/12/1994"}, {"tribunal": "STJ", "n": "124", "texto": "A taxa de melhoramento dos portos tem base de calculo diversa do imposto de importação, sendo legitima a sua cobrança sobre a importação de mercadorias de paises signatarios do gatt, da alalc ou aladi.,", "vinculante": false, "materia": "Direito Tributário – Taxas", "orgao": "Primeira Seção", "data": "06/12/1994"}, {"tribunal": "STJ", "n": "125", "texto": "O pagamento de ferias não gozadas por necessidade do serviço não esta sujeito a incidencia do imposto de renda.", "vinculante": false, "materia": "Direito Tributário – Imposto de Renda", "orgao": "Primeira Seção", "data": "06/12/1994"}, {"tribunal": "STJ", "n": "126", "texto": "E inadmissivel recurso especial, quando o acordão recorrido assenta em fundamentos constitucional e infraconstitucional, qualquer deles suficiente, por si so, para mante-lo, e a parte vencida não manifesta recurso extraordinario.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "09/03/1995"}, {"tribunal": "STJ", "n": "127", "texto": "E ilegal condicionar a renovação da licença de veiculo ao pagamento de multa, da qual o infrator não foi notificado.", "vinculante": false, "materia": "Direito Administrativo – Código de Trânsito Brasileiro", "orgao": "Primeira Seção", "data": "14/03/1995"}, {"tribunal": "STJ", "n": "128", "texto": "Na execução fiscal haverá segundo leilão, se no primeiro não houver lanço superior a avaliação.", "vinculante": false, "materia": "Direito Processual Civil – Execução Fiscal", "orgao": "Primeira Seção", "data": "14/03/1995"}, {"tribunal": "STJ", "n": "129", "texto": "O exportador adquire o direito de transferencia de credito do icms quando realiza a exportação do produto e não ao estocar a materia-prima.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Circulação de Mercadorias e Serviços", "orgao": "Primeira Seção", "data": "14/03/1995"}, {"tribunal": "STJ", "n": "130", "texto": "A empresa responde, perante o cliente, pela reparação de dano ou furto de veiculo ocorridos em seu estacionamento.", "vinculante": false, "materia": "Direito Civil – Responsabilidade Civil", "orgao": "Segunda Seção", "data": "29/03/1995"}, {"tribunal": "STJ", "n": "131", "texto": "Nas ações de desapropriação incluem-se no calculo da verba advocaticia as parcelas relativas aos juros compensatorios e moratorios, devidamente corrigidas.", "vinculante": false, "materia": "Direito Administrativo – Desapropriação", "orgao": "Primeira Seção", "data": "18/04/1995"}, {"tribunal": "STJ", "n": "132", "texto": "A ausencia de registro da transferencia não implica a responsabilidade do antigo proprietario por dano resultante de acidente que envolva o veiculo alienado.", "vinculante": false, "materia": "Direito Civil – Responsabilidade Civil", "orgao": "Segunda Seção", "data": "26/04/1995"}, {"tribunal": "STJ", "n": "133", "texto": "A restituição da importancia adiantada, a conta de contrato de cambio, independe de ter sido a antecipação efetuada nos quinze dias anteriores ao requerimento da concordata.", "vinculante": false, "materia": "Direito Empresarial – Falência, Concordata e Recuperação Jucicial", "orgao": "Segunda Seção", "data": "26/04/1995"}, {"tribunal": "STJ", "n": "134", "texto": "Embora intimado da penhora em imovel do casal, o conjuge do executado pode opor embargos de terceiro para defesa de sua meação.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Segunda Seção", "data": "26/04/1995"}, {"tribunal": "STJ", "n": "135", "texto": "O icms não incide na gravação e distribuição de filmes e videoteipes.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Circulação de Mercadorias e Serviços", "orgao": "Primeira Seção", "data": "09/05/1995"}, {"tribunal": "STJ", "n": "136", "texto": "O pagamento de licença-premio não gozada por necessidade do serviço não esta sujeito ao imposto de renda.", "vinculante": false, "materia": "Direito Tributário – Imposto de Renda", "orgao": "Primeira Seção", "data": "09/05/1995"}, {"tribunal": "STJ", "n": "137", "texto": "Compete a justiça comum estadual processar e julgar ação de servidor publico municipal, pleiteando direitos relativos ao vinculo estatutario.", "vinculante": false, "materia": "Direito Administrativo – Servidor Público Civil", "orgao": "Corte Especial", "data": "11/05/1995"}, {"tribunal": "STJ", "n": "138", "texto": "O iss incide na operação de arrendamento mercantil de coisas moveis.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Serviços", "orgao": "Primeira Seção", "data": "16/05/1995"}, {"tribunal": "STJ", "n": "139", "texto": "Cabe a procuradoria da fazenda nacional propor execução fiscal para cobrança de credito relativo ao itr.", "vinculante": false, "materia": "Direito Processual Civil – Execução Fiscal", "orgao": "Primeira Seção", "data": "16/05/1995"}, {"tribunal": "STJ", "n": "140", "texto": "Compete a justiça comum estadual processar e julgar crime em que o indigena figure como autor ou vitima.", "vinculante": false, "materia": "Direito Processual Penal – Competência", "orgao": "Terceira Seção", "data": "18/05/1995"}, {"tribunal": "STJ", "n": "141", "texto": "Os honorarios de advogado em desapropriação direta são calculados sobre a diferença entre a indenização e a oferta, corrigidas monetariamente.", "vinculante": false, "materia": "Direito Administrativo – Desapropriação", "orgao": "Primeira Seção", "data": "06/06/1995"}, {"tribunal": "STJ", "n": "142", "texto": "PRESCREVE EM VINTE ANOS A AÇÃO PARA EXIGIR A ABSTENÇÃO DO USO DE MARCA COMERCIAL. Julgando a AR 512/DF, na sessão de 12.05.1999, a Segunda Seção deliberou pelo CANCELAMENTO da Súmula n. 142.", "vinculante": false, "materia": "Direito Empresarial – Marca Comercial", "orgao": "Segunda Seção", "data": "12/05/1999"}, {"tribunal": "STJ", "n": "143", "texto": "Prescreve em cinco anos a ação de perdas e danos pelo uso de marca comercial.", "vinculante": false, "materia": "Direito Empresarial – Marca Comercial", "orgao": "Segunda Seção", "data": "14/06/1995"}, {"tribunal": "STJ", "n": "144", "texto": "Os creditos de natureza alimenticia gozam de preferencia, desvinculados os precatorios da ordem cronologica dos creditos de natureza diversa.", "vinculante": false, "materia": "Direito Processual Civil – Precatório", "orgao": "Corte Especial", "data": "10/08/1995"}, {"tribunal": "STJ", "n": "145", "texto": "No transporte desinteressado, de simples cortesia, o transportador so sera civilmente responsavel por danos causados ao transportado quando incorrer em dolo ou culpa grave.", "vinculante": false, "materia": "Direito Civil – Responsabilidade Civil", "orgao": "Segunda Seção", "data": "08/11/1995"}, {"tribunal": "STJ", "n": "146", "texto": "O segurado, vitima de novo infortunio, faz jus a um unico beneficio somado ao salario de contribuição vigente no dia do acidente.", "vinculante": false, "materia": "Direito Previdenciário – dos Benefícios Previdenciários", "orgao": "Terceira Seção", "data": "07/12/1995"}, {"tribunal": "STJ", "n": "147", "texto": "Compete a justiça federal processar e julgar os crimes praticados contra funcionario publico federal, quando relacionados com o exercicio da função.", "vinculante": false, "materia": "Direito Processual Penal – Competência", "orgao": "Terceira Seção", "data": "07/12/1995"}, {"tribunal": "STJ", "n": "148", "texto": "Os debitos relativos a beneficio previdenciario, vencidos e cobrados em juizo apos a vigencia da lei nr. 6.899/81, devem ser corrigidos monetariamente na forma prevista nesse diploma legal.", "vinculante": false, "materia": "Direito Previdenciário – dos Benefícios Previdenciários", "orgao": "Terceira Seção", "data": "07/12/1995"}, {"tribunal": "STJ", "n": "149", "texto": "A prova exclusivamente testemunhal não basta a comprovação da atividade ruricola, para efeito da obtenção de beneficio previdenciario.", "vinculante": false, "materia": "Direito Previdenciário – Trabalho Rural", "orgao": "Terceira Seção", "data": "07/12/1995"}, {"tribunal": "STJ", "n": "150", "texto": "Compete a justiça federal decidir sobre a existencia de interesse juridico que justifique a presença, no processo, da união, suas autarquias ou empresas publicas.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Corte Especial", "data": "07/02/1996"}, {"tribunal": "STJ", "n": "151", "texto": "A competencia para o processo e julgamento por crime de contrabando ou descaminho define-se pela prevenção do juizo federal do lugar da apreensão dos bens.", "vinculante": false, "materia": "Direito Processual Penal – Competência", "orgao": "Terceira Seção", "data": "14/02/1996"}, {"tribunal": "STJ", "n": "152", "texto": "NA VENDA PELO SEGURADOR, DE BENS SALVADOS DE SINISTROS, INCIDE O ICMS. Julgando o REsp 73.552-RJ, na sessão de 13/6/2007, a Primeira Seção deliberou pelo CANCELAMENTO da Súmula n. 152.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Circulação de Mercadorias e Serviços", "orgao": "Primeira Seção", "data": "13/06/2007"}, {"tribunal": "STJ", "n": "153", "texto": "A desistencia da execução fiscal, apos o oferecimento dos embargos, não exime o exequente dos encargos da sucumbencia.", "vinculante": false, "materia": "Direito Processual Civil – Execução Fiscal", "orgao": "Primeira Seção", "data": "08/03/1996"}, {"tribunal": "STJ", "n": "154", "texto": "Os optantes pelo fgts, nos termos da lei n. 5.958, de 1973, tem direito a taxa progressiva dos juros, na forma do art. 4. Da lei n. 5.107, de 1966.", "vinculante": false, "materia": "Direito Administrativo – Fundo de Garantia Por Tempo de Serviço", "orgao": "Primeira Seção", "data": "22/03/1996"}, {"tribunal": "STJ", "n": "155", "texto": "O icms incide na importação de aeronave, por pessoa fisica, para uso proprio.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Circulação de Mercadorias e Serviços", "orgao": "Primeira Seção", "data": "22/03/1996"}, {"tribunal": "STJ", "n": "156", "texto": "A prestação de serviço de composição grafica, personalizada e sob encomenda, ainda que envolva fornecimento de mercadorias, esta sujeita, apenas, ao iss.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Serviços", "orgao": "Primeira Seção", "data": "22/03/1996"}, {"tribunal": "STJ", "n": "157", "texto": "É ilegítima a cobrança de taxa, pelo município, na renovação de licença para localização de estabelecimento comercial ou industrial. Julgando o RESP 261.571-SP, na sessão de 24/04/2002, a Primeira Seção deliberou pelo CANCELAMENTO da súmula n. 157.", "vinculante": false, "materia": "Direito Tributário – Taxas", "orgao": "Primeira Seção", "data": "24/04/2002"}, {"tribunal": "STJ", "n": "158", "texto": "Não se presta a justificar embargos de divergencia o dissidio com acordão de turma ou seção que não mais tenha competencia para a materia neles versada.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "15/05/1996"}, {"tribunal": "STJ", "n": "159", "texto": "O beneficio acidentario, no caso de contribuinte que perceba remuneração variavel, deve ser calculado com base na media aritmetica dos ultimos doze meses de contribuição.", "vinculante": false, "materia": "Direito Previdenciário – dos Benefícios Previdenciários", "orgao": "Corte Especial", "data": "15/05/1996"}, {"tribunal": "STJ", "n": "160", "texto": "E defeso, ao municipio, atualizar o iptu, mediante decreto, em percentual superior ao indice oficial de correção monetaria.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre a Propriedade Predial e Territorial Urbana", "orgao": "Primeira Seção", "data": "12/06/1996"}, {"tribunal": "STJ", "n": "161", "texto": "E da competencia da justiça estadual autorizar o levantamento dos valores relativos ao pis / pasep e fgts, em decorrencia do falecimento do titular da conta.", "vinculante": false, "materia": "Direito Administrativo – Fundo de Garantia Por Tempo de Serviço", "orgao": "Primeira Seção", "data": "12/06/1996"}, {"tribunal": "STJ", "n": "162", "texto": "Na repetição de indebito tributario, a correção monetaria incide a partir do pagamento indevido.", "vinculante": false, "materia": "Direito Tributário – Repetição de Indébito", "orgao": "Primeira Seção", "data": "12/06/1996"}, {"tribunal": "STJ", "n": "163", "texto": "O fornecimento de mercadorias com a simultanea prestação de serviços em bares, restaurantes e estabelecimentos similares constitui fato gerador do icms a incidir sobre o valor total da operação.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Circulação de Mercadorias e Serviços", "orgao": "Primeira Seção", "data": "12/06/1996"}, {"tribunal": "STJ", "n": "164", "texto": "O prefeito municipal, apos a extinção do mandato, continua sujeito a processo por crime previsto no art. 1. Do dec. Lei n. 201, de 27/02/67.", "vinculante": false, "materia": "Direito Processual Penal – Competência", "orgao": "Terceira Seção", "data": "14/08/1996"}, {"tribunal": "STJ", "n": "165", "texto": "Compete a justiça federal processar e julgar crime de falso testemunho cometido no processo trabalhista.", "vinculante": false, "materia": "Direito Processual Penal – Competência", "orgao": "Terceira Seção", "data": "14/08/1996"}, {"tribunal": "STJ", "n": "166", "texto": "Não constitui fato gerador do icms o simples deslocamento de mercadoria de um para outro estabelecimento do mesmo contribuinte.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Circulação de Mercadorias e Serviços", "orgao": "Primeira Seção", "data": "14/08/1996"}, {"tribunal": "STJ", "n": "167", "texto": "O fornecimento de concreto, por empreitada, para construção civil, preparado no trajeto ate a obra em betoneiras acopladas a caminhões, e prestação de serviço, sujeitando-se apenas a incidencia do iss.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Serviços", "orgao": "Primeira Seção", "data": "11/09/1996"}, {"tribunal": "STJ", "n": "168", "texto": "Não cabem embargos de divergencia, quando a jurisprudencia do tribunal se firmou no mesmo sentido do acordão embargado.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "16/10/1996"}, {"tribunal": "STJ", "n": "169", "texto": "São inadmissiveis embargos infringentes no processo de mandado de segurança.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "16/10/1996"}, {"tribunal": "STJ", "n": "170", "texto": "Compete ao juizo onde primeiro for intentada a ação envolvendo acumulação de pedidos, trabalhista e estatutario, decidi-la nos limites da sua jurisdição, sem prejuizo do ajuizamento de nova causa, com o pedido remanescente, no juizo proprio.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Terceira Seção", "data": "23/10/1996"}, {"tribunal": "STJ", "n": "171", "texto": "Cominadas cumulativamente, em lei especial, penas privativa de liberdade e pecuniaria, e defeso a substituição da prisão por multa.", "vinculante": false, "materia": "Direito Penal – das Penas", "orgao": "Terceira Seção", "data": "23/10/1996"}, {"tribunal": "STJ", "n": "172", "texto": "Compete a justiça comum processar e julgar militar por crime de abuso de autoridade, ainda que praticado em serviço.", "vinculante": false, "materia": "Direito Processual Penal – Competência", "orgao": "Terceira Seção", "data": "23/10/1996"}, {"tribunal": "STJ", "n": "173", "texto": "Compete a justiça federal processar e julgar o pedido de reintegração em cargo publico federal, ainda que o servidor tenha sido dispensado antes da instituição do regime juridico unico.", "vinculante": false, "materia": "Direito Administrativo – Servidor Público Civil", "orgao": "Terceira Seção", "data": "23/10/1996"}, {"tribunal": "STJ", "n": "174", "texto": "NO CRIME DE ROUBO, A INTIMIDAÇÃO FEITA COM ARMA DE BRINQUEDO AUTORIZA O AUMENTO DA PENA. Julgando o RESP 213.054-SP, na sessão de 24/10/2001, a Terceira Seção deliberou pelo CANCELAMENTO da súmula n. 174.", "vinculante": false, "materia": "Direito Penal – das Penas", "orgao": "Terceira Seção", "data": "24/10/2001"}, {"tribunal": "STJ", "n": "175", "texto": "Descabe o deposito previo nas ações rescisorias propostas pelo inss.", "vinculante": false, "materia": "Direito Processual Civil – Custas Processuais", "orgao": "Terceira Seção", "data": "23/10/1996"}, {"tribunal": "STJ", "n": "176", "texto": "E nula a clausula contratual que sujeita o devedor a taxa de juros divulgada pela anbid/cetip.", "vinculante": false, "materia": "Direito Bancário – Contrato Bancário", "orgao": "Segunda Seção", "data": "23/10/1996"}, {"tribunal": "STJ", "n": "177", "texto": "O superior tribunal de justiça é incompetente para processar e julgar, originariamente, mandado de segurança contra ato de órgão colegiado presidido por ministro de estado.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Primeira Seção", "data": "27/11/1996"}, {"tribunal": "STJ", "n": "178", "texto": "O inss não goza de isenção do pagamento de custas e emolumentos, nas ações acidentarias e de beneficios, propostas na justiça estadual.", "vinculante": false, "materia": "Direito Previdenciário – Ações Previdenciárias", "orgao": "Terceira Seção", "data": "11/12/1996"}, {"tribunal": "STJ", "n": "179", "texto": "O estabelecimento de credito que recebe dinheiro, em deposito judicial, responde pelo pagamento da correção monetaria relativa aos valores recolhidos.", "vinculante": false, "materia": "Direito Processual Civil – Depósito Judicial", "orgao": "Corte Especial", "data": "05/02/1997"}, {"tribunal": "STJ", "n": "180", "texto": "Na lide trabalhista, compete ao tribunal regional do trabalho dirimir conflito de competencia verificado, na respectiva região, entre juiz estadual e junta de conciliação e julgamento.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Corte Especial", "data": "05/02/1997"}, {"tribunal": "STJ", "n": "181", "texto": "E admissivel ação declaratoria, visando a obter certeza quanto a exata interpretação de clausula contratual.", "vinculante": false, "materia": "Direito Processual Civil – Ação Declaratória", "orgao": "Corte Especial", "data": "05/02/1997"}, {"tribunal": "STJ", "n": "182", "texto": "E inviavel o agravo do art. 545 do cpc que deixa de atacar especificamente os fundamentos da decisão agravada.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "05/02/1997"}, {"tribunal": "STJ", "n": "183", "texto": "COMPETE AO JUIZ ESTADUAL, NAS COMARCAS QUE NÃO SEJAM SEDE DE VARA DA JUSTIÇA FEDERAL, PROCESSAR E JULGAR AÇÃO CIVIL PUBLICA, AINDA QUE A UNIÃO FIGURE NO PROCESSO. Julgando os Embargos de Declaração no CC n. 27.676-BA, na sessão de 08/11/2000, a Primeira Seção deliberou pelo CANCELAMENTO da Súmula n. 183.", "vinculante": false, "materia": "Direito Processual Civil – Ação Civil Pública", "orgao": "Primeira Seção", "data": "08/11/2000"}, {"tribunal": "STJ", "n": "184", "texto": "A microempresa de representação comercial e isenta do imposto de renda.", "vinculante": false, "materia": "Direito Tributário – Imposto de Renda", "orgao": "Primeira Seção", "data": "12/03/1997"}, {"tribunal": "STJ", "n": "185", "texto": "Nos depositos judiciais, não incide o imposto sobre operações financeiras.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Operações Financeiras", "orgao": "Primeira Seção", "data": "12/03/1997"}, {"tribunal": "STJ", "n": "186", "texto": "Nas indenizações por ato ilicito, os juros compostos somente são devidos por aquele que praticou o crime.", "vinculante": false, "materia": "Direito Civil – Responsabilidade Civil", "orgao": "Corte Especial", "data": "02/04/1997"}, {"tribunal": "STJ", "n": "187", "texto": "E deserto o recurso interposto para o superior tribunal de justiça, quando o recorrente não recolhe, na origem, a importancia das despesas de remessa e retorno dos autos.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "21/05/1997"}, {"tribunal": "STJ", "n": "188", "texto": "Os juros moratorios, na repetição do indebito tributário, são devidos a partir do transito em julgado da sentença.", "vinculante": false, "materia": "Direito Tributário – Repetição de Indébito", "orgao": "Primeira Seção", "data": "11/06/1997"}, {"tribunal": "STJ", "n": "189", "texto": "E desnecessaria a intervenção do ministerio publico nas execuções fiscais.", "vinculante": false, "materia": "Direito Processual Civil – Execução Fiscal", "orgao": "Primeira Seção", "data": "11/06/1997"}, {"tribunal": "STJ", "n": "190", "texto": "Na execução fiscal, processada perante a justiça estadual, cumpre a fazenda publica antecipar o numerario destinado ao custeio das despesas com o transporte dos oficiais de justiça.", "vinculante": false, "materia": "Direito Processual Civil – Execução Fiscal", "orgao": "Primeira Seção", "data": "11/06/1997"}, {"tribunal": "STJ", "n": "191", "texto": "A pronuncia e causa interruptiva da prescrição, ainda que o tribunal do juri venha a desclassificar o crime.", "vinculante": false, "materia": "Direito Penal – Prescrição", "orgao": "Terceira Seção", "data": "25/06/1997"}, {"tribunal": "STJ", "n": "192", "texto": "Compete ao juizo das execuções penais do estado a execução das penas impostas a sentenciados pela justiça federal, militar ou eleitoral, quando recolhidos a estabelecimentos sujeitos a administração estadual.", "vinculante": false, "materia": "Direito Penal – Execução Penal", "orgao": "Terceira Seção", "data": "25/06/1997"}, {"tribunal": "STJ", "n": "193", "texto": "O direito de uso de linha telefonica pode ser adquirido por usucapião.", "vinculante": false, "materia": "Direito Civil – Usucapião", "orgao": "Segunda Seção", "data": "25/06/1997"}, {"tribunal": "STJ", "n": "194", "texto": "Prescreve em vinte anos a ação para obter, do construtor, indenização por defeitos da obra.", "vinculante": false, "materia": "Direito Civil – Contrato de Construção", "orgao": "Segunda Seção", "data": "24/09/1997"}, {"tribunal": "STJ", "n": "195", "texto": "Em embargos de terceiro não se anula ato juridico, por fraude contra credores.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Corte Especial", "data": "01/10/1997"}, {"tribunal": "STJ", "n": "196", "texto": "Ao executado que, citado por edital ou por hora certa, permanecer revel, sera nomeado curador especial, com legitimidade para apresentação de embargos.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Corte Especial", "data": "01/10/1997"}, {"tribunal": "STJ", "n": "197", "texto": "O divorcio direto pode ser concedido sem que haja previa partilha dos bens.", "vinculante": false, "materia": "Direito Civil – Divórcio", "orgao": "Segunda Seção", "data": "08/10/1997"}, {"tribunal": "STJ", "n": "198", "texto": "Na importação de veiculo por pessoa fisica, destinado a uso proprio, incide o icms.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Circulação de Mercadorias e Serviços", "orgao": "Primeira Seção", "data": "08/10/1997"}, {"tribunal": "STJ", "n": "199", "texto": "Na execução hipotecaria de credito vinculado ao sistema financeiro da habitação, nos termos da lei n. 5.741/71, a petição inicial deve ser instruida com, pelo menos, dois avisos de cobrança.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Primeira Seção", "data": "08/10/1997"}, {"tribunal": "STJ", "n": "200", "texto": "O juizo federal competente para processar e julgar acusado de crime de uso de passaporte falso e o do lugar onde o delito se consumou.", "vinculante": false, "materia": "Direito Processual Penal – Competência", "orgao": "Terceira Seção", "data": "22/10/1997"}, {"tribunal": "STJ", "n": "201", "texto": "Os honorarios advocaticios não podem ser fixados em salarios-minimos.", "vinculante": false, "materia": "Direito Processual Civil – Honorários Advocatícios", "orgao": "Corte Especial", "data": "17/12/1997"}, {"tribunal": "STJ", "n": "202", "texto": "A impetração de segurança por terceiro, contra ato judicial, não se condiciona a interposição de recurso.", "vinculante": false, "materia": "Direito Processual Civil – Mandado de Segurança", "orgao": "Corte Especial", "data": "17/12/1997"}, {"tribunal": "STJ", "n": "203", "texto": "Não cabe recurso especial contra decisão proferida por órgão de segundo grau dos Juizados Especiais. A Corte Especial, na sessão extraordinária de 23 de maio de 2002, julgando o AgRg no Ag 400.076-BA, deliberou pela ALTERAÇÃO do enunciado da Súmula n. 203. REDAÇÃO ANTERIOR (decisão de 04/02/1998, DJ 12/02/1998, PG: 35): NÃO CABE RECURSO ESPECIAL CONTRA DECISÃO PROFERIDA, NOS LIMITES DE SUA COMPETÊNCIA, POR ÓRGÃO DE SEGUNDO GRAU DOS JUIZADOS ESPECIAIS.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "23/05/2002"}, {"tribunal": "STJ", "n": "204", "texto": "Os juros de mora nas ações relativas a beneficios previdenciarios incidem a partir da citação valida.", "vinculante": false, "materia": "Direito Previdenciário – dos Benefícios Previdenciários", "orgao": "Terceira Seção", "data": "11/03/1998"}, {"tribunal": "STJ", "n": "205", "texto": "A lei 8.009/90 aplica-se a penhora realizada antes de sua vigencia.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Corte Especial", "data": "01/04/1998"}, {"tribunal": "STJ", "n": "206", "texto": "A existencia de vara privativa, instituida por lei estadual, não altera a competencia territorial resultante das leis de processo.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Corte Especial", "data": "01/04/1998"}, {"tribunal": "STJ", "n": "207", "texto": "E inadmissivel recurso especial quando cabiveis embargos infringentes contra o acordão proferido no tribunal de origem.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "01/04/1998"}, {"tribunal": "STJ", "n": "208", "texto": "Compete a justiça federal processar e julgar prefeito municipal por desvio de verba sujeita a prestação de contas perante orgão federal.", "vinculante": false, "materia": "Direito Processual Penal – Competência", "orgao": "Terceira Seção", "data": "27/05/1998"}, {"tribunal": "STJ", "n": "209", "texto": "Compete a justiça estadual processar e julgar prefeito por desvio de verba transferida e incorporada ao patrimonio municipal.", "vinculante": false, "materia": "Direito Processual Penal – Competência", "orgao": "Terceira Seção", "data": "27/05/1998"}, {"tribunal": "STJ", "n": "210", "texto": "A ação de cobrança das contribuições para o fgts prescreve em trinta (30) anos.", "vinculante": false, "materia": "Direito Administrativo – Fundo de Garantia Por Tempo de Serviço", "orgao": "Primeira Seção", "data": "27/05/1998"}, {"tribunal": "STJ", "n": "211", "texto": "Inadmissível recurso especial quanto à questão que, a despeito da oposição de embargos declaratórios, não foi apreciada pelo Tribunal a quo.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "01/07/1998"}, {"tribunal": "STJ", "n": "212", "texto": "A compensação de créditos tributários não pode ser deferida em ação cautelar ou por medida liminar cautelar ou antecipatória. A Primeira Seção, na sessão ordinária de 11 de maio de 2005, deliberou pela ALTERAÇÃO do enunciado da Súmula n. 212. REDAÇÃO ANTERIOR (decisão de 23/09/1998, DJ 02/10/1998, PG. 250): A COMPENSAÇÃO DE CRÉDITOS TRIBUTÁRIOS NÃO PODE SER DEFERIDA POR MEDIDA LIMINAR.", "vinculante": false, "materia": "Direito Tributário – Compensação", "orgao": "Primeira Seção", "data": "11/05/2005"}, {"tribunal": "STJ", "n": "213", "texto": "O mandado de segurança constitui ação adequada para a declaração do direito à compensação tributária.", "vinculante": false, "materia": "Direito Tributário – Compensação", "orgao": "Primeira Seção", "data": "23/09/1998"}, {"tribunal": "STJ", "n": "214", "texto": "O fiador na locação não responde por obrigações resultantes de aditamento ao qual não anuiu.", "vinculante": false, "materia": "Direito Civil – Contrato de Locação", "orgao": "Terceira Seção", "data": "23/09/1998"}, {"tribunal": "STJ", "n": "215", "texto": "A indenização recebida pela adesão a programa de incentivo à demissão voluntária não está sujeita à incidência do imposto de renda.", "vinculante": false, "materia": "Direito Tributário – Imposto de Renda", "orgao": "Primeira Seção", "data": "24/11/1998"}, {"tribunal": "STJ", "n": "216", "texto": "A tempestividade de recurso interposto no Superior Tribunal de Justiça é aferida pelo registro no protocolo da secretaria e não pela data da entrega na agência do correio.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "03/02/1999"}, {"tribunal": "STJ", "n": "217", "texto": "Não cabe agravo de decisão que indefere o pedido de suspensão da execução da liminar, ou da sentença em mandado de segurança. julgando AgRg na SS n. 1.204-AM, na sessão de 23/10/2003, a Corte Especial deliberou pelo CANCELAMENTO da súmula n. 217.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "23/10/2003"}, {"tribunal": "STJ", "n": "218", "texto": "Compete à Justiça dos Estados processar e julgar ação de servidor estadual decorrente de direitos e vantagens estatutárias no exercício de cargo em comissão.", "vinculante": false, "materia": "Direito Administrativo – Servidor Público Civil", "orgao": "Terceira Seção", "data": "10/02/1999"}, {"tribunal": "STJ", "n": "219", "texto": "Os créditos decorrentes de serviços prestados à massa falida, inclusive a remuneração do síndico, gozam dos privilégios próprios dos trabalhistas.", "vinculante": false, "materia": "Direito Empresarial – Falência, Concordata e Recuperação Jucicial", "orgao": "Segunda Seção", "data": "10/03/1999"}, {"tribunal": "STJ", "n": "220", "texto": "A reincidência não influi no prazo da prescrição da pretensão punitiva.", "vinculante": false, "materia": "Direito Penal – Prescrição", "orgao": "Terceira Seção", "data": "12/05/1999"}, {"tribunal": "STJ", "n": "221", "texto": "São civilmente responsáveis pelo ressarcimento de dano, decorrente de publicação pela imprensa, tanto o autor do escrito quanto o proprietário do veículo de divulgação.", "vinculante": false, "materia": "Direito Civil – Responsabilidade Civil", "orgao": "Segunda Seção", "data": "12/05/1999"}, {"tribunal": "STJ", "n": "222", "texto": "Compete à Justiça Comum processar e julgar as ações relativas à contribuição sindical prevista no art. 578 da CLT.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Segunda Seção", "data": "23/06/1999"}, {"tribunal": "STJ", "n": "223", "texto": "A certidão de intimação do acórdão recorrido constitui peça obrigatória do instrumento de agravo.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "02/08/1999"}, {"tribunal": "STJ", "n": "224", "texto": "Excluído do feito o ente federal, cuja presença levara o Juiz Estadual a declinar da competência, deve o Juiz Federal restituir os autos e não suscitar conflito.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Corte Especial", "data": "02/08/1999"}, {"tribunal": "STJ", "n": "225", "texto": "Compete ao Tribunal Regional do Trabalho apreciar recurso contra sentença proferida por órgão de primeiro grau da Justiça Trabalhista, ainda que para declarar-lhe a nulidade em virtude de incompetência.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Corte Especial", "data": "02/08/1999"}, {"tribunal": "STJ", "n": "226", "texto": "O Ministério Público tem legitimidade para recorrer na ação de acidente do trabalho, ainda que o segurado esteja assistido por advogado.", "vinculante": false, "materia": "Direito Processual Civil – Ação Acidentária", "orgao": "Corte Especial", "data": "02/08/1999"}, {"tribunal": "STJ", "n": "227", "texto": "A pessoa jurídica pode sofrer dano moral.", "vinculante": false, "materia": "Direito Civil – Dano Moral", "orgao": "Segunda Seção", "data": "08/09/1999"}, {"tribunal": "STJ", "n": "228", "texto": "É inadmissível o interdito proibitório para a proteção do direito autoral.", "vinculante": false, "materia": "Direito Processual Civil – Interdito Proibitório", "orgao": "Segunda Seção", "data": "08/09/1999"}, {"tribunal": "STJ", "n": "229", "texto": "O pedido do pagamento de indenização à seguradora suspende o prazo de prescrição até que o segurado tenha ciência da decisão.", "vinculante": false, "materia": "Direito Civil – Contrato de Seguro", "orgao": "Segunda Seção", "data": "08/09/1999"}, {"tribunal": "STJ", "n": "230", "texto": "Compete à Justiça Estadual processar e julgar ação movida por trabalhador avulso portuário, em que se impugna ato do órgão gestor de mão-de-obra de que resulte óbice ao exercício de sua profissão. Julgando os Conflitos de Competência ns. 30.513-SP, 30.500-SP e 30.504-SP, na sessão de 11/10/2000, a Segunda Seção deliberou pelo CANCELAMENTO da Súmula n. 230.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Segunda Seção", "data": "11/10/2000"}, {"tribunal": "STJ", "n": "231", "texto": "A incidência da circunstância atenuante não pode conduzir à redução da pena abaixo do mínimo legal.", "vinculante": false, "materia": "Direito Penal – das Penas", "orgao": "Terceira Seção", "data": "22/09/1999"}, {"tribunal": "STJ", "n": "232", "texto": "A Fazenda Pública, quando parte no processo, fica sujeita à exigência do depósito prévio dos honorários do perito.", "vinculante": false, "materia": "Direito Processual Civil – Honorários Periciais", "orgao": "Corte Especial", "data": "01/12/1999"}, {"tribunal": "STJ", "n": "233", "texto": "O contrato de abertura de crédito, ainda que acompanhado de extrato da conta-corrente, não é título executivo.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Segunda Seção", "data": "13/12/1999"}, {"tribunal": "STJ", "n": "234", "texto": "A participação de membro do Ministério Público na fase investigatória criminal não acarreta o seu impedimento ou suspeição para o oferecimento da denúncia.", "vinculante": false, "materia": "Direito Processual Penal – Investigação Criminal", "orgao": "Terceira Seção", "data": "13/12/1999"}, {"tribunal": "STJ", "n": "235", "texto": "A conexão não determina a reunião dos processos, se um deles já foi julgado.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Corte Especial", "data": "01/02/2000"}, {"tribunal": "STJ", "n": "236", "texto": "Não compete ao Superior Tribunal de Justiça dirimir conflitos de competência entre juízes trabalhistas vinculados a Tribunais Regionais do Trabalho diversos.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Segunda Seção", "data": "22/03/2000"}, {"tribunal": "STJ", "n": "237", "texto": "Nas operações com cartão de crédito, os encargos relativos ao financiamento não são considerados no cálculo do ICMS.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Circulação de Mercadorias e Serviços", "orgao": "Primeira Seção", "data": "10/04/2000"}, {"tribunal": "STJ", "n": "238", "texto": "A avaliação da indenização devida ao proprietário do solo, em razão de alvará de pesquisa mineral, é processada no Juízo Estadual da situação do imóvel.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Primeira Seção", "data": "10/04/2000"}, {"tribunal": "STJ", "n": "239", "texto": "O direito à adjudicação compulsória não se condiciona ao registro do compromisso de compra e venda no cartório de imóveis.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Segunda Seção", "data": "28/06/2000"}, {"tribunal": "STJ", "n": "240", "texto": "A extinção do processo, por abandono da causa pelo autor, depende de requerimento do réu.", "vinculante": false, "materia": "Direito Processual Civil – Extinção do Processo", "orgao": "Corte Especial", "data": "02/08/2000"}, {"tribunal": "STJ", "n": "241", "texto": "A reincidência penal não pode ser considerada como circunstância agravante e, simultaneamente, como circunstância judicial.", "vinculante": false, "materia": "Direito Penal – das Penas", "orgao": "Terceira Seção", "data": "23/08/2000"}, {"tribunal": "STJ", "n": "242", "texto": "Cabe ação declaratoria para reconhecimento de tempo de serviço para fins previdenciários.", "vinculante": false, "materia": "Direito Previdenciário – Ações Previdenciárias", "orgao": "Terceira Seção", "data": "22/11/2000"}, {"tribunal": "STJ", "n": "243", "texto": "O benefício da suspensão do processo não é aplicável em relação às infrações penais cometidas em concurso material, concurso formal ou continuidade delitiva, quando a pena mínima cominada, seja pelo somatório, seja pela incidência da majorante, ultrapassar o limite de um (01) ano.", "vinculante": false, "materia": "Direito Processual Penal – Suspensão Condicional do Processo", "orgao": "Corte Especial", "data": "11/12/2000"}, {"tribunal": "STJ", "n": "244", "texto": "Compete ao foro do local da recusa processar e julgar o crime de estelionato mediante cheque sem provisão de fundos.", "vinculante": false, "materia": "Direito Processual Penal – Competência", "orgao": "Terceira Seção", "data": "13/12/2000"}, {"tribunal": "STJ", "n": "245", "texto": "A notificação destinada a comprovar a mora nas dívidas garantidas por alienação fiduciária dispensa a indicação do valor do débito.", "vinculante": false, "materia": "Direito Bancário – Contrato Com Garantia de Alienação Fiduciária", "orgao": "Segunda Seção", "data": "28/03/2001"}, {"tribunal": "STJ", "n": "246", "texto": "O valor do seguro obrigatório deve ser deduzido da indenização judicialmente fixada.", "vinculante": false, "materia": "Direito Civil – Dpvat", "orgao": "Segunda Seção", "data": "28/03/2001"}, {"tribunal": "STJ", "n": "247", "texto": "O contrato de abertura de crédito em conta-corrente, acompanhado do demonstrativo de débito, constitui documento hábil para o ajuizamento da ação monitória.", "vinculante": false, "materia": "Direito Processual Civil – Ação Monitória", "orgao": "Segunda Seção", "data": "23/05/2001"}, {"tribunal": "STJ", "n": "248", "texto": "Comprovada a prestação dos serviços, a duplicata não aceita, mas protestada, é título hábil para instruir pedido de falência.", "vinculante": false, "materia": "Direito Empresarial – Falência, Concordata e Recuperação Jucicial", "orgao": "Segunda Seção", "data": "23/05/2001"}, {"tribunal": "STJ", "n": "249", "texto": "A Caixa Econômica Federal tem legitimidade passiva para integrar processo em que se discute correção monetária do FGTS.", "vinculante": false, "materia": "Direito Administrativo – Fundo de Garantia Por Tempo de Serviço", "orgao": "Primeira Seção", "data": "24/05/2001"}, {"tribunal": "STJ", "n": "250", "texto": "É legítima a cobrança de multa fiscal de empresa em regime de concordata.", "vinculante": false, "materia": "Direito Tributário – Multas", "orgao": "Primeira Seção", "data": "24/05/2001"}, {"tribunal": "STJ", "n": "251", "texto": "A meação só responde pelo ato ilícito quando o credor, na execução fiscal, provar que o enriquecimento dele resultante aproveitou ao casal.", "vinculante": false, "materia": "Direito Processual Civil – Execução Fiscal", "orgao": "Primeira Seção", "data": "13/06/2001"}, {"tribunal": "STJ", "n": "252", "texto": "Os saldos das contas do FGTS, pela legislação infraconstitucional, são corrigidos em 42,72% (IPC) quanto às perdas de janeiro de 1989 e 44,80% (IPC) quanto às de abril de 1990, acolhidos pelo STJ os índices de 18,02% (LBC) quanto as perdas de junho de 1987, de 5,38% (BTN) para maio de 1990 e 7,00%(TR) para fevereiro de 1991, de acordo com o entendimento do STF (RE 226.855-7-RS).", "vinculante": false, "materia": "Direito Administrativo – Fundo de Garantia Por Tempo de Serviço", "orgao": "Primeira Seção", "data": "13/06/2001"}, {"tribunal": "STJ", "n": "253", "texto": "O art. 557 do CPC, que autoriza o relator a decidir o recurso, alcança o reexame necessário.", "vinculante": false, "materia": "Direito Processual Civil – Reexame Necessário", "orgao": "Corte Especial", "data": "20/06/2001"}, {"tribunal": "STJ", "n": "254", "texto": "A decisão do Juízo Federal que exclui da relação processual ente federal não pode ser reexaminada no Juízo Estadual.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Corte Especial", "data": "01/08/2001"}, {"tribunal": "STJ", "n": "255", "texto": "Cabem embargos infringentes contra acórdão, proferido por maioria, em agravo retido, quando se tratar de matéria de mérito.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "01/08/2001"}, {"tribunal": "STJ", "n": "256", "texto": "O sistema de \"protocolo integrado\" não se aplica aos recursos dirigidos ao Superior Tribunal de Justiça. Julgando o AgRg no Ag 792.846-SP, na sessão de 21/05/2008, a Corte Especial deliberou pelo CANCELAMENTO da súmula n. 256.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "21/05/2008"}, {"tribunal": "STJ", "n": "257", "texto": "A falta de pagamento do prêmio do seguro obrigatório de Danos Pessoais Causados por Veículos Automotores de Vias Terrestres (DPVAT) não é motivo para a recusa do pagamento da indenização.", "vinculante": false, "materia": "Direito Civil – Dpvat", "orgao": "Segunda Seção", "data": "08/08/2001"}, {"tribunal": "STJ", "n": "258", "texto": "A nota promissória vinculada a contrato de abertura de crédito não goza de autonomia em razão da iliquidez do título que a originou.", "vinculante": false, "materia": "Direito Empresarial – Títulos de Crédito", "orgao": "Segunda Seção", "data": "12/09/2001"}, {"tribunal": "STJ", "n": "259", "texto": "A ação de prestação de contas pode ser proposta pelo titular de conta-corrente bancária.", "vinculante": false, "materia": "Direito Processual Civil – Ação de Prestação de Contas", "orgao": "Segunda Seção", "data": "28/11/2001"}, {"tribunal": "STJ", "n": "260", "texto": "A convenção de condomínio aprovada, ainda que sem registro, é eficaz para regular as relações entre os condôminos.", "vinculante": false, "materia": "Direito Civil – Condomínio", "orgao": "Segunda Seção", "data": "28/11/2001"}, {"tribunal": "STJ", "n": "261", "texto": "A cobrança de direitos autorais pela retransmissão radiofônica de músicas, em estabelecimentos hoteleiros, deve ser feita conforme a taxa média de utilização do equipamento, apurada em liquidação.", "vinculante": false, "materia": "Direito Civil – Direito Autoral", "orgao": "Segunda Seção", "data": "13/03/2002"}, {"tribunal": "STJ", "n": "262", "texto": "Incide o imposto de renda sobre o resultado das aplicações financeiras realizadas pelas cooperativas.", "vinculante": false, "materia": "Direito Tributário – Imposto de Renda", "orgao": "Primeira Seção", "data": "24/04/2002"}, {"tribunal": "STJ", "n": "263", "texto": "A cobrança antecipada do valor residual (VRG) descaracteriza o contrato de arrendamento mercantil, transformando-o em compra e venda a prestação. Julgando os RESPs 443.143-GO e 470.632-SP, na sessão de 27/08/2003, a Segunda Seção deliberou pelo CANCELAMENTO da Súmula n. 263.", "vinculante": false, "materia": "Direito Empresarial – Arrendamento Mercantil", "orgao": "Segunda Seção", "data": "27/08/2003"}, {"tribunal": "STJ", "n": "264", "texto": "É irrecorrível o ato judicial que apenas manda processar a concordata preventiva.", "vinculante": false, "materia": "Direito Empresarial – Falência, Concordata e Recuperação Jucicial", "orgao": "Segunda Seção", "data": "08/05/2002"}, {"tribunal": "STJ", "n": "265", "texto": "É necessária a oitiva do menor infrator antes de decretar-se a regressão da medida sócio-educativa.", "vinculante": false, "materia": "Direito Processual Penal – Estatuto da Criança e Do Adolescente", "orgao": "Terceira Seção", "data": "22/05/2002"}, {"tribunal": "STJ", "n": "266", "texto": "O diploma ou habilitação legal para o exercício do cargo deve ser exigido na posse e não na inscrição para o concurso público.", "vinculante": false, "materia": "Direito Administrativo – Concurso Público", "orgao": "Terceira Seção", "data": "22/05/2002"}, {"tribunal": "STJ", "n": "267", "texto": "A interposição de recurso, sem efeito suspensivo, contra decisão condenatória não obsta a expedição de mandado de prisão.", "vinculante": false, "materia": "Direito Processual Penal – Recursos", "orgao": "Terceira Seção", "data": "22/05/2002"}, {"tribunal": "STJ", "n": "268", "texto": "O fiador que não integrou a relação processual na ação de despejo não responde pela execução do julgado.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Terceira Seção", "data": "22/05/2002"}, {"tribunal": "STJ", "n": "269", "texto": "É admissível a adoção do regime prisional semi-aberto aos reincidentes condenados a pena igual ou inferior a quatro anos se favoráveis as circunstâncias judiciais.", "vinculante": false, "materia": "Direito Penal – das Penas", "orgao": "Terceira Seção", "data": "22/05/2002"}, {"tribunal": "STJ", "n": "270", "texto": "O protesto pela preferência de crédito, apresentado por ente federal em execução que tramita na Justiça Estadual, não desloca a competência para a Justiça Federal.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Corte Especial", "data": "01/08/2002"}, {"tribunal": "STJ", "n": "271", "texto": "A correção monetária dos depósitos judiciais independe de ação específica contra o banco depositário.", "vinculante": false, "materia": "Direito Processual Civil – Depósito Judicial", "orgao": "Corte Especial", "data": "01/08/2002"}, {"tribunal": "STJ", "n": "272", "texto": "O trabalhador rural, na condição de segurado especial, sujeito à contribuição obrigatória sobre a produção rural comercializada, somente faz jus à aposentadoria por tempo de serviço, se recolher contribuições facultativas.", "vinculante": false, "materia": "Direito Previdenciário – Trabalho Rural", "orgao": "Terceira Seção", "data": "11/09/2002"}, {"tribunal": "STJ", "n": "273", "texto": "Intimada a defesa da expedição da carta precatória, torna-se desnecessária intimação da data da audiência no juízo deprecado.", "vinculante": false, "materia": "Direito Processual Penal – Intimação", "orgao": "Terceira Seção", "data": "11/09/2002"}, {"tribunal": "STJ", "n": "274", "texto": "O ISS incide sobre o valor dos serviços de assistência médica, incluindo-se neles as refeições, os medicamentos e as diárias hospitalares.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Serviços", "orgao": "Primeira Seção", "data": "12/02/2003"}, {"tribunal": "STJ", "n": "275", "texto": "O auxiliar de farmácia não pode ser responsável técnico por farmácia ou drogaria.", "vinculante": false, "materia": "Direito Administrativo – Atividade Farmacêutica", "orgao": "Primeira Seção", "data": "12/03/2003"}, {"tribunal": "STJ", "n": "276", "texto": "As sociedades civis de prestação de serviços profissionais são isentas da Cofins, irrelevante o regime tributário adotado. Julgando a AR 3.761-PR, na sessão de 12/11/2008, a Primeira Seção deliberou pelo CANCELAMENTO da Súmula n. 276.", "vinculante": false, "materia": "Direito Tributário – Contribuição Para Financiamento da Seguridade Social", "orgao": "Primeira Seção", "data": "12/11/2008"}, {"tribunal": "STJ", "n": "277", "texto": "Julgada procedente a investigação de paternidade, os alimentos são devidos a partir da citação.", "vinculante": false, "materia": "Direito Civil – Investigação de Paternidade", "orgao": "Segunda Seção", "data": "14/05/2003"}, {"tribunal": "STJ", "n": "278", "texto": "O termo inicial do prazo prescricional, na ação de indenização, é a data em que o segurado teve ciência inequívoca da incapacidade laboral.", "vinculante": false, "materia": "Direito Civil – Contrato de Seguro", "orgao": "Segunda Seção", "data": "14/05/2003"}, {"tribunal": "STJ", "n": "279", "texto": "É cabível execução por título extrajudicial contra a Fazenda Pública.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Corte Especial", "data": "21/05/2003"}, {"tribunal": "STJ", "n": "280", "texto": "O art. 35 do Decreto-Lei n° 7.661, de 1945, que estabelece a prisão administrativa, foi revogado pelos incisos LXI e LXVII do art. 5° da Constituição Federal de 1988.", "vinculante": false, "materia": "Direito Empresarial – Falência e Concordata", "orgao": "Segunda Seção", "data": "10/12/2003"}, {"tribunal": "STJ", "n": "281", "texto": "A indenização por dano moral não está sujeita à tarifação prevista na Lei de Imprensa.", "vinculante": false, "materia": "Direito Civil – Dano Moral", "orgao": "Segunda Seção", "data": "28/04/2004"}, {"tribunal": "STJ", "n": "282", "texto": "Cabe a citação por edital em ação monitória.", "vinculante": false, "materia": "Direito Processual Civil – Ação Monitória", "orgao": "Segunda Seção", "data": "28/04/2004"}, {"tribunal": "STJ", "n": "283", "texto": "As empresas administradoras de cartão de crédito são instituições financeiras e, por isso, os juros remuneratórios por elas cobrados não sofrem as limitações da Lei de Usura.", "vinculante": false, "materia": "Direito Bancário – Contrato Bancário", "orgao": "Segunda Seção", "data": "28/04/2004"}, {"tribunal": "STJ", "n": "284", "texto": "A purga da mora, nos contratos de alienação fiduciária, só é permitida quando já pagos pelo menos 40% (quarenta por cento) do valor financiado.", "vinculante": false, "materia": "Direito Bancário – Contrato Com Garantia de Alienação Fiduciária", "orgao": "Segunda Seção", "data": "28/04/2004"}, {"tribunal": "STJ", "n": "285", "texto": "Nos contratos bancários posteriores ao Código de Defesa do Consumidor incide a multa moratória nele prevista.", "vinculante": false, "materia": "Direito do Consumidor – Instituições Financeiras", "orgao": "Segunda Seção", "data": "28/04/2004"}, {"tribunal": "STJ", "n": "286", "texto": "A renegociação de contrato bancário ou a confissão da dívida não impede a possibilidade de discussão sobre eventuais ilegalidades dos contratos anteriores.", "vinculante": false, "materia": "Direito Bancário – Contrato Bancário", "orgao": "Segunda Seção", "data": "28/04/2004"}, {"tribunal": "STJ", "n": "287", "texto": "A Taxa Básica Financeira (TBF) não pode ser utilizada como indexador de correção monetária nos contratos bancários.", "vinculante": false, "materia": "Direito Bancário – Contrato Bancário", "orgao": "Segunda Seção", "data": "28/04/2004"}, {"tribunal": "STJ", "n": "288", "texto": "A Taxa de Juros de Longo Prazo (TJLP) pode ser utilizada como indexador de correção monetária nos contratos bancários.", "vinculante": false, "materia": "Direito Bancário – Contrato Bancário", "orgao": "Segunda Seção", "data": "28/04/2004"}, {"tribunal": "STJ", "n": "289", "texto": "A restituição das parcelas pagas a plano de previdência privada deve ser objeto de correção plena, por índice que recomponha a efetiva desvalorização da moeda.", "vinculante": false, "materia": "Direito Previdenciário – Previdência Privada", "orgao": "Segunda Seção", "data": "28/04/2004"}, {"tribunal": "STJ", "n": "290", "texto": "Nos planos de previdência privada, não cabe ao beneficiário a devolução da contribuição efetuada pelo patrocinador.", "vinculante": false, "materia": "Direito Previdenciário – Previdência Privada", "orgao": "Segunda Seção", "data": "28/04/2004"}, {"tribunal": "STJ", "n": "291", "texto": "A ação de cobrança de parcelas de complementação de aposentadoria pela previdência privada prescreve em cinco anos.", "vinculante": false, "materia": "Direito Previdenciário – Previdência Privada", "orgao": "Segunda Seção", "data": "28/04/2004"}, {"tribunal": "STJ", "n": "292", "texto": "A reconvenção é cabível na ação monitória, após a conversão do procedimento em ordinário.", "vinculante": false, "materia": "Direito Processual Civil – Ação Monitória", "orgao": "Corte Especial", "data": "05/05/2004"}, {"tribunal": "STJ", "n": "293", "texto": "A cobrança antecipada do valor residual garantido (VRG) não descaracteriza o contrato de arrendamento mercantil.", "vinculante": false, "materia": "Direito Empresarial – Arrendamento Mercantil", "orgao": "Corte Especial", "data": "05/05/2004"}, {"tribunal": "STJ", "n": "294", "texto": "Não é potestativa a cláusula contratual que prevê a comissão de permanência, calculada pela taxa média de mercado apurada pelo Banco Central do Brasil, limitada à taxa do contrato.", "vinculante": false, "materia": "Direito Bancário – Contrato Bancário", "orgao": "Segunda Seção", "data": "12/05/2004"}, {"tribunal": "STJ", "n": "295", "texto": "A Taxa Referencial (TR) é indexador válido para contratos posteriores à Lei n. 8.177/91, desde que pactuada.", "vinculante": false, "materia": "Direito Bancário – Contrato Bancário", "orgao": "Segunda Seção", "data": "12/05/2004"}, {"tribunal": "STJ", "n": "296", "texto": "Os juros remuneratórios, não cumuláveis com a comissão de permanência, são devidos no período de inadimplência, à taxa média de mercado estipulada pelo Banco Central do Brasil, limitada ao percentual contratado.", "vinculante": false, "materia": "Direito Bancário – Contrato Bancário", "orgao": "Segunda Seção", "data": "12/05/2004"}, {"tribunal": "STJ", "n": "297", "texto": "O Código de Defesa do Consumidor é aplicável às instituições financeiras.", "vinculante": false, "materia": "Direito do Consumidor – Instituições Financeiras", "orgao": "Segunda Seção", "data": "12/05/2004"}, {"tribunal": "STJ", "n": "298", "texto": "O alongamento de dívida originada de crédito rural não constitui faculdade da instituição financeira, mas, direito do devedor nos termos da lei.", "vinculante": false, "materia": "Direito Bancário – Contrato Bancário", "orgao": "Segunda Seção", "data": "18/10/2004"}, {"tribunal": "STJ", "n": "299", "texto": "É admissível a ação monitória fundada em cheque prescrito.", "vinculante": false, "materia": "Direito Processual Civil – Ação Monitória", "orgao": "Segunda Seção", "data": "18/10/2004"}, {"tribunal": "STJ", "n": "300", "texto": "O instrumento de confissão de dívida, ainda que originário de contrato de abertura de crédito, constitui título executivo extrajudicial.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Segunda Seção", "data": "18/10/2004"}, {"tribunal": "STJ", "n": "301", "texto": "Em ação investigatória, a recusa do suposto pai a submeter-se ao exame de DNA induz presunção juris tantum de paternidade.", "vinculante": false, "materia": "Direito Civil – Investigação de Paternidade", "orgao": "Segunda Seção", "data": "18/10/2004"}, {"tribunal": "STJ", "n": "302", "texto": "É abusiva a cláusula contratual de plano de saúde que limita no tempo a internação hospitalar do segurado.", "vinculante": false, "materia": "Direito do Consumidor – Plano de Saúde", "orgao": "Segunda Seção", "data": "18/10/2004"}, {"tribunal": "STJ", "n": "303", "texto": "Em embargos de terceiro, quem deu causa à constrição indevida deve arcar com os honorários advocatícios.", "vinculante": false, "materia": "Direito Processual Civil – Honorários Advocatícios", "orgao": "Corte Especial", "data": "03/11/2004"}, {"tribunal": "STJ", "n": "304", "texto": "É ilegal a decretação da prisão civil daquele que não assume expressamente o encargo de depositário judicial.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Corte Especial", "data": "03/11/2004"}, {"tribunal": "STJ", "n": "305", "texto": "É descabida a prisão civil do depositário quando, decretada a falência da empresa, sobrevém a arrecadação do bem pelo síndico.", "vinculante": false, "materia": "Direito Empresarial – Falência, Concordata e Recuperação Jucicial", "orgao": "Corte Especial", "data": "03/11/2004"}, {"tribunal": "STJ", "n": "306", "texto": "Os honorários advocatícios devem ser compensados quando houver sucumbência recíproca, assegurado o direito autônomo do advogado à execução do saldo sem excluir a legitimidade da própria parte.", "vinculante": false, "materia": "Direito Processual Civil – Sucumbência", "orgao": "Corte Especial", "data": "03/11/2004"}, {"tribunal": "STJ", "n": "307", "texto": "A restituição de adiantamento de contrato de câmbio, na falência, deve ser atendida antes de qualquer crédito.", "vinculante": false, "materia": "Direito Empresarial – Falência, Concordata e Recuperação Jucicial", "orgao": "Segunda Seção", "data": "06/12/2004"}, {"tribunal": "STJ", "n": "308", "texto": "A hipoteca firmada entre a construtora e o agente financeiro, anterior ou posterior à celebração da promessa de compra e venda, não tem eficácia perante os adquirentes do imóvel.", "vinculante": false, "materia": "Direito Bancário – Sistema Financeiro da Habitação", "orgao": "Segunda Seção", "data": "30/03/2005"}, {"tribunal": "STJ", "n": "309", "texto": "O débito alimentar que autoriza a prisão civil do alimentante é o que compreende as três prestações anteriores ao ajuizamento da execução e as que se vencerem no curso do processo. A Segunda Seção, na sessão ordinária de 22 de março de 2006, julgando o HC 53.068-MS, deliberou pela ALTERAÇÃO do enunciado da Súmula n. 309. REDAÇÃO ANTERIOR (decisão de 27/04/2005, DJ 04/05/2005, PG: 166): O débito alimentar que autoriza a prisão civil do alimentante é o que compreende as três prestações anteriores à citação e as que vencerem no curso do processo.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Segunda Seção", "data": "22/03/2006"}, {"tribunal": "STJ", "n": "310", "texto": "O Auxílio-creche não integra o salário-de-contribuição.", "vinculante": false, "materia": "Direito Previdenciário – Benefícios Previdenciários", "orgao": "Primeira Seção", "data": "11/05/2005"}, {"tribunal": "STJ", "n": "311", "texto": "Os atos do presidente do tribunal que disponham sobre processamento e pagamento de precatório não têm caráter jurisdicional.", "vinculante": false, "materia": "Direito Processual Civil – Precatório", "orgao": "Primeira Seção", "data": "11/05/2005"}, {"tribunal": "STJ", "n": "312", "texto": "No processo administrativo para imposição de multa de trânsito, são necessárias as notificações da autuação e da aplicação da pena decorrente da infração.", "vinculante": false, "materia": "Direito Administrativo – Código de Trânsito Brasileiro", "orgao": "Primeira Seção", "data": "11/05/2005"}, {"tribunal": "STJ", "n": "313", "texto": "Em ação de indenização, procedente o pedido, é necessária a constituição de capital ou caução fidejussória para a garantia de pagamento da pensão, independentemente da situação financeira do demandado.", "vinculante": false, "materia": "Direito Processual Civil – Liquidação de Sentença", "orgao": "Segunda Seção", "data": "25/05/2005"}, {"tribunal": "STJ", "n": "314", "texto": "Em execução fiscal, não localizados bens penhoráveis, suspende-se o processo por um ano, findo o qual se inicia o prazo da prescrição qüinqüenal intercorrente.", "vinculante": false, "materia": "Direito Processual Civil – Execução Fiscal", "orgao": "Primeira Seção", "data": "12/12/2005"}, {"tribunal": "STJ", "n": "315", "texto": "Não cabem embargos de divergência no âmbito do agravo de instrumento que não admite recurso especial.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "05/10/2005"}, {"tribunal": "STJ", "n": "316", "texto": "Cabem embargos de divergência contra acórdão que, em agravo regimental, decide recurso especial.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "05/10/2005"}, {"tribunal": "STJ", "n": "317", "texto": "É definitiva a execução de título extrajudicial, ainda que pendente apelação contra sentença que julgue improcedentes os embargos.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Corte Especial", "data": "05/10/2005"}, {"tribunal": "STJ", "n": "318", "texto": "Formulado pedido certo e determinado, somente o autor tem interesse recursal em argüir o vício da sentença ilíquida.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "05/10/2005"}, {"tribunal": "STJ", "n": "319", "texto": "O encargo de depositário de bens penhorados pode ser expressamente recusado.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Corte Especial", "data": "05/10/2005"}, {"tribunal": "STJ", "n": "320", "texto": "A questão federal somente ventilada no voto vencido não atende ao requisito do prequestionamento.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "05/10/2005"}, {"tribunal": "STJ", "n": "321", "texto": "O Código de Defesa do Consumidor é aplicável à relação jurídica entre a entidade de previdência privada e seus participantes. A Segunda Seção, na sessão de 24 de fevereiro de 2016, ao apreciar o Projeto de Súmula n. 627 e o julgado no REsp 1.536.786-MG, determinou o CANCELAMENTO da Súmula n. 321-STJ.", "vinculante": false, "materia": "Direito do Consumidor – Instituições Financeiras", "orgao": "Segunda Seção", "data": "24/02/2016"}, {"tribunal": "STJ", "n": "322", "texto": "Para a repetição de indébito, nos contratos de abertura de crédito em conta-corrente, não se exige a prova do erro.", "vinculante": false, "materia": "Direito Bancário – Contrato Bancário", "orgao": "Segunda Seção", "data": "23/11/2005"}, {"tribunal": "STJ", "n": "323", "texto": "A inscrição do nome do devedor pode ser mantida nos serviços de proteção ao crédito até o prazo máximo de cinco anos, independentemente da prescrição da execução. A Segunda Seção, na sessão ordinária de 25 de novembro de 2009, deliberou pela ALTERAÇÃO do enunciado da Súmula n. 323. REDAÇÃO ANTERIOR (Decisão de 23/11/2005, DJ 05/12/2005, PG. 410): A inscrição de inadimplente pode ser mantida nos serviços de proteção ao crédito por, no máximo, cinco anos.", "vinculante": false, "materia": "Direito do Consumidor – Serviço de Proteção ao Crédito", "orgao": "Segunda Seção", "data": "25/11/2009"}, {"tribunal": "STJ", "n": "324", "texto": "Compete à Justiça Federal processar e julgar ações de que participa a Fundação Habitacional do Exército, equiparada à entidade autárquica federal, supervisionada pelo Ministério do Exército.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Corte Especial", "data": "03/05/2006"}, {"tribunal": "STJ", "n": "325", "texto": "A remessa oficial devolve ao Tribunal o reexame de todas as parcelas da condenação suportadas pela Fazenda Pública, inclusive dos honorários de advogado.", "vinculante": false, "materia": "Direito Processual Civil – Reexame Necessário", "orgao": "Corte Especial", "data": "03/05/2006"}, {"tribunal": "STJ", "n": "326", "texto": "Na ação de indenização por dano moral, a condenação em montante inferior ao postulado na inicial não implica sucumbência recíproca.", "vinculante": false, "materia": "Direito Processual Civil – Sucumbência", "orgao": "Corte Especial", "data": "22/05/2006"}, {"tribunal": "STJ", "n": "327", "texto": "Nas ações referentes ao Sistema Financeiro da Habitação, a Caixa Econômica Federal tem legitimidade como sucessora do Banco Nacional da Habitação.", "vinculante": false, "materia": "Direito Bancário – Sistema Financeiro da Habitação", "orgao": "Corte Especial", "data": "22/05/2006"}, {"tribunal": "STJ", "n": "328", "texto": "Na execução contra instituição financeira, é penhorável o numerário disponível, excluídas as reservas bancárias mantidas no Banco Central.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Corte Especial", "data": "02/08/2006"}, {"tribunal": "STJ", "n": "329", "texto": "O Ministério Público tem legitimidade para propor ação civil pública em defesa do patrimônio público.", "vinculante": false, "materia": "Direito Processual Civil – Ação Civil Pública", "orgao": "Corte Especial", "data": "02/08/2006"}, {"tribunal": "STJ", "n": "330", "texto": "É desnecessária a resposta preliminar de que trata o artigo 514 do Código de Processo Penal, na ação penal instruída por inquérito policial.", "vinculante": false, "materia": "Direito Processual Penal – Resposta Preliminar", "orgao": "Terceira Seção", "data": "13/09/2006"}, {"tribunal": "STJ", "n": "331", "texto": "A apelação interposta contra sentença que julga embargos à arrematação tem efeito meramente devolutivo.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "04/10/2006"}, {"tribunal": "STJ", "n": "332", "texto": "A fiança prestada sem autorização de um dos cônjuges implica a ineficácia total da garantia.", "vinculante": false, "materia": "Direito Civil – Contrato de Fiança", "orgao": "Corte Especial", "data": "05/03/2008"}, {"tribunal": "STJ", "n": "333", "texto": "Cabe mandado de segurança contra ato praticado em licitação promovida por sociedade de economia mista ou empresa pública.", "vinculante": false, "materia": "Direito Processual Civil – Mandado de Segurança", "orgao": "Primeira Seção", "data": "13/12/2006"}, {"tribunal": "STJ", "n": "334", "texto": "O ICMS não incide no serviço dos provedores de acesso à Internet.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Circulação de Mercadorias e Serviços", "orgao": "Primeira Seção", "data": "13/12/2006"}, {"tribunal": "STJ", "n": "335", "texto": "Nos contratos de locação, é válida a cláusula de renúncia à indenização das benfeitorias e ao direito de retenção.", "vinculante": false, "materia": "Direito Civil – Contrato de Locação", "orgao": "Terceira Seção", "data": "25/04/2007"}, {"tribunal": "STJ", "n": "336", "texto": "A mulher que renunciou aos alimentos na separação judicial tem direito à pensão previdenciária por morte do ex-marido, comprovada a necessidade econômica superveniente.", "vinculante": false, "materia": "Direito Previdenciário – dos Benefícios Previdenciários", "orgao": "Terceira Seção", "data": "25/04/2007"}, {"tribunal": "STJ", "n": "337", "texto": "É cabível a suspensão condicional do processo na desclassificação do crime e na procedência parcial da pretensão punitiva.", "vinculante": false, "materia": "Direito Processual Penal – Suspensão Condicional do Processo", "orgao": "Terceira Seção", "data": "09/05/2007"}, {"tribunal": "STJ", "n": "338", "texto": "A prescrição penal é aplicável nas medidas sócio-educativas.", "vinculante": false, "materia": "Direito Penal – Estatuto da Criança e Do Adolescente", "orgao": "Terceira Seção", "data": "09/05/2007"}, {"tribunal": "STJ", "n": "339", "texto": "É cabível ação monitória contra a Fazenda Pública.", "vinculante": false, "materia": "Direito Processual Civil – Ação Monitória", "orgao": "Corte Especial", "data": "16/05/2007"}, {"tribunal": "STJ", "n": "340", "texto": "A lei aplicável à concessão de pensão previdenciária por morte é aquela vigente na data do óbito do segurado.", "vinculante": false, "materia": "Direito Previdenciário – dos Benefícios Previdenciários", "orgao": "Terceira Seção", "data": "27/06/2007"}, {"tribunal": "STJ", "n": "341", "texto": "A freqüência a curso de ensino formal é causa de remição de parte do tempo de execução de pena sob regime fechado ou semi-aberto.", "vinculante": false, "materia": "Direito Penal – Execução Penal", "orgao": "Terceira Seção", "data": "27/06/2007"}, {"tribunal": "STJ", "n": "342", "texto": "No procedimento para aplicação de medida sócio-educativa, é nula a desistência de outras provas em face da confissão do adolescente.", "vinculante": false, "materia": "Direito Penal – Estatuto da Criança e Do Adolescente", "orgao": "Terceira Seção", "data": "27/06/2007"}, {"tribunal": "STJ", "n": "343", "texto": "É obrigatória a presença de advogado em todas as fases do processo administrativo disciplinar. A Primeira Seção, na sessão de 28 de abril de 2021, ao apreciar a QO no MS 7.078-DF (Projeto de Súmula n. 700), determinou o CANCELAMENTO da Súmula n. 343-STJ.", "vinculante": false, "materia": "Direito Administrativo – Processo Administrativo Disciplinar", "orgao": "Terceira Seção", "data": "12/09/2007"}, {"tribunal": "STJ", "n": "344", "texto": "A liquidação por forma diversa da estabelecida na sentença não ofende a coisa julgada.", "vinculante": false, "materia": "Direito Processual Civil – Liquidação de Sentença", "orgao": "Corte Especial", "data": "07/11/2007"}, {"tribunal": "STJ", "n": "345", "texto": "São devidos honorários advocatícios pela Fazenda Pública nas execuções individuais de sentença proferida em ações coletivas, ainda que não embargadas.", "vinculante": false, "materia": "Direito Processual Civil – Honorários Advocatícios", "orgao": "Corte Especial", "data": "07/11/2007"}, {"tribunal": "STJ", "n": "346", "texto": "É vedada aos militares temporários, para aquisição de estabilidade, a contagem em dobro de férias e licenças não-gozadas.", "vinculante": false, "materia": "Direito Administrativo – Servidor Público Militar", "orgao": "Terceira Seção", "data": "13/02/2008"}, {"tribunal": "STJ", "n": "347", "texto": "O conhecimento de recurso de apelação do réu independe de sua prisão.", "vinculante": false, "materia": "Direito Processual Penal – Recursos", "orgao": "Terceira Seção", "data": "23/04/2008"}, {"tribunal": "STJ", "n": "348", "texto": "Compete ao Superior Tribunal de Justiça decidir os conflitos de competência entre juizado especial federal e juízo federal, ainda que da mesma seção judiciária. julgando o CC 107.635-PR, na sessão de 17/03/2010, a Corte Especial deliberou pelo CANCELAMENTO da súmula n. 348.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Corte Especial", "data": "17/03/2010"}, {"tribunal": "STJ", "n": "349", "texto": "Compete à Justiça Federal ou aos juízes com competência delegada o julgamento das execuções fiscais de contribuições devidas pelo empregador ao FGTS.", "vinculante": false, "materia": "Direito Administrativo – Fundo de Garantia Por Tempo de Serviço", "orgao": "Primeira Seção", "data": "11/06/2008"}, {"tribunal": "STJ", "n": "350", "texto": "O ICMS não incide sobre o serviço de habilitação de telefone celular.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Circulação de Mercadorias e Serviços", "orgao": "Primeira Seção", "data": "11/06/2008"}, {"tribunal": "STJ", "n": "351", "texto": "A alíquota de contribuição para o Seguro de Acidente do Trabalho (SAT) é aferida pelo grau de risco desenvolvido em cada empresa, individualizada pelo seu CNPJ, ou pelo grau de risco da atividade preponderante quando houver apenas um registro.", "vinculante": false, "materia": "Direito Previdenciário – Seguro de Acidente do Trabalho", "orgao": "Primeira Seção", "data": "11/06/2008"}, {"tribunal": "STJ", "n": "352", "texto": "A obtenção ou a renovação do Certificado de Entidade Beneficente de Assistência Social (Cebas) não exime a entidade do cumprimento dos requisitos legais supervenientes.", "vinculante": false, "materia": "Direito Previdenciário – Certificado de Entidade Beneficente de Assistência Social", "orgao": "Primeira Seção", "data": "11/06/2008"}, {"tribunal": "STJ", "n": "353", "texto": "As disposições do Código Tributário Nacional não se aplicam às contribuições para o FGTS.", "vinculante": false, "materia": "Direito Administrativo – Fundo de Garantia Por Tempo de Serviço", "orgao": "Primeira Seção", "data": "11/06/2008"}, {"tribunal": "STJ", "n": "354", "texto": "A invasão do imóvel é causa de suspensão do processo expropriatório para fins de reforma agrária.", "vinculante": false, "materia": "Direito Administrativo – Desapropriação", "orgao": "Primeira Seção", "data": "25/06/2008"}, {"tribunal": "STJ", "n": "355", "texto": "É válida a notificação do ato de exclusão do programa de recuperação fiscal do Refis pelo Diário Oficial ou pela Internet.", "vinculante": false, "materia": "Direito Tributário – Programa de Recuperação Fiscal", "orgao": "Primeira Seção", "data": "25/06/2008"}, {"tribunal": "STJ", "n": "356", "texto": "É legítima a cobrança da tarifa básica pelo uso dos serviços de telefonia fixa.", "vinculante": false, "materia": "Direito Administrativo – Telefonia", "orgao": "Primeira Seção", "data": "25/06/2008"}, {"tribunal": "STJ", "n": "357", "texto": "A pedido do assinante, que responderá pelos custos, é obrigatória, a partir de 1º de janeiro de 2006, a discriminação de pulsos excedentes e ligações de telefone fixo para celular. Julgando o REsp 1.074.799-MG, na sessão de 27/05/2009, a Primeira Seção deliberou pela REVOGAÇÃO da súmula 357.", "vinculante": false, "materia": "Direito do Consumidor – Serviços Públicos", "orgao": "Primeira Seção", "data": "27/05/2009"}, {"tribunal": "STJ", "n": "358", "texto": "O cancelamento de pensão alimentícia de filho que atingiu a maioridade está sujeito à decisão judicial, mediante contraditório, ainda que nos próprios autos.", "vinculante": false, "materia": "Direito Civil – Alimentos", "orgao": "Segunda Seção", "data": "13/08/2008"}, {"tribunal": "STJ", "n": "359", "texto": "Cabe ao órgão mantenedor do Cadastro de Proteção ao Crédito a notificação do devedor antes de proceder à inscrição.", "vinculante": false, "materia": "Direito do Consumidor – Serviço de Proteção ao Crédito", "orgao": "Segunda Seção", "data": "13/08/2008"}, {"tribunal": "STJ", "n": "360", "texto": "O benefício da denúncia espontânea não se aplica aos tributos sujeitos a lançamento por homologação regularmente declarados, mas pagos a destempo.", "vinculante": false, "materia": "Direito Tributário – Denúncia Espontânea", "orgao": "Primeira Seção", "data": "27/08/2008"}, {"tribunal": "STJ", "n": "361", "texto": "A notificação do protesto, para requerimento de falência da empresa devedora, exige a identificação da pessoa que a recebeu.", "vinculante": false, "materia": "Direito Empresarial – Falência, Concordata e Recuperação Jucicial", "orgao": "Segunda Seção", "data": "10/09/2008"}, {"tribunal": "STJ", "n": "362", "texto": "A correção monetária do valor da indenização do dano moral incide desde a data do arbitramento.", "vinculante": false, "materia": "Direito Civil – Responsabilidade Civil", "orgao": "Corte Especial", "data": "15/10/2008"}, {"tribunal": "STJ", "n": "363", "texto": "Compete à Justiça estadual processar e julgar a ação de cobrança ajuizada por profissional liberal contra cliente.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Corte Especial", "data": "15/10/2008"}, {"tribunal": "STJ", "n": "364", "texto": "O conceito de impenhorabilidade de bem de família abrange também o imóvel pertencente a pessoas solteiras, separadas e viúvas.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Corte Especial", "data": "15/10/2008"}, {"tribunal": "STJ", "n": "365", "texto": "A intervenção da União como sucessora da Rede Ferroviária Federal S/A (RFFSA) desloca a competência para a Justiça Federal ainda que a sentença tenha sido proferida por Juízo estadual.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Corte Especial", "data": "19/11/2008"}, {"tribunal": "STJ", "n": "366", "texto": "Compete à Justiça estadual processar e julgar ação indenizatória proposta por viúva e filhos de empregado falecido em acidente de trabalho. Julgando o CC 101.977-SP, na sessão de 16/09/2009, a Corte Especial deliberou pelo CANCELAMENTO da Súmula n. 366.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Corte Especial", "data": "16/09/2009"}, {"tribunal": "STJ", "n": "367", "texto": "A competência estabelecida pela EC n. 45/2004 não alcança os processos já sentenciados.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Corte Especial", "data": "19/11/2008"}, {"tribunal": "STJ", "n": "368", "texto": "Compete à Justiça comum estadual processar e julgar os pedidos de retificação de dados cadastrais da Justiça Eleitoral.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Primeira Seção", "data": "26/11/2008"}, {"tribunal": "STJ", "n": "369", "texto": "No contrato de arrendamento mercantil (leasing), ainda que haja cláusula resolutiva expressa, é necessária a notificação prévia do arrendatário para constituí-lo em mora.", "vinculante": false, "materia": "Direito Empresarial – Arrendamento Mercantil", "orgao": "Segunda Seção", "data": "16/02/2009"}, {"tribunal": "STJ", "n": "370", "texto": "Caracteriza dano moral a apresentação antecipada de cheque pré-datado.", "vinculante": false, "materia": "Direito Civil – Dano Moral", "orgao": "Segunda Seção", "data": "16/02/2009"}, {"tribunal": "STJ", "n": "371", "texto": "Nos contratos de participação financeira para a aquisição de linha telefônica, o Valor Patrimonial da Ação (VPA) é apurado com base no balancete do mês da integralização.", "vinculante": false, "materia": "Direito Empresarial – Contrato de Participação Financeira", "orgao": "Segunda Seção", "data": "11/03/2009"}, {"tribunal": "STJ", "n": "372", "texto": "Na ação de exibição de documentos, não cabe a aplicação de multa cominatória.", "vinculante": false, "materia": "Direito Processual Civil – Ação de Exibição de Documentos", "orgao": "Segunda Seção", "data": "11/03/2009"}, {"tribunal": "STJ", "n": "373", "texto": "É ilegítima a exigência de depósito prévio para admissibilidade de recurso administrativo.", "vinculante": false, "materia": "Direito Administrativo – Processo Administrativo", "orgao": "Primeira Seção", "data": "11/03/2009"}, {"tribunal": "STJ", "n": "374", "texto": "Compete à Justiça Eleitoral processar e julgar a ação para anular débito decorrente de multa eleitoral.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Primeira Seção", "data": "11/03/2009"}, {"tribunal": "STJ", "n": "375", "texto": "O reconhecimento da fraude à execução depende do registro da penhora do bem alienado ou da prova de má-fé do terceiro adquirente.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Corte Especial", "data": "18/03/2009"}, {"tribunal": "STJ", "n": "376", "texto": "Compete a turma recursal processar e julgar o mandado de segurança contra ato de juizado especial.", "vinculante": false, "materia": "Direito Processual Civil – Mandado de Segurança", "orgao": "Corte Especial", "data": "18/03/2009"}, {"tribunal": "STJ", "n": "377", "texto": "O portador de visão monocular tem direito de concorrer, em concurso público, às vagas reservadas aos deficientes.", "vinculante": false, "materia": "Direito Administrativo – Concurso Público", "orgao": "Terceira Seção", "data": "22/04/2009"}, {"tribunal": "STJ", "n": "378", "texto": "Reconhecido o desvio de função, o servidor faz jus às diferenças salariais decorrentes.", "vinculante": false, "materia": "Direito Administrativo – Servidor Público Civil", "orgao": "Terceira Seção", "data": "22/04/2009"}, {"tribunal": "STJ", "n": "379", "texto": "Nos contratos bancários não regidos por legislação específica, os juros moratórios poderão ser convencionados até o limite de 1% ao mês.", "vinculante": false, "materia": "Direito Bancário – Contrato Bancário", "orgao": "Segunda Seção", "data": "22/04/2009"}, {"tribunal": "STJ", "n": "380", "texto": "A simples propositura da ação de revisão de contrato não inibe a caracterização da mora do autor.", "vinculante": false, "materia": "Direito Bancário – Contrato Bancário", "orgao": "Segunda Seção", "data": "22/04/2009"}, {"tribunal": "STJ", "n": "381", "texto": "Nos contratos bancários, é vedado ao julgador conhecer, de ofício, da abusividade das cláusulas.", "vinculante": false, "materia": "Direito Bancário – Contrato Bancário", "orgao": "Segunda Seção", "data": "22/04/2009"}, {"tribunal": "STJ", "n": "382", "texto": "A estipulação de juros remuneratórios superiores a 12% ao ano, por si só, não indica abusividade.", "vinculante": false, "materia": "Direito Bancário – Contrato Bancário", "orgao": "Segunda Seção", "data": "27/05/2009"}, {"tribunal": "STJ", "n": "383", "texto": "A competência para processar e julgar as ações conexas de interesse de menor é, em princípio, do foro do domicílio do detentor de sua guarda.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Segunda Seção", "data": "27/05/2009"}, {"tribunal": "STJ", "n": "384", "texto": "Cabe ação monitória para haver saldo remanescente oriundo de venda extrajudicial de bem alienado fiduciariamente em garantia.", "vinculante": false, "materia": "Direito Processual Civil – Ação Monitória", "orgao": "Segunda Seção", "data": "27/05/2009"}, {"tribunal": "STJ", "n": "385", "texto": "Da anotação irregular em cadastro de proteção ao crédito, não cabe indenização por dano moral, quando preexistente legítima inscrição, ressalvado o direito ao cancelamento.", "vinculante": false, "materia": "Direito do Consumidor – Serviço de Proteção ao Crédito", "orgao": "Segunda Seção", "data": "27/05/2009"}, {"tribunal": "STJ", "n": "386", "texto": "São isentas de imposto de renda as indenizações de férias proporcionais e o respectivo adicional.", "vinculante": false, "materia": "Direito Tributário – Imposto de Renda", "orgao": "Primeira Seção", "data": "26/08/2009"}, {"tribunal": "STJ", "n": "387", "texto": "É lícita a cumulação das indenizações de dano estético e dano moral.", "vinculante": false, "materia": "Direito Civil – Dano Moral", "orgao": "Segunda Seção", "data": "26/08/2009"}, {"tribunal": "STJ", "n": "388", "texto": "A simples devolução indevida de cheque caracteriza dano moral.", "vinculante": false, "materia": "Direito Civil – Dano Moral", "orgao": "Segunda Seção", "data": "26/08/2009"}, {"tribunal": "STJ", "n": "389", "texto": "A comprovação do pagamento do ?custo do serviço? referente ao fornecimento de certidão de assentamentos constantes dos livros da companhia é requisito de procedibilidade da ação de exibição de documentos ajuizada em face da sociedade anônima.", "vinculante": false, "materia": "Direito Processual Civil – Ação de Exibição de Documentos", "orgao": "Segunda Seção", "data": "26/08/2009"}, {"tribunal": "STJ", "n": "390", "texto": "Nas decisões por maioria, em reexame necessário, não se admitem embargos infringentes.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "02/09/2009"}, {"tribunal": "STJ", "n": "391", "texto": "O ICMS incide sobre o valor da tarifa de energia elétrica correspondente à demanda de potência efetivamente utilizada.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Circulação de Mercadorias e Serviços", "orgao": "Primeira Seção", "data": "23/09/2009"}, {"tribunal": "STJ", "n": "392", "texto": "A Fazenda Pública pode substituir a certidão de dívida ativa (CDA) até a prolação da sentença de embargos, quando se tratar de correção de erro material ou formal, vedada a modificação do sujeito passivo da execução.", "vinculante": false, "materia": "Direito Processual Civil – Execução Fiscal", "orgao": "Primeira Seção", "data": "23/09/2009"}, {"tribunal": "STJ", "n": "393", "texto": "A exceção de pré-executividade é admissível na execução fiscal relativamente às matérias conhecíveis de ofício que não demandem dilação probatória.", "vinculante": false, "materia": "Direito Processual Civil – Execução Fiscal", "orgao": "Primeira Seção", "data": "23/09/2009"}, {"tribunal": "STJ", "n": "394", "texto": "É admissível, em embargos à execução, compensar os valores de imposto de renda retidos indevidamente na fonte com os valores restituídos apurados na declaração anual.", "vinculante": false, "materia": "Direito Processual Civil – Execução Fiscal", "orgao": "Primeira Seção", "data": "23/09/2009"}, {"tribunal": "STJ", "n": "395", "texto": "O ICMS incide sobre o valor da venda a prazo constante da nota fiscal.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Circulação de Mercadorias e Serviços", "orgao": "Primeira Seção", "data": "23/09/2009"}, {"tribunal": "STJ", "n": "396", "texto": "A Confederação Nacional da Agricultura tem legitimidade ativa para a cobrança da contribuição sindical rural.", "vinculante": false, "materia": "Direito Tributário – Contribuição Sindical Rural", "orgao": "Primeira Seção", "data": "23/09/2009"}, {"tribunal": "STJ", "n": "397", "texto": "O contribuinte do IPTU é notificado do lançamento pelo envio do carnê ao seu endereço.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre a Propriedade Predial e Territorial Urbana", "orgao": "Primeira Seção", "data": "23/09/2009"}, {"tribunal": "STJ", "n": "398", "texto": "A prescrição da ação para pleitear os juros progressivos sobre os saldos de conta vinculada do FGTS não atinge o fundo de direito, limitando-se às parcelas vencidas.", "vinculante": false, "materia": "Direito Administrativo – Fundo de Garantia Por Tempo de Serviço", "orgao": "Primeira Seção", "data": "23/09/2009"}, {"tribunal": "STJ", "n": "399", "texto": "Cabe à legislação municipal estabelecer o sujeito passivo do IPTU.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre a Propriedade Predial e Territorial Urbana", "orgao": "Primeira Seção", "data": "23/09/2009"}, {"tribunal": "STJ", "n": "400", "texto": "O encargo de 20% previsto no DL n. 1.025/1969 é exigível na execução fiscal proposta contra a massa falida.", "vinculante": false, "materia": "Direito Processual Civil – Execução Fiscal", "orgao": "Primeira Seção", "data": "23/09/2009"}, {"tribunal": "STJ", "n": "401", "texto": "O prazo decadencial da ação rescisória só se inicia quando não for cabível qualquer recurso do último pronunciamento judicial.", "vinculante": false, "materia": "Direito Processual Civil – Ação Rescisória", "orgao": "Corte Especial", "data": "07/10/2009"}, {"tribunal": "STJ", "n": "402", "texto": "O contrato de seguro por danos pessoais compreende os danos morais, salvo cláusula expressa de exclusão.", "vinculante": false, "materia": "Direito Civil – Contrato de Seguro", "orgao": "Segunda Seção", "data": "28/10/2009"}, {"tribunal": "STJ", "n": "403", "texto": "Independe de prova do prejuízo a indenização pela publicação não autorizada de imagem de pessoa com fins econômicos ou comerciais.", "vinculante": false, "materia": "Direito Civil – Dano Moral", "orgao": "Segunda Seção", "data": "28/10/2009"}, {"tribunal": "STJ", "n": "404", "texto": "É dispensável o aviso de recebimento (AR) na carta de comunicação ao consumidor sobre a negativação de seu nome em bancos de dados e cadastros.", "vinculante": false, "materia": "Direito do Consumidor – Serviço de Proteção ao Crédito", "orgao": "Segunda Seção", "data": "28/10/2009"}, {"tribunal": "STJ", "n": "405", "texto": "A ação de cobrança do seguro obrigatório (DPVAT) prescreve em três anos.", "vinculante": false, "materia": "Direito Civil – Dpvat", "orgao": "Segunda Seção", "data": "28/10/2009"}, {"tribunal": "STJ", "n": "406", "texto": "A Fazenda Pública pode recusar a substituição do bem penhorado por precatório.", "vinculante": false, "materia": "Direito Processual Civil – Execução Fiscal", "orgao": "Primeira Seção", "data": "28/10/2009"}, {"tribunal": "STJ", "n": "407", "texto": "É legítima a cobrança da tarifa de água fixada de acordo com as categorias de usuários e as faixas de consumo.", "vinculante": false, "materia": "Direito Administrativo – Água e Esgoto", "orgao": "Primeira Seção", "data": "28/10/2009"}, {"tribunal": "STJ", "n": "408", "texto": "Nas ações de desapropriação, os juros compensatórios incidentes após a Medida Provisória n. 1.577, de 11/06/1997, devem ser fixados em 6% ao ano até 13/09/2001 e, a partir de então, em 12% ao ano, na forma da Súmula n. 618 do Supremo Tribunal Federal. A Primeira Seção, no dia 28/10/2020, ao julgar a PET 12.344-DF, determinou o CANCELAMENTO da Súmula n. 408-STJ, com a publicação do cancelamento da referida súmula no DJe por três dias consecutivos a partir do dia 18/11/2020.", "vinculante": false, "materia": "Direito Administrativo – Desapropriação", "orgao": "Primeira Seção", "data": "28/10/2009"}, {"tribunal": "STJ", "n": "409", "texto": "Em execução fiscal, a prescrição ocorrida antes da propositura da ação pode ser decretada de ofício (art. 219, § 5º, do CPC).", "vinculante": false, "materia": "Direito Processual Civil – Execução Fiscal", "orgao": "Primeira Seção", "data": "28/10/2009"}, {"tribunal": "STJ", "n": "410", "texto": "A prévia intimação pessoal do devedor constitui condição necessária para a cobrança de multa pelo descumprimento de obrigação de fazer ou não fazer.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Segunda Seção", "data": "25/11/2009"}, {"tribunal": "STJ", "n": "411", "texto": "É devida a correção monetária ao creditamento do IPI quando há oposição ao seu aproveitamento decorrente de resistência ilegítima do Fisco.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Produtos Industrializados", "orgao": "Primeira Seção", "data": "25/11/2009"}, {"tribunal": "STJ", "n": "412", "texto": "A ação de repetição de indébito de tarifas de água e esgoto sujeita-se ao prazo prescricional estabelecido no Código Civil.", "vinculante": false, "materia": "Direito Administrativo – Água e Esgoto", "orgao": "Primeira Seção", "data": "25/11/2009"}, {"tribunal": "STJ", "n": "413", "texto": "O farmacêutico pode acumular a responsabilidade técnica por uma farmácia e uma drogaria ou por duas drogarias.", "vinculante": false, "materia": "Direito Administrativo – Atividade Farmacêutica", "orgao": "Primeira Seção", "data": "25/11/2009"}, {"tribunal": "STJ", "n": "414", "texto": "A citação por edital na execução fiscal é cabível quando frustradas as demais modalidades.", "vinculante": false, "materia": "Direito Processual Civil – Execução Fiscal", "orgao": "Primeira Seção", "data": "25/11/2009"}, {"tribunal": "STJ", "n": "415", "texto": "O período de suspensão do prazo prescricional é regulado pelo máximo da pena cominada.", "vinculante": false, "materia": "Direito Penal – Prescrição", "orgao": "Terceira Seção", "data": "09/12/2009"}, {"tribunal": "STJ", "n": "416", "texto": "É devida a pensão por morte aos dependentes do segurado que, apesar de ter perdido essa qualidade, preencheu os requisitos legais para a obtenção de aposentadoria até a data do seu óbito.", "vinculante": false, "materia": "Direito Previdenciário – dos Benefícios Previdenciários", "orgao": "Terceira Seção", "data": "09/12/2009"}, {"tribunal": "STJ", "n": "417", "texto": "Na execução civil, a penhora de dinheiro na ordem de nomeação de bens não tem caráter absoluto.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Corte Especial", "data": "03/03/2010"}, {"tribunal": "STJ", "n": "418", "texto": "É inadmissível o recurso especial interposto antes da publicação do acórdão dos embargos de declaração, sem posterior ratificação. A Corte Especial, na sessão de 1º de julho de 2016, determinou o CANCELAMENTO da Súmula n. 418-STJ.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "01/07/2016"}, {"tribunal": "STJ", "n": "419", "texto": "Descabe a prisão civil do depositário judicial infiel.", "vinculante": false, "materia": "Direito Civil – Prisão Civil", "orgao": "Corte Especial", "data": "03/03/2010"}, {"tribunal": "STJ", "n": "420", "texto": "Incabível, em embargos de divergência, discutir o valor de indenização por danos morais.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "03/03/2010"}, {"tribunal": "STJ", "n": "421", "texto": "Os honorários advocatícios não são devidos à Defensoria Pública quando ela atua contra a pessoa jurídica de direito público à qual pertença.", "vinculante": false, "materia": "Direito Processual Civil – Honorários Advocatícios", "orgao": "Corte Especial", "data": "03/03/2010"}, {"tribunal": "STJ", "n": "422", "texto": "O art. 6º, e, da Lei n. 4.380/1964 não estabelece limitação aos juros remuneratórios nos contratos vinculados ao SFH.", "vinculante": false, "materia": "Direito Bancário – Sistema Financeiro da Habitação", "orgao": "Corte Especial", "data": "03/03/2010"}, {"tribunal": "STJ", "n": "423", "texto": "A Contribuição para Financiamento da Seguridade Social ? Cofins incide sobre as receitas provenientes das operações de locação de bens móveis.", "vinculante": false, "materia": "Direito Tributário – Contribuição Para Financiamento da Seguridade Social", "orgao": "Primeira Seção", "data": "10/03/2010"}, {"tribunal": "STJ", "n": "424", "texto": "É legítima a incidência de ISS sobre os serviços bancários congêneres da lista anexa ao DL n. 406/1968 e à LC n. 56/1987.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Serviços", "orgao": "Primeira Seção", "data": "10/03/2010"}, {"tribunal": "STJ", "n": "425", "texto": "A retenção da contribuição para a seguridade social pelo tomador do serviço não se aplica às empresas optantes pelo Simples.", "vinculante": false, "materia": "Direito Tributário – Sistema Integrado de Pagamento de Impostos e Contribuições Das", "orgao": "Primeira Seção", "data": "10/03/2010"}, {"tribunal": "STJ", "n": "426", "texto": "Os juros de mora na indenização do seguro DPVAT fluem a partir da citação.", "vinculante": false, "materia": "Direito Civil – Dpvat", "orgao": "Segunda Seção", "data": "10/03/2010"}, {"tribunal": "STJ", "n": "427", "texto": "A ação de cobrança de diferenças de valores de complementação de aposentadoria prescreve em cinco anos contados da data do pagamento.", "vinculante": false, "materia": "Direito Previdenciário – Previdência Privada", "orgao": "Segunda Seção", "data": "10/03/2010"}, {"tribunal": "STJ", "n": "428", "texto": "Compete ao Tribunal Regional Federal decidir os conflitos de competência entre juizado especial federal e juízo federal da mesma seção judiciária.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Corte Especial", "data": "17/03/2010"}, {"tribunal": "STJ", "n": "429", "texto": "A citação postal, quando autorizada por lei, exige o aviso de recebimento.", "vinculante": false, "materia": "Direito Processual Civil – Citação", "orgao": "Corte Especial", "data": "17/03/2010"}, {"tribunal": "STJ", "n": "430", "texto": "O inadimplemento da obrigação tributária pela sociedade não gera, por si só, a responsabilidade solidária do sócio-gerente.", "vinculante": false, "materia": "Direito Processual Civil – Execução Fiscal", "orgao": "Primeira Seção", "data": "24/03/2010"}, {"tribunal": "STJ", "n": "431", "texto": "É ilegal a cobrança de ICMS com base no valor da mercadoria submetido ao regime de pauta fiscal.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Circulação de Mercadorias e Serviços", "orgao": "Primeira Seção", "data": "24/03/2010"}, {"tribunal": "STJ", "n": "432", "texto": "As empresas de construção civil não estão obrigadas a pagar ICMS sobre mercadorias adquiridas como insumos em operações interestaduais.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Circulação de Mercadorias e Serviços", "orgao": "Primeira Seção", "data": "24/03/2010"}, {"tribunal": "STJ", "n": "433", "texto": "O produto semi-elaborado, para fins de incidência de ICMS, é aquele que preenche cumulativamente os três requisitos do art. 1º da Lei Complementar n. 65/1991.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Circulação de Mercadorias e Serviços", "orgao": "Primeira Seção", "data": "24/03/2010"}, {"tribunal": "STJ", "n": "434", "texto": "O pagamento da multa por infração de trânsito não inibe a discussão judicial do débito.", "vinculante": false, "materia": "Direito Administrativo – Código de Trânsito Brasileiro", "orgao": "Primeira Seção", "data": "24/03/2010"}, {"tribunal": "STJ", "n": "435", "texto": "Presume-se dissolvida irregularmente a empresa que deixar de funcionar no seu domicílio fiscal, sem comunicação aos órgãos competentes, legitimando o redirecionamento da execução fiscal para o sócio-gerente.", "vinculante": false, "materia": "Direito Processual Civil – Execução Fiscal", "orgao": "Primeira Seção", "data": "14/04/2010"}, {"tribunal": "STJ", "n": "436", "texto": "A entrega de declaração pelo contribuinte reconhecendo débito fiscal constitui o crédito tributário, dispensada qualquer outra providência por parte do fisco.", "vinculante": false, "materia": "Direito Tributário – Crédito Tributário", "orgao": "Primeira Seção", "data": "14/04/2010"}, {"tribunal": "STJ", "n": "437", "texto": "A suspensão da exigibilidade do crédito tributário superior a quinhentos mil reais para opção pelo Refis pressupõe a homologação expressa do comitê gestor e a constituição de garantia por meio do arrolamento de bens.", "vinculante": false, "materia": "Direito Tributário – Programa de Recuperação Fiscal", "orgao": "Primeira Seção", "data": "14/04/2010"}, {"tribunal": "STJ", "n": "438", "texto": "É inadmissível a extinção da punibilidade pela prescrição da pretensão punitiva com fundamento em pena hipotética, independentemente da existência ou sorte do processo penal.", "vinculante": false, "materia": "Direito Penal – Extinção da Punibilidade", "orgao": "Terceira Seção", "data": "28/04/2010"}, {"tribunal": "STJ", "n": "439", "texto": "Admite-se o exame criminológico pelas peculiaridades do caso, desde que em decisão motivada.", "vinculante": false, "materia": "Direito Penal – Execução Penal", "orgao": "Terceira Seção", "data": "28/04/2010"}, {"tribunal": "STJ", "n": "440", "texto": "Fixada a pena-base no mínimo legal, é vedado o estabelecimento de regime prisional mais gravoso do que o cabível em razão da sanção imposta, com base apenas na gravidade abstrata do delito.", "vinculante": false, "materia": "Direito Penal – das Penas", "orgao": "Terceira Seção", "data": "28/04/2010"}, {"tribunal": "STJ", "n": "441", "texto": "A falta grave não interrompe o prazo para obtenção de livramento condicional.", "vinculante": false, "materia": "Direito Penal – Execução Penal", "orgao": "Terceira Seção", "data": "28/04/2010"}, {"tribunal": "STJ", "n": "442", "texto": "É inadmissível aplicar, no furto qualificado, pelo concurso de agentes, a majorante do roubo.", "vinculante": false, "materia": "Direito Penal – das Penas", "orgao": "Terceira Seção", "data": "28/04/2010"}, {"tribunal": "STJ", "n": "443", "texto": "O aumento na terceira fase de aplicação da pena no crime de roubo circunstanciado exige fundamentação concreta, não sendo suficiente para a sua exasperação a mera indicação do número de majorantes.", "vinculante": false, "materia": "Direito Penal – das Penas", "orgao": "Terceira Seção", "data": "28/04/2010"}, {"tribunal": "STJ", "n": "444", "texto": "É vedada a utilização de inquéritos policiais e ações penais em curso para agravar a pena-base.", "vinculante": false, "materia": "Direito Penal – das Penas", "orgao": "Terceira Seção", "data": "28/04/2010"}, {"tribunal": "STJ", "n": "445", "texto": "As diferenças de correção monetária resultantes de expurgos inflacionários sobre os saldos de FGTS têm como termo inicial a data em que deveriam ter sido creditadas.", "vinculante": false, "materia": "Direito Administrativo – Fundo de Garantia Por Tempo de Serviço", "orgao": "Primeira Seção", "data": "28/04/2010"}, {"tribunal": "STJ", "n": "446", "texto": "Declarado e não pago o débito tributário pelo contribuinte, é legítima a recusa de expedição de certidão negativa ou positiva com efeito de negativa.", "vinculante": false, "materia": "Direito Tributário – Crédito Tributário", "orgao": "Primeira Seção", "data": "28/04/2010"}, {"tribunal": "STJ", "n": "447", "texto": "Os Estados e o Distrito Federal são partes legítimas na ação de restituição de imposto de renda retido na fonte proposta por seus servidores.", "vinculante": false, "materia": "Direito Tributário – Imposto de Renda", "orgao": "Primeira Seção", "data": "28/04/2010"}, {"tribunal": "STJ", "n": "448", "texto": "A opção pelo Simples de estabelecimentos dedicados às atividades de creche, pré-escola e ensino fundamental é admitida somente a partir de 24/10/2000, data de vigência da Lei n. 10.034/2000.", "vinculante": false, "materia": "Direito Tributário – Sistema Integrado de Pagamento de Impostos e Contribuições Das", "orgao": "Primeira Seção", "data": "28/04/2010"}, {"tribunal": "STJ", "n": "449", "texto": "A vaga de garagem que possui matrícula própria no registro de imóveis não constitui bem de família para efeito de penhora.", "vinculante": false, "materia": "Direito Processual Civil – Bem de Família", "orgao": "Corte Especial", "data": "02/06/2010"}, {"tribunal": "STJ", "n": "450", "texto": "Nos contratos vinculados ao SFH, a atualização do saldo devedor antecede sua amortização pelo pagamento da prestação.", "vinculante": false, "materia": "Direito Bancário – Sistema Financeiro da Habitação", "orgao": "Corte Especial", "data": "02/06/2010"}, {"tribunal": "STJ", "n": "451", "texto": "É legítima a penhora da sede do estabelecimento comercial.", "vinculante": false, "materia": "Direito Processual Civil – Execução Fiscal", "orgao": "Corte Especial", "data": "02/06/2010"}, {"tribunal": "STJ", "n": "452", "texto": "A extinção das ações de pequeno valor é faculdade da Administração Federal, vedada a atuação judicial de ofício.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Corte Especial", "data": "02/06/2010"}, {"tribunal": "STJ", "n": "453", "texto": "Os honorários sucumbenciais, quando omitidos em decisão transitada em julgado, não podem ser cobrados em execução ou em ação própria.", "vinculante": false, "materia": "Direito Processual Civil – Honorários Advocatícios", "orgao": "Corte Especial", "data": "18/08/2010"}, {"tribunal": "STJ", "n": "454", "texto": "Pactuada a correção monetária nos contratos do SFH pelo mesmo índice aplicável à caderneta de poupança, incide a taxa referencial (TR) a partir da vigência da Lei n. 8.177/1991.", "vinculante": false, "materia": "Direito Bancário – Sistema Financeiro da Habitação", "orgao": "Corte Especial", "data": "18/08/2010"}, {"tribunal": "STJ", "n": "455", "texto": "A decisão que determina a produção antecipada de provas com base no art. 366 do CPP deve ser concretamente fundamentada, não a justificando unicamente o mero decurso do tempo.", "vinculante": false, "materia": "Direito Processual Penal – Provas", "orgao": "Terceira Seção", "data": "25/08/2010"}, {"tribunal": "STJ", "n": "456", "texto": "É incabível a correção monetária dos salários de contribuição considerados no cálculo do salário de benefício de auxílio-doença, aposentadoria por invalidez, pensão ou auxílio-reclusão concedidos antes da vigência da CF/1988.", "vinculante": false, "materia": "Direito Previdenciário – dos Benefícios Previdenciários", "orgao": "Terceira Seção", "data": "25/08/2010"}, {"tribunal": "STJ", "n": "457", "texto": "Os descontos incondicionais nas operações mercantis não se incluem na base de cálculo do ICMS.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Circulação de Mercadorias e Serviços", "orgao": "Primeira Seção", "data": "25/08/2010"}, {"tribunal": "STJ", "n": "458", "texto": "A contribuição previdenciária incide sobre a comissão paga ao corretor de seguros.", "vinculante": false, "materia": "Direito Previdenciário – Contribuições Previdenciárias", "orgao": "Primeira Seção", "data": "25/08/2010"}, {"tribunal": "STJ", "n": "459", "texto": "A Taxa Referencial (TR) é o índice aplicável, a título de correção monetária, aos débitos com o FGTS recolhidos pelo empregador mas não repassados ao fundo.", "vinculante": false, "materia": "Direito Administrativo – Fundo de Garantia Por Tempo de Serviço", "orgao": "Primeira Seção", "data": "25/08/2010"}, {"tribunal": "STJ", "n": "460", "texto": "É incabível o mandado de segurança para convalidar a compensação tributária realizada pelo contribuinte.", "vinculante": false, "materia": "Direito Tributário – Compensação de Créditos Tributários", "orgao": "Primeira Seção", "data": "25/08/2010"}, {"tribunal": "STJ", "n": "461", "texto": "O contribuinte pode optar por receber, por meio de precatório ou por compensação, o indébito tributário certificado por sentença declaratória transitada em julgado.", "vinculante": false, "materia": "Direito Tributário – Compensação", "orgao": "Primeira Seção", "data": "25/08/2010"}, {"tribunal": "STJ", "n": "462", "texto": "Nas ações em que representa o FGTS, a CEF, quando sucumbente, não está isenta de reembolsar as custas antecipadas pela parte vencedora.", "vinculante": false, "materia": "Direito Processual Civil – Sucumbência", "orgao": "Primeira Seção", "data": "25/08/2010"}, {"tribunal": "STJ", "n": "463", "texto": "Incide imposto de renda sobre os valores percebidos a título de indenização por horas extraordinárias trabalhadas, ainda que decorrentes de acordo coletivo.", "vinculante": false, "materia": "Direito Tributário – Imposto de Renda", "orgao": "Primeira Seção", "data": "25/08/2010"}, {"tribunal": "STJ", "n": "464", "texto": "A regra de imputação de pagamentos estabelecida no art. 354 do Código Civil não se aplica às hipóteses de compensação tributária.", "vinculante": false, "materia": "Direito Tributário – Compensação", "orgao": "Primeira Seção", "data": "25/08/2010"}, {"tribunal": "STJ", "n": "465", "texto": "Ressalvada a hipótese de efetivo agravamento do risco, a seguradora não se exime do dever de indenizar em razão da transferência do veículo sem a sua prévia comunicação.", "vinculante": false, "materia": "Direito Civil – Contrato de Seguro", "orgao": "Segunda Seção", "data": "13/10/2010"}, {"tribunal": "STJ", "n": "466", "texto": "O titular da conta vinculada ao FGTS tem o direito de sacar o saldo respectivo quando declarado nulo seu contrato de trabalho por ausência de prévia aprovação em concurso público.", "vinculante": false, "materia": "Direito Administrativo – Fundo de Garantia Por Tempo de Serviço", "orgao": "Primeira Seção", "data": "13/10/2010"}, {"tribunal": "STJ", "n": "467", "texto": "Prescreve em cinco anos, contados do término do processo administrativo, a pretensão da Administração Pública de promover a execução da multa por infração ambiental.", "vinculante": false, "materia": "Direito Ambiental – Multa", "orgao": "Primeira Seção", "data": "13/10/2010"}, {"tribunal": "STJ", "n": "468", "texto": "A base de cálculo do PIS, até a edição da MP n. 1.212/1995, era o faturamento ocorrido no sexto mês anterior ao do fato gerador.", "vinculante": false, "materia": "Direito Previdenciário – Contribuições Previdenciárias", "orgao": "Primeira Seção", "data": "13/10/2010"}, {"tribunal": "STJ", "n": "469", "texto": "Aplica-se o Código de Defesa do Consumidor aos contratos de plano de saúde. A Segunda Seção, na sessão de 11 de abril de 2018, ao apreciar o Projeto de Súmula n. 937, determinou o CANCELAMENTO da Súmula n. 469-STJ.", "vinculante": false, "materia": "Direito do Consumidor – Plano de Saúde", "orgao": "Segunda Seção", "data": "24/11/2010"}, {"tribunal": "STJ", "n": "470", "texto": "O Ministério Público não tem legitimidade para pleitear, em ação civil pública, a indenização decorrente do DPVAT em benefício do segurado. A Segunda Seção, na sessão de 27 de maio de 2015, ao julgar o REsp 858.056-GO, determinou o CANCELAMENTO da Súmula n. 470-STJ.", "vinculante": false, "materia": "Direito Civil – Dpvat", "orgao": "Segunda Seção", "data": "27/05/2015"}, {"tribunal": "STJ", "n": "471", "texto": "Os condenados por crimes hediondos ou assemelhados cometidos antes da vigência da Lei n. 11.464/2007 sujeitam-se ao disposto no art. 112 da Lei n. 7.210/1984 (Lei de Execução Penal) para a progressão de regime prisional.", "vinculante": false, "materia": "Direito Penal – Execução Penal", "orgao": "Terceira Seção", "data": "23/02/2011"}, {"tribunal": "STJ", "n": "472", "texto": "A cobrança de comissão de permanência - cujo valor não pode ultrapassar a soma dos encargos remuneratórios e moratórios previstos no contrato - exclui a exigibilidade dos juros remuneratórios, moratórios e da multa contratual.", "vinculante": false, "materia": "Direito Bancário – Contrato Bancário", "orgao": "Segunda Seção", "data": "13/06/2012"}, {"tribunal": "STJ", "n": "473", "texto": "O mutuário do SFH não pode ser compelido a contratar o seguro habitacional obrigatório com a instituição financeira mutuante ou com a seguradora por ela indicada.", "vinculante": false, "materia": "Direito Bancário – Sistema Financeiro da Habitação", "orgao": "Segunda Seção", "data": "13/06/2012"}, {"tribunal": "STJ", "n": "474", "texto": "A indenização do seguro DPVAT, em caso de invalidez parcial do beneficiário, será paga de forma proporcional ao grau da invalidez.", "vinculante": false, "materia": "Direito Civil – Dpvat", "orgao": "Segunda Seção", "data": "13/06/2012"}, {"tribunal": "STJ", "n": "475", "texto": "Responde pelos danos decorrentes de protesto indevido o endossatário que recebe por endosso translativo título de crédito contendo vício formal extrínseco ou intrínseco, ficando ressalvado seu direito de regresso contra os endossantes e avalistas.", "vinculante": false, "materia": "Direito Empresarial – Títulos de Crédito", "orgao": "Segunda Seção", "data": "13/06/2012"}, {"tribunal": "STJ", "n": "476", "texto": "O endossatário de título de crédito por endosso-mandato só responde por danos decorrentes de protesto indevido se extrapolar os poderes de mandatário.", "vinculante": false, "materia": "Direito Empresarial – Títulos de Crédito", "orgao": "Segunda Seção", "data": "13/06/2012"}, {"tribunal": "STJ", "n": "477", "texto": "A decadência do art. 26 do CDC não é aplicável à prestação de contas para obter esclarecimentos sobre cobrança de taxas, tarifas e encargos bancários.", "vinculante": false, "materia": "Direito Processual Civil – Ação de Prestação de Contas", "orgao": "Segunda Seção", "data": "13/06/2012"}, {"tribunal": "STJ", "n": "478", "texto": "Na execução de crédito relativo a cotas condominiais, este tem preferência sobre o hipotecário.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Segunda Seção", "data": "13/06/2012"}, {"tribunal": "STJ", "n": "479", "texto": "As instituições financeiras respondem objetivamente pelos danos gerados por fortuito interno relativo a fraudes e delitos praticados por terceiros no âmbito de operações bancárias.", "vinculante": false, "materia": "Direito do Consumidor – Responsabilidade Civil do Fornecedor", "orgao": "Segunda Seção", "data": "27/06/2012"}, {"tribunal": "STJ", "n": "480", "texto": "O juízo da recuperação judicial não é competente para decidir sobre a constrição de bens não abrangidos pelo plano de recuperação da empresa.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Segunda Seção", "data": "27/06/2012"}, {"tribunal": "STJ", "n": "481", "texto": "Faz jus ao benefício da justiça gratuita a pessoa jurídica com ou sem fins lucrativos que demonstrar sua impossibilidade de arcar com os encargos processuais.", "vinculante": false, "materia": "Direito Processual Civil – Assistência Judiciária", "orgao": "Corte Especial", "data": "28/06/2012"}, {"tribunal": "STJ", "n": "482", "texto": "A falta de ajuizamento da ação principal no prazo do art. 806 do CPC acarreta a perda da eficácia da liminar deferida e a extinção do processo cautelar.", "vinculante": false, "materia": "Direito Processual Civil – Processo Cautelar", "orgao": "Corte Especial", "data": "28/06/2012"}, {"tribunal": "STJ", "n": "483", "texto": "O INSS não está obrigado a efetuar depósito prévio do preparo por gozar das prerrogativas e privilégios da Fazenda Pública.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "28/06/2012"}, {"tribunal": "STJ", "n": "484", "texto": "Admite-se que o preparo seja efetuado no primeiro dia útil subsequente, quando a interposição do recurso ocorrer após o encerramento do expediente bancário.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "28/06/2012"}, {"tribunal": "STJ", "n": "485", "texto": "A Lei de Arbitragem aplica-se aos contratos que contenham cláusula arbitral, ainda que celebrados antes da sua edição.", "vinculante": false, "materia": "Direito Processual Civil – Arbitragem", "orgao": "Corte Especial", "data": "28/06/2012"}, {"tribunal": "STJ", "n": "486", "texto": "É impenhorável o único imóvel residencial do devedor que esteja locado a terceiros, desde que a renda obtida com a locação seja revertida para a subsistência ou a moradia da sua família.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Corte Especial", "data": "28/06/2012"}, {"tribunal": "STJ", "n": "487", "texto": "O parágrafo único do art. 741 do CPC não se aplica às sentenças transitadas em julgado em data anterior à da sua vigência.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Corte Especial", "data": "28/06/2012"}, {"tribunal": "STJ", "n": "488", "texto": "O § 2º do art. 6º da Lei n. 9.469/1997, que obriga à repartição dos honorários advocatícios, é inaplicável a acordos ou transações celebrados em data anterior à sua vigência.", "vinculante": false, "materia": "Direito Processual Civil – Honorários Advocatícios", "orgao": "Corte Especial", "data": "28/06/2012"}, {"tribunal": "STJ", "n": "489", "texto": "Reconhecida a continência, devem ser reunidas na Justiça Federal as ações civis públicas propostas nesta e na Justiça estadual.", "vinculante": false, "materia": "Direito Processual Civil – Continência", "orgao": "Corte Especial", "data": "28/06/2012"}, {"tribunal": "STJ", "n": "490", "texto": "A dispensa de reexame necessário, quando o valor da condenação ou do direito controvertido for inferior a sessenta salários mínimos, não se aplica a sentenças ilíquidas.", "vinculante": false, "materia": "Direito Processual Civil – Reexame Necessário", "orgao": "Corte Especial", "data": "28/06/2012"}, {"tribunal": "STJ", "n": "491", "texto": "É inadmissível a chamada progressão per saltum de regime prisional.", "vinculante": false, "materia": "Direito Penal – Progressão de Regime Prisional", "orgao": "Terceira Seção", "data": "08/08/2012"}, {"tribunal": "STJ", "n": "492", "texto": "O ato infracional análogo ao tráfico de drogas, por si só, não conduz obrigatoriamente à imposição de medida socioeducativa de internação do adolescente.", "vinculante": false, "materia": "Direito Penal – Estatuto da Criança e Do Adolescente", "orgao": "Terceira Seção", "data": "08/08/2012"}, {"tribunal": "STJ", "n": "493", "texto": "É inadmissível a fixação de pena substitutiva (art. 44 do CP) como condição especial ao regime aberto.", "vinculante": false, "materia": "Direito Penal – das Penas", "orgao": "Terceira Seção", "data": "08/08/2012"}, {"tribunal": "STJ", "n": "494", "texto": "O benefício fiscal do ressarcimento do crédito presumido do IPI relativo às exportações incide mesmo quando as matérias-primas ou os insumos sejam adquiridos de pessoa física ou jurídica não contribuinte do PIS/PASEP.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Produtos Industrializados", "orgao": "Primeira Seção", "data": "08/08/2012"}, {"tribunal": "STJ", "n": "495", "texto": "A aquisição de bens integrantes do ativo permanente da empresa não gera direito a creditamento de IPI.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Produtos Industrializados", "orgao": "Primeira Seção", "data": "08/08/2012"}, {"tribunal": "STJ", "n": "496", "texto": "Os registros de propriedade particular de imóveis situados em terrenos de marinha não são oponíveis à União.", "vinculante": false, "materia": "Direito Administrativo – Terreno de Marinha", "orgao": "Primeira Seção", "data": "08/08/2012"}, {"tribunal": "STJ", "n": "497", "texto": "Os créditos das autarquias federais preferem aos créditos da Fazenda estadual desde que coexistam penhoras sobre o mesmo bem.", "vinculante": false, "materia": "Direito Processual Civil – Execução Fiscal", "orgao": "Primeira Seção", "data": "08/08/2012"}, {"tribunal": "STJ", "n": "498", "texto": "Não incide imposto de renda sobre a indenização por danos morais.", "vinculante": false, "materia": "Direito Tributário – Imposto de Renda", "orgao": "Primeira Seção", "data": "08/08/2012"}, {"tribunal": "STJ", "n": "499", "texto": "As empresas prestadoras de serviços estão sujeitas às contribuições ao Sesc e Senac, salvo se integradas noutro serviço social.", "vinculante": false, "materia": "Direito Tributário – Contribuições Sociais", "orgao": "Primeira Seção", "data": "13/03/2013"}, {"tribunal": "STJ", "n": "500", "texto": "A configuração do crime do art. 244-B do ECA independe da prova da efetiva corrupção do menor, por se tratar de delito formal.", "vinculante": false, "materia": "Direito Penal – Corrupção de Menores", "orgao": "Terceira Seção", "data": "23/10/2013"}, {"tribunal": "STJ", "n": "501", "texto": "É cabível a aplicação retroativa da Lei n. 11.343/2006, desde que o resultado da incidência das suas disposições, na íntegra, seja mais favorável ao réu do que o advindo da aplicação da Lei n. 6.368/1976, sendo vedada a combinação de leis.", "vinculante": false, "materia": "Direito Penal – Aplicação da Lei Penal", "orgao": "Terceira Seção", "data": "23/10/2013"}, {"tribunal": "STJ", "n": "502", "texto": "Presentes a materialidade e a autoria, afigura-se típica, em relação ao crime previsto no art. 184, § 2º, do CP, a conduta de expor à venda CDs e DVDs piratas.", "vinculante": false, "materia": "Direito Penal – Violação de Direito Autoral", "orgao": "Terceira Seção", "data": "23/10/2013"}, {"tribunal": "STJ", "n": "503", "texto": "O prazo para ajuizamento de ação monitória em face do emitente de cheque sem força executiva é quinquenal, a contar do dia seguinte à data de emissão estampada na cártula.", "vinculante": false, "materia": "Direito Processual Civil – Ação Monitória", "orgao": "Segunda Seção", "data": "11/12/2013"}, {"tribunal": "STJ", "n": "504", "texto": "O prazo para ajuizamento de ação monitória em face do emitente de nota promissória sem força executiva é quinquenal, a contar do dia seguinte ao vencimento do título.", "vinculante": false, "materia": "Direito Processual Civil – Ação Monitória", "orgao": "Segunda Seção", "data": "11/12/2013"}, {"tribunal": "STJ", "n": "505", "texto": "A competência para processar e julgar as demandas que têm por objeto obrigações decorrentes dos contratos de planos de previdência privada firmados com a Fundação Rede Ferroviária de Seguridade Social - REFER é da Justiça estadual.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Segunda Seção", "data": "11/12/2013"}, {"tribunal": "STJ", "n": "506", "texto": "A Anatel não é parte legítima nas demandas entre a concessionária e o usuário de telefonia decorrentes de relação contratual.", "vinculante": false, "materia": "Direito Processual Civil – Partes e Procuradores", "orgao": "Primeira Seção", "data": "26/03/2014"}, {"tribunal": "STJ", "n": "507", "texto": "A acumulação de auxílio-acidente com aposentadoria pressupõe que a lesão incapacitante e a aposentadoria sejam anteriores a 11/11/1997, observado o critério do art. 23 da Lei n. 8.213/1991 para definição do momento da lesão nos casos de doença profissional ou do trabalho.", "vinculante": false, "materia": "Direito Previdenciário – Benefícios Previdenciários", "orgao": "Primeira Seção", "data": "26/03/2014"}, {"tribunal": "STJ", "n": "508", "texto": "A isenção da Cofins concedida pelo art. 6º, II, da LC n. 70/1991 às sociedades civis de prestação de serviços profissionais foi revogada pelo art. 56 da Lei n. 9.430/1996.", "vinculante": false, "materia": "Direito Tributário – Isenção", "orgao": "Primeira Seção", "data": "26/03/2014"}, {"tribunal": "STJ", "n": "509", "texto": "É lícito ao comerciante de boa-fé aproveitar os créditos de ICMS decorrentes de nota fiscal posteriormente declarada inidônea, quando demonstrada a veracidade da compra e venda.", "vinculante": false, "materia": "Direito Tributário – Crédito Tributário", "orgao": "Primeira Seção", "data": "26/03/2014"}, {"tribunal": "STJ", "n": "510", "texto": "A liberação de veículo retido apenas por transporte irregular de passageiros não está condicionada ao pagamento de multas e despesas.", "vinculante": false, "materia": "Direito Administrativo – Código de Trânsito Brasileiro", "orgao": "Primeira Seção", "data": "26/03/2014"}, {"tribunal": "STJ", "n": "511", "texto": "É possível o reconhecimento do privilégio previsto no § 2º do art. 155 do CP nos casos de crime de furto qualificado, se estiverem presentes a primariedade do agente, o pequeno valor da coisa e a qualificadora for de ordem objetiva.", "vinculante": false, "materia": "Direito Penal – das Penas", "orgao": "Terceira Seção", "data": "11/06/2014"}, {"tribunal": "STJ", "n": "512", "texto": "A aplicação da causa de diminuição de pena prevista no art. 33, § 4º, da Lei n. 11.343/2006 não afasta a hediondez do crime de tráfico de drogas. A Terceira Seção, na sessão de 23 de novembro de 2016, ao julgar a QO na Pet 11.796-DF, determinou o CANCELAMENTO da Súmula n. 512-STJ.", "vinculante": false, "materia": "Direito Penal – das Penas", "orgao": "Terceira Seção", "data": "23/11/2016"}, {"tribunal": "STJ", "n": "513", "texto": "A 'abolitio criminis' temporária prevista na Lei n. 10.826/2003 aplica-se ao crime de posse de arma de fogo de uso permitido com numeração, marca ou qualquer outro sinal de identificação raspado, suprimido ou adulterado, praticado somente até 23/10/2005.", "vinculante": false, "materia": "Direito Penal – Aplicação da Lei Penal", "orgao": "Terceira Seção", "data": "11/06/2014"}, {"tribunal": "STJ", "n": "514", "texto": "A CEF é responsável pelo fornecimento dos extratos das contas individualizadas vinculadas ao FGTS dos Trabalhadores participantes do Fundo de Garantia do Tempo de Serviço, inclusive para fins de exibição em juízo, independentemente do período em discussão.", "vinculante": false, "materia": "Direito Administrativo – Fundo de Garantia Por Tempo de Serviço", "orgao": "Primeira Seção", "data": "14/08/2014"}, {"tribunal": "STJ", "n": "515", "texto": "A reunião de execuções fiscais contra o mesmo devedor constitui faculdade do Juiz.", "vinculante": false, "materia": "Direito Processual Civil – Execução Fiscal", "orgao": "Primeira Seção", "data": "14/08/2014"}, {"tribunal": "STJ", "n": "516", "texto": "A contribuição de intervenção no domínio econômico para o Incra (Decreto-Lei n. 1.110/1970), devida por empregadores rurais e urbanos, não foi extinta pelas Leis ns. 7.787/1989, 8.212/1991 e 8.213/1991, não podendo ser compensada com a contribuição ao INSS.", "vinculante": false, "materia": "Direito Tributário – Contribuição de Intervenção no Domínio Econômico Para o Incra", "orgao": "Primeira Seção", "data": "25/02/2015"}, {"tribunal": "STJ", "n": "517", "texto": "São devidos honorários advocatícios no cumprimento de sentença, haja ou não impugnação, depois de escoado o prazo para pagamento voluntário, que se inicia após a intimação do advogado da parte executada.", "vinculante": false, "materia": "Direito Processual Civil – Honorários Advocatícios", "orgao": "Corte Especial", "data": "26/02/2015"}, {"tribunal": "STJ", "n": "518", "texto": "Para fins do art. 105, III, a, da Constituição Federal, não é cabível recurso especial fundado em alegada violação de enunciado de súmula.", "vinculante": false, "materia": "Direito Processual Civil – Cabimento do Recurso Especial", "orgao": "Corte Especial", "data": "26/02/2015"}, {"tribunal": "STJ", "n": "519", "texto": "Na hipótese de rejeição da impugnação ao cumprimento de sentença, não são cabíveis honorários advocatícios.", "vinculante": false, "materia": "Direito Processual Civil – Honorários Advocatícios", "orgao": "Corte Especial", "data": "26/02/2015"}, {"tribunal": "STJ", "n": "520", "texto": "O benefício de saída temporária no âmbito da execução penal é ato jurisdicional insuscetível de delegação à autoridade administrativa do estabelecimento prisional.", "vinculante": false, "materia": "Direito Penal – Execução Penal", "orgao": "Terceira Seção", "data": "25/03/2015"}, {"tribunal": "STJ", "n": "521", "texto": "A legitimidade para a execução fiscal de multa pendente de pagamento imposta em sentença condenatória é exclusiva da Procuradoria da Fazenda Pública.", "vinculante": false, "materia": "Direito Processual Penal – Legitimidade", "orgao": "Terceira Seção", "data": "25/03/2015"}, {"tribunal": "STJ", "n": "522", "texto": "A conduta de atribuir-se falsa identidade perante autoridade policial é típica, ainda que em situação de alegada autodefesa.", "vinculante": false, "materia": "Direito Penal – Tipificação Penal", "orgao": "Terceira Seção", "data": "25/03/2015"}, {"tribunal": "STJ", "n": "523", "texto": "A taxa de juros de mora incidente na repetição de indébito de tributos estaduais deve corresponder à utilizada para cobrança do tributo pago em atraso, sendo legítima a incidência da taxa Selic, em ambas as hipóteses, quando prevista na legislação local, vedada sua cumulação com quaisquer outros índices.", "vinculante": false, "materia": "Direito Tributário – Repetição de Indébito", "orgao": "Primeira Seção", "data": "22/04/2015"}, {"tribunal": "STJ", "n": "524", "texto": "No tocante à base de cálculo, o ISSQN incide apenas sobre a taxa de agenciamento quando o serviço prestado por sociedade empresária de trabalho temporário for de intermediação, devendo, entretanto, englobar também os valores dos salários e encargos sociais dos trabalhadores por ela contratados nas hipóteses de fornecimento de mão de obra.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre Serviços", "orgao": "Primeira Seção", "data": "22/04/2015"}, {"tribunal": "STJ", "n": "525", "texto": "A Câmara de Vereadores não possui personalidade jurídica, apenas personalidade judiciária, somente podendo demandar em juízo para defender os seus direitos institucionais.", "vinculante": false, "materia": "Direito Processual Civil – Legitimidade", "orgao": "Primeira Seção", "data": "22/04/2015"}, {"tribunal": "STJ", "n": "526", "texto": "O reconhecimento de falta grave decorrente do cometimento de fato definido como crime doloso no cumprimento da pena prescinde do trânsito em julgado de sentença penal condenatória no processo penal instaurado para apuração do fato.", "vinculante": false, "materia": "Direito Penal – Execução Penal", "orgao": "Terceira Seção", "data": "13/05/2015"}, {"tribunal": "STJ", "n": "527", "texto": "O tempo de duração da medida de segurança não deve ultrapassar o limite máximo da pena abstratamente cominada ao delito praticado.", "vinculante": false, "materia": "Direito Penal – Medida de Segurança", "orgao": "Terceira Seção", "data": "13/05/2015"}, {"tribunal": "STJ", "n": "528", "texto": "Compete ao juiz federal do local da apreensão da droga remetida do exterior pela via postal processar e julgar o crime de tráfico internacional.", "vinculante": false, "materia": "Direito Processual Penal – Competência", "orgao": "Terceira Seção", "data": "13/05/2015"}, {"tribunal": "STJ", "n": "529", "texto": "No seguro de responsabilidade civil facultativo, não cabe o ajuizamento de ação pelo terceiro prejudicado direta e exclusivamente em face da seguradora do apontado causador do dano.", "vinculante": false, "materia": "Direito Civil – Contrato de Seguro", "orgao": "Segunda Seção", "data": "13/05/2015"}, {"tribunal": "STJ", "n": "530", "texto": "Nos contratos bancários, na impossibilidade de comprovar a taxa de juros efetivamente contratada - por ausência de pactuação ou pela falta de juntada do instrumento aos autos -, aplica-se a taxa média de mercado, divulgada pelo Bacen, praticada nas operações da mesma espécie, salvo se a taxa cobrada for mais vantajosa para o devedor.", "vinculante": false, "materia": "Direito Bancário – Contrato Bancário", "orgao": "Segunda Seção", "data": "13/05/2015"}, {"tribunal": "STJ", "n": "531", "texto": "Em ação monitória fundada em cheque prescrito ajuizada contra o emitente, é dispensável a menção ao negócio jurídico subjacente à emissão da cártula.", "vinculante": false, "materia": "Direito Processual Civil – Ação Monitória", "orgao": "Segunda Seção", "data": "13/05/2015"}, {"tribunal": "STJ", "n": "532", "texto": "Constitui prática comercial abusiva o envio de cartão de crédito sem prévia e expressa solicitação do consumidor, configurando-se ato ilícito indenizável e sujeito à aplicação de multa administrativa.", "vinculante": false, "materia": "Direito do Consumidor – Responsabilidade Civil do Fornecedor", "orgao": "Corte Especial", "data": "03/06/2015"}, {"tribunal": "STJ", "n": "533", "texto": "Para o reconhecimento da prática de falta disciplinar no âmbito da execução penal, é imprescindível a instauração de procedimento administrativo pelo diretor do estabelecimento prisional, assegurado o direito de defesa, a ser realizado por advogado constituído ou defensor público nomeado.", "vinculante": false, "materia": "Direito Penal – Execução Penal", "orgao": "Terceira Seção", "data": "10/06/2015"}, {"tribunal": "STJ", "n": "534", "texto": "A prática de falta grave interrompe a contagem do prazo para a progressão de regime de cumprimento de pena, o qual se reinicia a partir do cometimento dessa infração.", "vinculante": false, "materia": "Direito Penal – Execução Penal", "orgao": "Terceira Seção", "data": "10/06/2015"}, {"tribunal": "STJ", "n": "535", "texto": "A prática de falta grave não interrompe o prazo para fim de comutação de pena ou indulto.", "vinculante": false, "materia": "Direito Penal – Execução Penal", "orgao": "Terceira Seção", "data": "10/06/2015"}, {"tribunal": "STJ", "n": "536", "texto": "A suspensão condicional do processo e a transação penal não se aplicam na hipótese de delitos sujeitos ao rito da Lei Maria da Penha.", "vinculante": false, "materia": "Direito Penal – Lei Maria da Penha", "orgao": "Terceira Seção", "data": "10/06/2015"}, {"tribunal": "STJ", "n": "537", "texto": "Em ação de reparação de danos, a seguradora denunciada, se aceitar a denunciação ou contestar o pedido do autor, pode ser condenada, direta e solidariamente junto com o segurado, ao pagamento da indenização devida à vítima, nos limites contratados na apólice.", "vinculante": false, "materia": "Direito Civil – Contrato de Seguro", "orgao": "Segunda Seção", "data": "10/06/2015"}, {"tribunal": "STJ", "n": "538", "texto": "As administradoras de consórcio têm liberdade para estabelecer a respectiva taxa de administração, ainda que fixada em percentual superior a dez por cento.", "vinculante": false, "materia": "Direito do Consumidor – Consórcio", "orgao": "Segunda Seção", "data": "10/06/2015"}, {"tribunal": "STJ", "n": "539", "texto": "É permitida a capitalização de juros com periodicidade inferior à anual em contratos celebrados com instituições integrantes do Sistema Financeiro Nacional a partir de 31/3/2000 (MP n. 1.963-17/2000, reeditada como MP n. 2.170-36/2001), desde que expressamente pactuada.", "vinculante": false, "materia": "Direito Bancário – Contrato Bancário", "orgao": "Segunda Seção", "data": "10/06/2015"}, {"tribunal": "STJ", "n": "540", "texto": "Na ação de cobrança do seguro DPVAT, constitui faculdade do autor escolher entre os foros do seu domicílio, do local do acidente ou ainda do domicílio do réu.", "vinculante": false, "materia": "Direito Civil – Dpvat", "orgao": "Segunda Seção", "data": "10/06/2015"}, {"tribunal": "STJ", "n": "541", "texto": "A previsão no contrato bancário de taxa de juros anual superior ao duodécuplo da mensal é suficiente para permitir a cobrança da taxa efetiva anual contratada.", "vinculante": false, "materia": "Direito Bancário – Contrato Bancário", "orgao": "Segunda Seção", "data": "10/06/2015"}, {"tribunal": "STJ", "n": "542", "texto": "A ação penal relativa ao crime de lesão corporal resultante de violência doméstica contra a mulher é pública incondicionada.", "vinculante": false, "materia": "Direito Processual Penal – Lei Maria da Penha", "orgao": "Terceira Seção", "data": "26/08/2015"}, {"tribunal": "STJ", "n": "543", "texto": "Na hipótese de resolução de contrato de promessa de compra e venda de imóvel submetido ao Código de Defesa do Consumidor, deve ocorrer a imediata restituição das parcelas pagas pelo promitente comprador - integralmente, em caso de culpa exclusiva do promitente vendedor/construtor, ou parcialmente, caso tenha sido o comprador quem deu causa ao desfazimento.", "vinculante": false, "materia": "Direito do Consumidor – Promessa de Compra e Venda de Imóvel", "orgao": "Segunda Seção", "data": "26/08/2015"}, {"tribunal": "STJ", "n": "544", "texto": "É válida a utilização de tabela do Conselho Nacional de Seguros Privados para estabelecer a proporcionalidade da indenização do seguro DPVAT ao grau de invalidez também na hipótese de sinistro anterior a 16/12/2008, data da entrada em vigor da Medida Provisória n. 451/2008.", "vinculante": false, "materia": "Direito Civil – Dpvat", "orgao": "Segunda Seção", "data": "26/08/2015"}, {"tribunal": "STJ", "n": "545", "texto": "Quando a confissão for utilizada para a formação do convencimento do julgador, o réu fará jus à atenuante prevista no art. 65, III, d, do Código Penal.", "vinculante": false, "materia": "Direito Penal – das Penas", "orgao": "Terceira Seção", "data": "14/10/2015"}, {"tribunal": "STJ", "n": "546", "texto": "A competência para processar e julgar o crime de uso de documento falso é firmada em razão da entidade ou órgão ao qual foi apresentado o documento público, não importando a qualificação do órgão expedidor.", "vinculante": false, "materia": "Direito Processual Penal – Competência", "orgao": "Terceira Seção", "data": "14/10/2015"}, {"tribunal": "STJ", "n": "547", "texto": "Nas ações em que se pleiteia o ressarcimento dos valores pagos a título de participação financeira do consumidor no custeio de construção de rede elétrica, o prazo prescricional é de vinte anos na vigência do Código Civil de 1916. Na vigência do Código Civil de 2002, o prazo é de cinco anos se houver previsão contratual de ressarcimento e de três anos na ausência de cláusula nesse sentido, observada a regra de transição disciplinada em seu art. 2.028.", "vinculante": false, "materia": "Direito do Consumidor – Energia Elétrica", "orgao": "Segunda Seção", "data": "14/10/2015"}, {"tribunal": "STJ", "n": "548", "texto": "Incumbe ao credor a exclusão do registro da dívida em nome do devedor no cadastro de inadimplentes no prazo de cinco dias úteis, a partir do integral e efetivo pagamento do débito.", "vinculante": false, "materia": "Direito do Consumidor – Serviço de Proteção ao Crédito", "orgao": "Segunda Seção", "data": "14/10/2015"}, {"tribunal": "STJ", "n": "549", "texto": "É válida a penhora de bem de família pertencente a fiador de contrato de locação.", "vinculante": false, "materia": "Direito Civil – Contrato de Locação", "orgao": "Segunda Seção", "data": "14/10/2015"}, {"tribunal": "STJ", "n": "550", "texto": "A utilização de escore de crédito, método estatístico de avaliação de risco que não constitui banco de dados, dispensa o consentimento do consumidor, que terá o direito de solicitar esclarecimentos sobre as informações pessoais valoradas e as fontes dos dados considerados no respectivo cálculo.", "vinculante": false, "materia": "Direito do Consumidor – Serviço de Proteção ao Crédito", "orgao": "Segunda Seção", "data": "14/10/2015"}, {"tribunal": "STJ", "n": "551", "texto": "Nas demandas por complementação de ações de empresas de telefonia, admite-se a condenação ao pagamento de dividendos e juros sobre capital próprio independentemente de pedido expresso. No entanto, somente quando previstos no título executivo, poderão ser objeto de cumprimento de sentença.", "vinculante": false, "materia": "Direito Processual Civil – Ação Por Complementação de Ações de Empresas de Telefonia", "orgao": "Segunda Seção", "data": "14/10/2015"}, {"tribunal": "STJ", "n": "552", "texto": "O portador de surdez unilateral não se qualifica como pessoa com deficiência para o fim de disputar as vagas reservadas em concursos públicos.", "vinculante": false, "materia": "Direito Administrativo – Concurso Público", "orgao": "Corte Especial", "data": "04/11/2015"}, {"tribunal": "STJ", "n": "553", "texto": "Nos casos de empréstimo compulsório sobre o consumo de energia elétrica, é competente a Justiça estadual para o julgamento de demanda proposta exclusivamente contra a Eletrobrás. Requerida a intervenção da União no feito após a prolação de sentença pelo juízo estadual, os autos devem ser remetidos ao Tribunal Regional Federal competente para o julgamento da apelação se deferida a intervenção.", "vinculante": false, "materia": "Direito Processual Civil – Competência", "orgao": "Primeira Seção", "data": "09/12/2015"}, {"tribunal": "STJ", "n": "554", "texto": "Na hipótese de sucessão empresarial, a responsabilidade da sucessora abrange não apenas os tributos devidos pela sucedida, mas também as multas moratórias ou punitivas referentes a fatos geradores ocorridos até a data da sucessão.", "vinculante": false, "materia": "Direito Empresarial – Sociedades Empresariais", "orgao": "Primeira Seção", "data": "09/12/2015"}, {"tribunal": "STJ", "n": "555", "texto": "Quando não houver declaração do débito, o prazo decadencial quinquenal para o Fisco constituir o crédito tributário conta-se exclusivamente na forma do art. 173, I, do CTN, nos casos em que a legislação atribui ao sujeito passivo o dever de antecipar o pagamento sem prévio exame da autoridade administrativa.", "vinculante": false, "materia": "Direito Tributário – Crédito Tributário", "orgao": "Primeira Seção", "data": "09/12/2015"}, {"tribunal": "STJ", "n": "556", "texto": "É indevida a incidência de imposto de renda sobre o valor da complementação de aposentadoria pago por entidade de previdência privada e em relação ao resgate de contribuições recolhidas para referidas entidades patrocinadoras no período de 1º/1/1989 a 31/12/1995, em razão da isenção concedida pelo art. 6º, VII, b, da Lei n. 7.713/1988, na redação anterior à que lhe foi dada pela Lei n. 9.250/1995.", "vinculante": false, "materia": "Direito Tributário – Imposto de Renda", "orgao": "Primeira Seção", "data": "09/12/2015"}, {"tribunal": "STJ", "n": "557", "texto": "A renda mensal inicial (RMI) alusiva ao benefício de aposentadoria por invalidez precedido de auxílio-doença será apurada na forma do art. 36, § 7º, do Decreto n. 3.048/1999, observando-se, porém, os critérios previstos no art. 29, § 5º, da Lei n. 8.213/1991, quando intercalados períodos de afastamento e de atividade laboral.", "vinculante": false, "materia": "Direito Previdenciário – Aposentadoria Por Invalidez", "orgao": "Primeira Seção", "data": "09/12/2015"}, {"tribunal": "STJ", "n": "558", "texto": "Em ações de execução fiscal, a petição inicial não pode ser indeferida sob o argumento da falta de indicação do CPF e/ou RG ou CNPJ da parte executada.", "vinculante": false, "materia": "Direito Processual Civil – Execução Fiscal", "orgao": "Primeira Seção", "data": "09/12/2015"}, {"tribunal": "STJ", "n": "559", "texto": "Em ações de execução fiscal, é desnecessária a instrução da petição inicial com o demonstrativo de cálculo do débito, por tratar-se de requisito não previsto no art. 6º da Lei n. 6.830/1980.", "vinculante": false, "materia": "Direito Processual Civil – Execução", "orgao": "Primeira Seção", "data": "09/12/2015"}, {"tribunal": "STJ", "n": "560", "texto": "A decretação da indisponibilidade de bens e direitos, na forma do art. 185-A do CTN, pressupõe o exaurimento das diligências na busca por bens penhoráveis, o qual fica caracterizado quando infrutíferos o pedido de constrição sobre ativos financeiros e a expedição de ofícios aos registros públicos do domicílio do executado, ao Denatran ou Detran.", "vinculante": false, "materia": "Direito Tributário – Execução Fiscal", "orgao": "Primeira Seção", "data": "09/12/2015"}, {"tribunal": "STJ", "n": "561", "texto": "Os Conselhos Regionais de Farmácia possuem atribuição para fiscalizar e autuar as farmácias e drogarias quanto ao cumprimento da exigência de manter profissional legalmente habilitado (farmacêutico) durante todo o período de funcionamento dos respectivos estabelecimentos.", "vinculante": false, "materia": "Direito Administrativo – Atividade Farmacêutica", "orgao": "Primeira Seção", "data": "09/12/2015"}, {"tribunal": "STJ", "n": "562", "texto": "É possível a remição de parte do tempo de execução da pena quando o condenado, em regime fechado ou semiaberto, desempenha atividade laborativa, ainda que extramuros.", "vinculante": false, "materia": "Direito Penal – Execução Penal", "orgao": "Terceira Seção", "data": "24/02/2016"}, {"tribunal": "STJ", "n": "563", "texto": "O Código de Defesa do Consumidor é aplicável às entidades abertas de previdência complementar, não incidindo nos contratos previdenciários celebrados com entidades fechadas.", "vinculante": false, "materia": "Direito do Consumidor – Instituições Financeiras", "orgao": "Segunda Seção", "data": "24/02/2016"}, {"tribunal": "STJ", "n": "564", "texto": "No caso de reintegração de posse em arrendamento mercantil financeiro, quando a soma da importância antecipada a título de valor residual garantido (VRG) com o valor da venda do bem ultrapassar o total do VRG previsto contratualmente, o arrendatário terá direito de receber a respectiva diferença, cabendo, porém, se estipulado no contrato, o prévio desconto de outras despesas ou encargos pactuados.", "vinculante": false, "materia": "Direito Empresarial – Arrendamento Mercantil", "orgao": "Segunda Seção", "data": "24/02/2016"}, {"tribunal": "STJ", "n": "565", "texto": "A pactuação das tarifas de abertura de crédito (TAC) e de emissão de carnê (TEC), ou outra denominação para o mesmo fato gerador, é válida apenas nos contratos bancários anteriores ao início da vigência da Resolução-CMN n. 3.518/2007, em 30/4/2008.", "vinculante": false, "materia": "Direito Bancário – Contrato Com Garantia de Alienação Fiduciária", "orgao": "Segunda Seção", "data": "24/02/2016"}, {"tribunal": "STJ", "n": "566", "texto": "Nos contratos bancários posteriores ao início da vigência da Resolução-CMN n. 3.518/2007, em 30/4/2008, pode ser cobrada a tarifa de cadastro no início do relacionamento entre o consumidor e a instituição financeira.", "vinculante": false, "materia": "Direito Bancário – Contrato Com Garantia de Alienação Fiduciária", "orgao": "Segunda Seção", "data": "24/02/2016"}, {"tribunal": "STJ", "n": "567", "texto": "Sistema de vigilância realizado por monitoramento eletrônico ou por existência de segurança no interior de estabelecimento comercial, por si só, não torna impossível a configuração do crime de furto.", "vinculante": false, "materia": "Direito Penal – Crime Impossível", "orgao": "Terceira Seção", "data": "24/02/2016"}, {"tribunal": "STJ", "n": "568", "texto": "O relator, monocraticamente e no Superior Tribunal de Justiça, poderá dar ou negar provimento ao recurso quando houver entendimento dominante acerca do tema.", "vinculante": false, "materia": "Direito Processual Civil – Decisão Monocrática do Relator", "orgao": "Corte Especial", "data": "16/03/2016"}, {"tribunal": "STJ", "n": "569", "texto": "Na importação, é indevida a exigência de nova certidão negativa de débito no desembaraço aduaneiro, se já apresentada a comprovação da quitação de tributos federais quando da concessão do benefício relativo ao regime de drawback.", "vinculante": false, "materia": "Direito Tributário – Certidão Negativa de Débito na Operação de Drawback", "orgao": "Primeira Seção", "data": "27/04/2016"}, {"tribunal": "STJ", "n": "570", "texto": "Compete à Justiça Federal o processo e julgamento de demanda em que se discute a ausência de ou o obstáculo ao credenciamento de instituição particular de ensino superior no Ministério da Educação como condição de expedição de diploma de ensino a distância aos estudantes.", "vinculante": false, "materia": "Direito Administrativo – Diploma de Curso de Ensino Superior", "orgao": "Primeira Seção", "data": "27/04/2016"}, {"tribunal": "STJ", "n": "571", "texto": "A taxa progressiva de juros não se aplica às contas vinculadas ao FGTS de trabalhadores qualificados como avulsos.", "vinculante": false, "materia": "Direito Administrativo – Fundo de Garantia Por Tempo de Serviço", "orgao": "Primeira Seção", "data": "27/04/2016"}, {"tribunal": "STJ", "n": "572", "texto": "O Banco do Brasil, na condição de gestor do Cadastro de Emitentes de Cheques sem Fundos (CCF), não tem a responsabilidade de notificar previamente o devedor acerca da sua inscrição no aludido cadastro, tampouco legitimidade passiva para as ações de reparação de danos fundadas na ausência de prévia comunicação.", "vinculante": false, "materia": "Direito do Consumidor – Inscrição em Cadastro de Inadimplentes", "orgao": "Segunda Seção", "data": "11/05/2016"}, {"tribunal": "STJ", "n": "573", "texto": "Nas ações de indenização decorrente de seguro DPVAT, a ciência inequívoca do caráter permanente da invalidez, para fins de contagem do prazo prescricional, depende de laudo médico, exceto nos casos de invalidez permanente notória ou naqueles em que o conhecimento anterior resulte comprovado na fase de instrução.", "vinculante": false, "materia": "Direito Civil – Dpvat", "orgao": "Segunda Seção", "data": "22/06/2016"}, {"tribunal": "STJ", "n": "574", "texto": "Para a configuração do delito de violação de direito autoral e a comprovação de sua materialidade, é suficiente a perícia realizada por amostragem do produto apreendido, nos aspectos externos do material, e é desnecessária a identificação dos titulares dos direitos autorais violados ou daqueles que os representem.", "vinculante": false, "materia": "Direito Penal – Violação de Direito Autoral", "orgao": "Terceira Seção", "data": "22/06/2016"}, {"tribunal": "STJ", "n": "575", "texto": "Constitui crime a conduta de permitir, confiar ou entregar a direção de veículo automotor a pessoa que não seja habilitada, ou que se encontre em qualquer das situações previstas no art. 310 do CTB, independentemente da ocorrência de lesão ou de perigo de dano concreto na condução do veículo.", "vinculante": false, "materia": "Direito Penal – Tipificação Penal", "orgao": "Terceira Seção", "data": "22/06/2016"}, {"tribunal": "STJ", "n": "576", "texto": "Ausente requerimento administrativo no INSS, o termo inicial para a implantação da aposentadoria por invalidez concedida judicialmente será a data da citação válida.", "vinculante": false, "materia": "Direito Previdenciário – Aposentadoria Por Invalidez", "orgao": "Primeira Seção", "data": "22/06/2016"}, {"tribunal": "STJ", "n": "577", "texto": "É possível reconhecer o tempo de serviço rural anterior ao documento mais antigo apresentado, desde que amparado em convincente prova testemunhal colhida sob o contraditório.", "vinculante": false, "materia": "Direito Previdenciário – Trabalho Rural", "orgao": "Primeira Seção", "data": "22/06/2016"}, {"tribunal": "STJ", "n": "578", "texto": "Os empregados que laboram no cultivo da cana-de-açúcar para empresa agroindustrial ligada ao setor sucroalcooleiro detêm a qualidade de rurícola, ensejando a isenção do FGTS desde a edição da Lei Complementar n. 11/1971 até a promulgação da Constituição Federal de 1988.", "vinculante": false, "materia": "Direito Administrativo – Fundo de Garantia Por Tempo de Serviço", "orgao": "Primeira Seção", "data": "22/06/2016"}, {"tribunal": "STJ", "n": "579", "texto": "Não é necessário ratificar o recurso especial interposto na pendência do julgamento dos embargos de declaração, quando inalterado o resultado anterior.", "vinculante": false, "materia": "Direito Processual Civil – dos Recursos", "orgao": "Corte Especial", "data": "01/07/2016"}, {"tribunal": "STJ", "n": "580", "texto": "A correção monetária nas indenizações do seguro DPVAT por morte ou invalidez, prevista no § 7º do art. 5º da Lei n. 6.194/1974, redação dada pela Lei n. 11.482/2007, incide desde a data do evento danoso.", "vinculante": false, "materia": "Direito Civil – Dpvat", "orgao": "Segunda Seção", "data": "14/09/2016"}, {"tribunal": "STJ", "n": "581", "texto": "A recuperação judicial do devedor principal não impede o prosseguimento das ações e execuções ajuizadas contra terceiros devedores solidários ou coobrigados em geral, por garantia cambial, real ou fidejussória.", "vinculante": false, "materia": "Direito Empresarial – Falência, Concordata e Recuperação Jucicial", "orgao": "Segunda Seção", "data": "14/09/2016"}, {"tribunal": "STJ", "n": "582", "texto": "Consuma-se o crime de roubo com a inversão da posse do bem mediante emprego de violência ou grave ameaça, ainda que por breve tempo e em seguida à perseguição imediata ao agente e recuperação da coisa roubada, sendo prescindível a posse mansa e pacífica ou desvigiada.", "vinculante": false, "materia": "Direito Penal – Tipificação Penal", "orgao": "Terceira Seção", "data": "14/09/2016"}, {"tribunal": "STJ", "n": "583", "texto": "O arquivamento provisório previsto no art. 20 da Lei n. 10.522/2002, dirigido aos débitos inscritos como dívida ativa da União pela Procuradoria-Geral da Fazenda Nacional ou por ela cobrados, não se aplica às execuções fiscais movidas pelos conselhos de fiscalização profissional ou pelas autarquias federais.", "vinculante": false, "materia": "Direito Tributário – Princípio da Insignificância", "orgao": "Primeira Seção", "data": "14/12/2016"}, {"tribunal": "STJ", "n": "584", "texto": "As sociedades corretoras de seguros, que não se confundem com as sociedades de valores mobiliários ou com os agentes autônomos de seguro privado, estão fora do rol de entidades constantes do art. 22, § 1º, da Lei n. 8.212/1991, não se sujeitando à majoração da alíquota da Cofins prevista no art. 18 da Lei n. 10.684/2003.", "vinculante": false, "materia": "Direito Tributário – Contribuição Para Financiamento da Seguridade Social", "orgao": "Primeira Seção", "data": "14/12/2016"}, {"tribunal": "STJ", "n": "585", "texto": "A responsabilidade solidária do ex-proprietário, prevista no art. 134 do Código de Trânsito Brasileiro - CTB, não abrange o IPVA incidente sobre o veículo automotor, no que se refere ao período posterior à sua alienação.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre a Propriedade de Veículos Automotores", "orgao": "Primeira Seção", "data": "14/12/2016"}, {"tribunal": "STJ", "n": "586", "texto": "A exigência de acordo entre o credor e o devedor na escolha do agente fiduciário aplica-se, exclusivamente, aos contratos não vinculados ao Sistema Financeiro da Habitação - SFH.", "vinculante": false, "materia": "Direito Bancário – Sistema Financeiro da Habitação", "orgao": "Corte Especial", "data": "19/12/2016"}, {"tribunal": "STJ", "n": "587", "texto": "Para a incidência da majorante prevista no art. 40, V, da Lei n. 11.343/2006, é desnecessária a efetiva transposição de fronteiras entre estados da Federação, sendo suficiente a demonstração inequívoca da intenção de realizar o tráfico interestadual.", "vinculante": false, "materia": "Direito Penal – das Penas", "orgao": "Terceira Seção", "data": "13/09/2017"}, {"tribunal": "STJ", "n": "588", "texto": "A prática de crime ou contravenção penal contra a mulher com violência ou grave ameaça no ambiente doméstico impossibilita a substituição da pena privativa de liberdade por restritiva de direitos.", "vinculante": false, "materia": "Direito Penal – Lei Maria da Penha", "orgao": "Terceira Seção", "data": "13/09/2017"}, {"tribunal": "STJ", "n": "589", "texto": "É inaplicável o princípio da insignificância nos crimes ou contravenções penais praticados contra a mulher no âmbito das relações domésticas.", "vinculante": false, "materia": "Direito Penal – Lei Maria da Penha", "orgao": "Terceira Seção", "data": "13/09/2017"}, {"tribunal": "STJ", "n": "590", "texto": "Constitui acréscimo patrimonial a atrair a incidência do imposto de renda, em caso de liquidação de entidade de previdência privada, a quantia que couber a cada participante, por rateio do patrimônio, superior ao valor das respectivas contribuições à entidade em liquidação, devidamente atualizadas e corrigidas.", "vinculante": false, "materia": "Direito Tributário – Imposto de Renda", "orgao": "Primeira Seção", "data": "13/09/2017"}, {"tribunal": "STJ", "n": "591", "texto": "É permitida a \"prova emprestada\" no processo administrativo disciplinar, desde que devidamente autorizada pelo juízo competente e respeitados o contraditório e a ampla defesa.", "vinculante": false, "materia": "Direito Administrativo – Processo Administrativo Disciplinar", "orgao": "Primeira Seção", "data": "13/09/2017"}, {"tribunal": "STJ", "n": "592", "texto": "O excesso de prazo para a conclusão do processo administrativo disciplinar só causa nulidade se houver demonstração de prejuízo à defesa.", "vinculante": false, "materia": "Direito Administrativo – Processo Administrativo Disciplinar", "orgao": "Primeira Seção", "data": "13/09/2017"}, {"tribunal": "STJ", "n": "593", "texto": "O crime de estupro de vulnerável se configura com a conjunção carnal ou prática de ato libidinoso com menor de 14 anos, sendo irrelevante eventual consentimento da vítima para a prática do ato, sua experiência sexual anterior ou existência de relacionamento amoroso com o agente.", "vinculante": false, "materia": "Direito Penal – Estupro de Vulnerável", "orgao": "Terceira Seção", "data": "25/10/2017"}, {"tribunal": "STJ", "n": "594", "texto": "O Ministério Público tem legitimidade ativa para ajuizar ação de alimentos em proveito de criança ou adolescente independentemente do exercício do poder familiar dos pais, ou do fato de o menor se encontrar nas situações de risco descritas no art. 98 do Estatuto da Criança e do Adolescente, ou de quaisquer outros questionamentos acerca da existência ou eficiência da Defensoria Pública na comarca.", "vinculante": false, "materia": "Direito Processual Civil – Legitimidade", "orgao": "Segunda Seção", "data": "25/10/2017"}, {"tribunal": "STJ", "n": "595", "texto": "As instituições de ensino superior respondem objetivamente pelos danos suportados pelo aluno/consumidor pela realização de curso não reconhecido pelo Ministério da Educação, sobre o qual não lhe tenha sido dada prévia e adequada informação.", "vinculante": false, "materia": "Direito do Consumidor – Responsabilidade Objetiva", "orgao": "Segunda Seção", "data": "25/10/2017"}, {"tribunal": "STJ", "n": "596", "texto": "A obrigação alimentar dos avós tem natureza complementar e subsidiária, somente se configurando no caso de impossibilidade total ou parcial de seu cumprimento pelos pais.", "vinculante": false, "materia": "Direito Civil – Alimentos", "orgao": "Segunda Seção", "data": "08/11/2017"}, {"tribunal": "STJ", "n": "597", "texto": "A cláusula contratual de plano de saúde que prevê carência para utilização dos serviços de assistência médica nas situações de emergência ou de urgência é considerada abusiva se ultrapassado o prazo máximo de 24 horas contado da data da contratação.", "vinculante": false, "materia": "Direito do Consumidor – Plano de Saúde", "orgao": "Segunda Seção", "data": "08/11/2017"}, {"tribunal": "STJ", "n": "598", "texto": "É desnecessária a apresentação de laudo médico oficial para o reconhecimento judicial da isenção do imposto de renda, desde que o magistrado entenda suficientemente demonstrada a doença grave por outros meios de prova.", "vinculante": false, "materia": "Direito Tributário – Imposto de Renda", "orgao": "Primeira Seção", "data": "08/11/2017"}, {"tribunal": "STJ", "n": "599", "texto": "O princípio da insignificância é inaplicável aos crimes contra a administração pública.", "vinculante": false, "materia": "Direito Penal – Crimes Contra a Administração Pública", "orgao": "Corte Especial", "data": "20/11/2017"}, {"tribunal": "STJ", "n": "600", "texto": "Para a configuração da violência doméstica e familiar prevista no artigo 5º da Lei n. 11.340/2006 (Lei Maria da Penha) não se exige a coabitação entre autor e vítima.", "vinculante": false, "materia": "Direito Penal – Lei Maria da Penha", "orgao": "Terceira Seção", "data": "22/11/2017"}, {"tribunal": "STJ", "n": "601", "texto": "O Ministério Público tem legitimidade ativa para atuar na defesa de direitos difusos, coletivos e individuais homogêneos dos consumidores, ainda que decorrentes da prestação de serviço público.", "vinculante": false, "materia": "Direito do Consumidor – Legitimidade do Ministério Público", "orgao": "Corte Especial", "data": "07/02/2018"}, {"tribunal": "STJ", "n": "602", "texto": "O Código de Defesa do Consumidor é aplicável aos empreendimentos habitacionais promovidos pelas sociedades cooperativas.", "vinculante": false, "materia": "Direito do Consumidor – Aplicabilidade do Código de Defesa do Consumidor", "orgao": "Segunda Seção", "data": "22/02/2018"}, {"tribunal": "STJ", "n": "603", "texto": "É vedado ao banco mutuante reter, em qualquer extensão, os salários, vencimentos e/ou proventos de correntista para adimplir o mútuo (comum) contraído, ainda que haja cláusula contratual autorizativa, excluído o empréstimo garantido por margem salarial consignável, com desconto em folha de pagamento, que possui regramento legal específico e admite a retenção de percentual. A Segunda Seção, na sessão de 22 de agosto de 2018, ao julgar o REsp 1.555.722-SP, determinou o CANCELAMENTO da Súmula n. 603-STJ.", "vinculante": false, "materia": "Direito Bancário – Contrato Bancário", "orgao": "Segunda Seção", "data": "22/02/2018"}, {"tribunal": "STJ", "n": "604", "texto": "O mandado de segurança não se presta para atribuir efeito suspensivo a recurso criminal interposto pelo Ministério Público.", "vinculante": false, "materia": "Direito Processual Penal – Recursos", "orgao": "Terceira Seção", "data": "28/02/2018"}, {"tribunal": "STJ", "n": "605", "texto": "A superveniência da maioridade penal não interfere na apuração de ato infracional nem na aplicabilidade de medida socioeducativa em curso, inclusive na liberdade assistida, enquanto não atingida a idade de 21 anos.", "vinculante": false, "materia": "Direito Penal – Estatuto da Criança e Do Adolescente", "orgao": "Terceira Seção", "data": "14/03/2018"}, {"tribunal": "STJ", "n": "606", "texto": "Não se aplica o princípio da insignificância a casos de transmissão clandestina de sinal de internet via radiofrequência, que caracteriza o fato típico previsto no art. 183 da Lei n. 9.472/1997.", "vinculante": false, "materia": "Direito Penal – Princípio da Insignificância", "orgao": "Terceira Seção", "data": "11/04/2018"}, {"tribunal": "STJ", "n": "607", "texto": "A majorante do tráfico transnacional de drogas (art. 40, I, da Lei n. 11.343/2006) configura-se com a prova da destinação internacional das drogas, ainda que não consumada a transposição de fronteiras.", "vinculante": false, "materia": "Direito Penal – das Penas", "orgao": "Terceira Seção", "data": "11/04/2018"}, {"tribunal": "STJ", "n": "608", "texto": "Aplica-se o Código de Defesa do Consumidor aos contratos de plano de saúde, salvo os administrados por entidades de autogestão.", "vinculante": false, "materia": "Direito do Consumidor – Plano de Saúde", "orgao": "Segunda Seção", "data": "11/04/2018"}, {"tribunal": "STJ", "n": "609", "texto": "A recusa de cobertura securitária, sob a alegação de doença preexistente, é ilícita se não houve a exigência de exames médicos prévios à contratação ou a demonstração de má-fé do segurado.", "vinculante": false, "materia": "Direito do Consumidor – Plano de Saúde", "orgao": "Segunda Seção", "data": "11/04/2018"}, {"tribunal": "STJ", "n": "610", "texto": "O suicídio não é coberto nos dois primeiros anos de vigência do contrato de seguro de vida, ressalvado o direito do beneficiário à devolução do montante da reserva técnica formada.", "vinculante": false, "materia": "Direito Civil – Contrato de Seguro", "orgao": "Segunda Seção", "data": "25/04/2018"}, {"tribunal": "STJ", "n": "611", "texto": "Desde que devidamente motivada e com amparo em investigação ou sindicância, é permitida a instauração de processo administrativo disciplinar com base em denúncia anônima, em face do poder-dever de autotutela imposto à Administração.", "vinculante": false, "materia": "Direito Administrativo – Processo Administrativo Disciplinar", "orgao": "Primeira Seção", "data": "09/05/2018"}, {"tribunal": "STJ", "n": "612", "texto": "O certificado de entidade beneficente de assistência social (CEBAS), no prazo de sua validade, possui natureza declaratória para fins tributários, retroagindo seus efeitos à data em que demonstrado o cumprimento dos requisitos estabelecidos por lei complementar para a fruição da imunidade.", "vinculante": false, "materia": "Direito Tributário – Imunidade Tributária", "orgao": "Primeira Seção", "data": "09/05/2018"}, {"tribunal": "STJ", "n": "613", "texto": "Não se admite a aplicação da teoria do fato consumado em tema de Direito Ambiental.", "vinculante": false, "materia": "Direito Ambiental – Dano Ambiental", "orgao": "Primeira Seção", "data": "09/05/2018"}, {"tribunal": "STJ", "n": "614", "texto": "O locatário não possui legitimidade ativa para discutir a relação jurídico-tributária de IPTU e de taxas referentes ao imóvel alugado nem para repetir indébito desses tributos.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre a Propriedade Predial e Territorial Urbana", "orgao": "Primeira Seção", "data": "09/05/2018"}, {"tribunal": "STJ", "n": "615", "texto": "Não pode ocorrer ou permanecer a inscrição do município em cadastros restritivos fundada em irregularidades na gestão anterior quando, na gestão sucessora, são tomadas as providências cabíveis à reparação dos danos eventualmente cometidos.", "vinculante": false, "materia": "Direito Administrativo – Inscricão em Cadastros Restritivos", "orgao": "Primeira Seção", "data": "09/05/2018"}, {"tribunal": "STJ", "n": "616", "texto": "A indenização securitária é devida quando ausente a comunicação prévia do segurado acerca do atraso no pagamento do prêmio, por constituir requisito essencial para a suspensão ou resolução do contrato de seguro.", "vinculante": false, "materia": "Direito Civil – Contrato de Seguro", "orgao": "Segunda Seção", "data": "23/05/2018"}, {"tribunal": "STJ", "n": "617", "texto": "A ausência de suspensão ou revogação do livramento condicional antes do término do período de prova enseja a extinção da punibilidade pelo integral cumprimento da pena.", "vinculante": false, "materia": "Direito Penal – Execução Penal", "orgao": "Terceira Seção", "data": "26/09/2018"}, {"tribunal": "STJ", "n": "618", "texto": "A inversão do ônus da prova aplica-se às ações de degradação ambiental.", "vinculante": false, "materia": "Direito Ambiental – Dano Ambiental", "orgao": "Corte Especial", "data": "24/10/2018"}, {"tribunal": "STJ", "n": "619", "texto": "A ocupação indevida de bem público configura mera detenção, de natureza precária, insuscetível de retenção ou indenização por acessões e benfeitorias.", "vinculante": false, "materia": "Direito Administrativo – Bem Público", "orgao": "Corte Especial", "data": "24/10/2018"}, {"tribunal": "STJ", "n": "620", "texto": "A embriaguez do segurado não exime a seguradora do pagamento da indenização prevista em contrato de seguro de vida.", "vinculante": false, "materia": "Direito Civil – Contrato de Seguro", "orgao": "Segunda Seção", "data": "12/12/2018"}, {"tribunal": "STJ", "n": "621", "texto": "Os efeitos da sentença que reduz, majora ou exonera o alimentante do pagamento retroagem à data da citação, vedadas a compensação e a repetibilidade.", "vinculante": false, "materia": "Direito Civil – Alimentos", "orgao": "Segunda Seção", "data": "12/12/2018"}, {"tribunal": "STJ", "n": "622", "texto": "A notificação do auto de infração faz cessar a contagem da decadência para a constituição do crédito tributário; exaurida a instância administrativa com o decurso do prazo para a impugnação ou com a notificação de seu julgamento definitivo e esgotado o prazo concedido pela Administração para o pagamento voluntário, inicia-se o prazo prescricional para a cobrança judicial.", "vinculante": false, "materia": "Direito Tributário – Crédito Tributário", "orgao": "Primeira Seção", "data": "12/12/2018"}, {"tribunal": "STJ", "n": "623", "texto": "As obrigações ambientais possuem natureza propter rem, sendo admissível cobrá-las do proprietário ou possuidor atual e/ou dos anteriores, à escolha do credor.", "vinculante": false, "materia": "Direito Ambiental – Dano Ambiental", "orgao": "Primeira Seção", "data": "12/12/2018"}, {"tribunal": "STJ", "n": "624", "texto": "É possível cumular a indenização do dano moral com a reparação econômica da Lei n. 10.559/2002 (Lei da Anistia Política).", "vinculante": false, "materia": "Direito Administrativo – Anistia Política", "orgao": "Primeira Seção", "data": "12/12/2018"}, {"tribunal": "STJ", "n": "625", "texto": "O pedido administrativo de compensação ou de restituição não interrompe o prazo prescricional para a ação de repetição de indébito tributário de que trata o art. 168 do CTN nem o da execução de título judicial contra a Fazenda Pública.", "vinculante": false, "materia": "Direito Tributário – Repetição de Indébito", "orgao": "Primeira Seção", "data": "12/12/2018"}, {"tribunal": "STJ", "n": "626", "texto": "A incidência do IPTU sobre imóvel situado em área considerada pela lei local como urbanizável ou de expansão urbana não está condicionada à existência dos melhoramentos elencados no art. 32, § 1º, do CTN.", "vinculante": false, "materia": "Direito Tributário – Imposto Sobre a Propriedade Predial e Territorial Urbana", "orgao": "Primeira Seção", "data": "12/12/2018"}, {"tribunal": "STJ", "n": "627", "texto": "O contribuinte faz jus à concessão ou à manutenção da isenção do imposto de renda, não se lhe exigindo a demonstração da contemporaneidade dos sintomas da doença nem da recidiva da enfermidade.", "vinculante": false, "materia": "Direito Tributário – Imposto de Renda", "orgao": "Primeira Seção", "data": "12/12/2018"}, {"tribunal": "STJ", "n": "628", "texto": "A teoria da encampação é aplicada no mandado de segurança quando presentes, cumulativamente, os seguintes requisitos: a) existência de vínculo hierárquico entre a autoridade que prestou informações e a que ordenou a prática do ato impugnado; b) manifestação a respeito do mérito nas informações prestadas; e c) ausência de modificação de competência estabelecida na Constituição Federal.", "vinculante": false, "materia": "Direito Processual Civil – Teoria da Encampação", "orgao": "Primeira Seção", "data": "12/12/2018"}, {"tribunal": "STJ", "n": "629", "texto": "Quanto ao dano ambiental, é admitida a condenação do réu à obrigação de fazer ou à de não fazer cumulada com a de indenizar.", "vinculante": false, "materia": "Direito Ambiental – Dano Ambiental", "orgao": "Primeira Seção", "data": "12/12/2018"}, {"tribunal": "STJ", "n": "630", "texto": "A incidência da atenuante da confissão espontânea no crime de tráfico ilícito de entorpecentes exige o reconhecimento da traficância pelo acusado, não bastando a mera admissão da posse ou propriedade para uso próprio.", "vinculante": false, "materia": "Direito Penal – das Penas", "orgao": "Terceira Seção", "data": "24/04/2019"}, {"tribunal": "STJ", "n": "631", "texto": "O indulto extingue os efeitos primários da condenação (pretensão executória), mas não atinge os efeitos secundários, penais ou extrapenais.", "vinculante": false, "materia": "Direito Penal – Execução Penal", "orgao": "Terceira Seção", "data": "24/04/2019"}, {"tribunal": "STJ", "n": "632", "texto": "Nos contratos de seguro regidos pelo Código Civil, a correção monetária sobre a indenização securitária incide a partir da contratação até o efetivo pagamento.", "vinculante": false, "materia": "Direito Civil – Contrato de Seguro", "orgao": "Segunda Seção", "data": "08/05/2019"}, {"tribunal": "STJ", "n": "633", "texto": "A Lei n. 9.784/1999, especialmente no que diz respeito ao prazo decadencial para a revisão de atos administrativos no âmbito da Administração Pública federal, pode ser aplicada, de forma subsidiária, aos estados e municípios, se inexistente norma local e específica que regule a matéria.", "vinculante": false, "materia": "Direito Administrativo – Prescrição e Decadência", "orgao": "Primeira Seção", "data": "12/06/2019"}, {"tribunal": "STJ", "n": "634", "texto": "Ao particular aplica-se o mesmo regime prescricional previsto na Lei de Improbidade Administrativa para o agente público.", "vinculante": false, "materia": "Direito Administrativo – Improbidade Administrativa", "orgao": "Primeira Seção", "data": "12/06/2019"}, {"tribunal": "STJ", "n": "635", "texto": "Os prazos prescricionais previstos no art. 142 da Lei n. 8.112/1990 iniciam-se na data em que a autoridade competente para a abertura do procedimento administrativo toma conhecimento do fato, interrompem-se com o primeiro ato de instauração válido - sindicância de caráter punitivo ou processo disciplinar - e voltam a fluir por inteiro, após decorridos 140 dias desde a interrupção.", "vinculante": false, "materia": "Direito Administrativo – Processo Administrativo Disciplinar", "orgao": "Primeira Seção", "data": "12/06/2019"}, {"tribunal": "STJ", "n": "636", "texto": "A folha de antecedentes criminais é documento suficiente a comprovar os maus antecedentes e a reincidência.", "vinculante": false, "materia": "Direito Penal – das Penas", "orgao": "Terceira Seção", "data": "26/06/2019"}, {"tribunal": "STJ", "n": "637", "texto": "O ente público detém legitimidade e interesse para intervir, incidentalmente, na ação possessória entre particulares, podendo deduzir qualquer matéria defensiva, inclusive, se for o caso, o domínio.", "vinculante": false, "materia": "Direito Processual Civil – Ação Possessória", "orgao": "Corte Especial", "data": "06/11/2019"}, {"tribunal": "STJ", "n": "638", "texto": "É abusiva a cláusula contratual que restringe a responsabilidade de instituição financeira pelos danos decorrentes de roubo, furto ou extravio de bem entregue em garantia no âmbito de contrato de penhor civil.", "vinculante": false, "materia": "Direito do Consumidor – Instituições Financeiras", "orgao": "Segunda Seção", "data": "27/11/2019"}, {"tribunal": "STJ", "n": "639", "texto": "Não fere o contraditório e o devido processo decisão que, sem ouvida prévia da defesa, determine transferência ou permanência de custodiado em estabelecimento penitenciário federal.", "vinculante": false, "materia": "Direito Processual Penal – Execução Penal", "orgao": "Terceira Seção", "data": "27/11/2019"}, {"tribunal": "STJ", "n": "640", "texto": "O benefício fiscal que trata do Regime Especial de Reintegração de Valores Tributários para as Empresas Exportadoras (REINTEGRA) alcança as operações de venda de mercadorias de origem nacional para a Zona Franca de Manaus, para consumo, industrialização ou reexportação para o estrangeiro.", "vinculante": false, "materia": "Direito Tributário – Benefícios Fiscais", "orgao": "Primeira Seção", "data": "18/02/2020"}, {"tribunal": "STJ", "n": "641", "texto": "A portaria de instauração do processo administrativo disciplinar prescinde da exposição detalhada dos fatos a serem apurados.", "vinculante": false, "materia": "Direito Administrativo – Processo Administrativo Disciplinar", "orgao": "Primeira Seção", "data": "18/02/2020"}, {"tribunal": "STJ", "n": "642", "texto": "O direito à indenização por danos morais transmite-se com o falecimento do titular, possuindo os herdeiros da vítima legitimidade ativa para ajuizar ou prosseguir a ação indenizatória.", "vinculante": false, "materia": "Direito Civil – Dano Moral", "orgao": "Corte Especial", "data": "02/12/2020"}, {"tribunal": "STJ", "n": "643", "texto": "A execução da pena restritiva de direitos depende do trânsito em julgado da condenação.", "vinculante": false, "materia": "Direito Penal – Execução Penal", "orgao": "Terceira Seção", "data": "10/02/2021"}, {"tribunal": "STJ", "n": "644", "texto": "O núcleo de prática jurídica deve apresentar o instrumento de mandato quando constituído pelo réu hipossuficiente, salvo nas hipóteses em que é nomeado pelo juízo.", "vinculante": false, "materia": "Direito Processual Penal – Representação Processual", "orgao": "Terceira Seção", "data": "10/02/2021"}, {"tribunal": "STJ", "n": "645", "texto": "O crime de fraude à licitação é formal, e sua consumação prescinde da comprovação do prejuízo ou da obtenção de vantagem.", "vinculante": false, "materia": "Direito Penal – Fraude À Licitação", "orgao": "Terceira Seção", "data": "10/02/2021"}, {"tribunal": "STJ", "n": "646", "texto": "É irrelevante a natureza da verba trabalhista para fins de incidência da contribuição ao FGTS, visto que apenas as verbas elencadas em lei (art. 28, § 9º, da Lei n. 8.212/1991), em rol taxativo, estão excluídas da sua base de cálculo, por força do disposto no art. 15, § 6º, da Lei n. 8.036/1990.", "vinculante": false, "materia": "", "orgao": "Primeira Seção", "data": "10/03/2021"}, {"tribunal": "STJ", "n": "647", "texto": "São imprescritíveis as ações indenizatórias por danos morais e materiais decorrentes de atos de perseguição política com violação de direitos fundamentais ocorridos durante o regime militar.", "vinculante": false, "materia": "", "orgao": "Primeira Seção", "data": "10/03/2021"}, {"tribunal": "STJ", "n": "648", "texto": "A superveniência da sentença condenatória prejudica o pedido de trancamento da ação penal por falta de justa causa feito em habeas corpus.", "vinculante": false, "materia": "Direito Processual Penal – Ação Penal", "orgao": "Terceira Seção", "data": "14/04/2021"}, {"tribunal": "STJ", "n": "649", "texto": "Não incide ICMS sobre o serviço de transporte interestadual de mercadorias destinadas ao exterior.", "vinculante": false, "materia": "", "orgao": "Primeira Seção", "data": "28/04/2021"}]);
